async function handleEmailCampaignUpdate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const id=parseInt(body.Id,10);
  if(!id) return json({error:'Id required'}, 400);
  const tableId=await emailResolveTable(env, payload.cid, 'campaigns');
  if(!tableId) return json({error:'Email campaigns table not configured'}, 400);
  const existingR=await ncFetch(env, `api/v2/tables/${tableId}/records/${id}`);
  const existing=await existingR.json().catch(()=>null);
  if(!existingR.ok||!existing||String(existing.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  if(existing.status!=='draft') return json({error:'Only draft campaigns can be edited'}, 400);
  const fields={};
  ['subject','html_body'].forEach(k=>{ if(k in body) fields[k]=body[k]; });
  if('segment_filter' in body) fields.segment_filter=JSON.stringify(body.segment_filter||{});
  const r=await ncFetch(env, `api/v2/tables/${tableId}/records`, {method:'PATCH', body:{Id:id, ...fields}});
  const data=await r.json().catch(()=>({}));
  return json(data, r.status);
}

async function handleEmailCampaignDelete(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const id=parseInt(body.Id,10);
  if(!id) return json({error:'Id required'}, 400);
  const tableId=await emailResolveTable(env, payload.cid, 'campaigns');
  if(!tableId) return json({error:'Email campaigns table not configured'}, 400);
  const existingR=await ncFetch(env, `api/v2/tables/${tableId}/records/${id}`);
  const existing=await existingR.json().catch(()=>null);
  if(!existingR.ok||!existing||String(existing.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  // Deleting a sending/sent campaign would orphan its EmailSends history — drafts only.
  if(existing.status!=='draft') return json({error:'Only draft campaigns can be deleted'}, 400);
  const r=await ncFetch(env, `api/v2/tables/${tableId}/records`, {method:'DELETE', body:{Id:id}});
  const data=await r.json().catch(()=>({}));
  return json(data, r.status);
}

async function handleEmailAudiencePreview(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const url=new URL(request.url);
  let segmentFilter={};
  try{ segmentFilter=JSON.parse(url.searchParams.get('segment_filter')||'{}'); }catch(e){}
  const where=emailAudienceWhereClause(payload.cid, segmentFilter);
  const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}&limit=5&fields=Id,Name,Email`);
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json(data, r.status);
  // NocoDB's standard list response already includes pageInfo.totalRows for the given where
  // clause, regardless of the page's own limit — no separate count call needed.
  return json({count:data?.pageInfo?.totalRows??(data.list||[]).length, sample:(data.list||[]).slice(0,5)});
}

async function handleEmailCampaignSendInit(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const campaignId=parseInt(body.campaign_id,10);
  if(!campaignId) return json({error:'campaign_id required'}, 400);
  const campaignsTable=await emailResolveTable(env, payload.cid, 'campaigns');
  const sendsTable=await emailResolveTable(env, payload.cid, 'sends');
  if(!campaignsTable||!sendsTable) return json({error:'Email tables not configured'}, 400);

  const campR=await ncFetch(env, `api/v2/tables/${campaignsTable}/records/${campaignId}`);
  const campaign=await campR.json().catch(()=>null);
  if(!campR.ok||!campaign||String(campaign.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  if(campaign.status!=='draft') return json({error:'Campaign already sent or sending'}, 400);

  let segmentFilter={}; try{ segmentFilter=JSON.parse(campaign.segment_filter||'{}'); }catch(e){}
  const where=emailAudienceWhereClause(payload.cid, segmentFilter);
  const leadsR=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}&limit=1000&fields=Id,Email`);
  const leadsData=await leadsR.json().catch(()=>({}));
  const leads=leadsData.list||[];
  if(!leads.length) return json({error:'No eligible recipients for this segment'}, 400);

  const CHUNK=40; // matches handleEcomDelete's bulk-write chunk size — NocoDB rejects overly large bulk arrays with a 422
  const rows=leads.map(l=>({client_id:payload.cid, campaign_id:campaignId, lead_id:l.Id, recipient_email:l.Email, status:'queued'}));
  const sendIds=[];
  for(let i=0;i<rows.length;i+=CHUNK){
    const r=await ncFetch(env, `api/v2/tables/${sendsTable}/records`, {method:'POST', body:rows.slice(i,i+CHUNK)});
    const created=await r.json().catch(()=>[]);
    // NocoDB's bulk-insert response is an array of the created rows (with their new Ids) —
    // the frontend needs these back so it has something concrete to loop send-one calls over.
    (Array.isArray(created)?created:[]).forEach(row=>{ if(row?.Id) sendIds.push(row.Id); });
  }
  await ncFetch(env, `api/v2/tables/${campaignsTable}/records`, {method:'PATCH', body:{Id:campaignId, status:'sending', total_recipients:leads.length}});
  return json({ok:true, total_recipients:leads.length, send_ids:sendIds});
}

async function handleEmailCampaignSendOne(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const sendId=parseInt(body.send_id,10);
  if(!sendId) return json({error:'send_id required'}, 400);
  const sendsTable=await emailResolveTable(env, payload.cid, 'sends');
  const campaignsTable=await emailResolveTable(env, payload.cid, 'campaigns');
  if(!sendsTable||!campaignsTable) return json({error:'Email tables not configured'}, 400);

  const sendR=await ncFetch(env, `api/v2/tables/${sendsTable}/records/${sendId}`);
  const sendRow=await sendR.json().catch(()=>null);
  if(!sendR.ok||!sendRow||String(sendRow.client_id)!==String(payload.cid)) return json({error:'Not found'}, 404);
  if(sendRow.status!=='queued') return json({ok:true, skipped:true});

  // Defensive re-check — a long-running campaign send can overlap with a lead unsubscribing
  // partway through; send-init already filtered the audience, this is the last line of defense.
  const leadR=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records/${sendRow.lead_id}`);
  const lead=await leadR.json().catch(()=>null);
  if(leadR.ok && lead?.EmailOptOut==='Yes'){
    await ncFetch(env, `api/v2/tables/${sendsTable}/records`, {method:'PATCH', body:{Id:sendId, status:'failed', error:'Lead unsubscribed before send'}});
    return json({ok:true, skipped:true});
  }

  const campR=await ncFetch(env, `api/v2/tables/${campaignsTable}/records/${sendRow.campaign_id}`);
  const campaign=await campR.json().catch(()=>null);
  if(!campR.ok||!campaign) return json({error:'Campaign not found'}, 404);
  const c=await getClientById(env, payload.cid);

  const unsubToken=await hmacHex(env, `unsub:${sendRow.lead_id}`);
  const unsubLink=`${new URL(request.url).origin}/email/unsubscribe?lead_id=${sendRow.lead_id}&token=${unsubToken}`;
  const html=`${campaign.html_body}<p style="font-size:11px;color:#888;margin-top:24px">Don't want these emails? <a href="${unsubLink}">Unsubscribe</a>.</p>`;

  const result=await sendClientResendEmail(c, {to:sendRow.recipient_email, subject:campaign.subject, html});
  if(result.ok){
    await ncFetch(env, `api/v2/tables/${sendsTable}/records`, {method:'PATCH', body:{Id:sendId, status:'sent', sent_at:new Date().toISOString()}});
    await ncFetch(env, `api/v2/tables/${campaignsTable}/records`, {method:'PATCH', body:{Id:sendRow.campaign_id, total_sent:(campaign.total_sent||0)+1}});
  }else{
    await ncFetch(env, `api/v2/tables/${sendsTable}/records`, {method:'PATCH', body:{Id:sendId, status:'failed', error:result.error}});
    await ncFetch(env, `api/v2/tables/${campaignsTable}/records`, {method:'PATCH', body:{Id:sendRow.campaign_id, total_failed:(campaign.total_failed||0)+1}});
  }
  return json(result);
}

// Stateless HMAC helper, reusing SESSION_SIGNING_KEY with a domain-separation prefix rather than
// provisioning a new secret — same crypto.subtle HMAC pattern as signSession/verifySession.
async function hmacHex(env, message){
  const key=await crypto.subtle.importKey('raw', new TextEncoder().encode(env.SESSION_SIGNING_KEY), {name:'HMAC', hash:'SHA-256'}, false, ['sign']);
  const sig=await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(message));
  return hex(sig);
}

async function handleEmailUnsubscribe(request, env){
  const url=new URL(request.url);
  const leadId=parseInt(url.searchParams.get('lead_id'),10);
  const token=url.searchParams.get('token')||'';
  if(!leadId||!token) return new Response('Invalid unsubscribe link.', {status:400});
  const expected=await hmacHex(env, `unsub:${leadId}`);
  if(expected.length!==token.length) return new Response('Invalid unsubscribe link.', {status:400});
  let diff=0;
  for(let i=0;i<expected.length;i++) diff|=expected.charCodeAt(i)^token.charCodeAt(i);
  if(diff!==0) return new Response('Invalid unsubscribe link.', {status:400});
  await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'PATCH', body:{Id:leadId, EmailOptOut:'Yes'}});
  return new Response('<!doctype html><html><body style="font-family:sans-serif;text-align:center;padding:60px 20px"><h2>You\'ve been unsubscribed</h2><p>You won\'t receive any more marketing emails from us.</p></body></html>', {status:200, headers:{'Content-Type':'text/html'}});
}

// ── HEALTH CHECKS (Integrations tab — on-demand "Run Check Now" and once-daily Cron Trigger) ──
// Every check here is read-only and cheap by design, since the daily run fires unattended for
// every client: it only confirms a credential/config still works, it never sends a real
// message/email. "Send yourself a test message" stays a manual, on-demand action elsewhere in
// the Integrations tab, not something this loop does automatically.
function sheetCsvUrl(sheetUrl){
  const m=String(sheetUrl||'').match(/spreadsheets\/d\/([a-zA-Z0-9-_]+)/);
  if(!m) return null;
  const gidMatch=String(sheetUrl).match(/[#&?]gid=(\d+)/);
  return `https://docs.google.com/spreadsheets/d/${m[1]}/export?format=csv${gidMatch?'&gid='+gidMatch[1]:''}`;
}

async function checkSheet(url){
  if(!url) return {status:'warn', detail:'Not configured'};
  const csvUrl=sheetCsvUrl(url);
  if(!csvUrl) return {status:'fail', detail:'Not a recognizable Google Sheets URL'};
  try{
    const r=await fetch(csvUrl, {redirect:'follow'});
    const text=await r.text();
    if(!r.ok) return {status:'fail', detail:'HTTP '+r.status+' — check sharing is set to "Anyone with the link can view"'};
    if(/<html/i.test(text.slice(0,200))) return {status:'fail', detail:'Sheet is not publicly viewable — check sharing settings'};
    if(!text.trim()) return {status:'warn', detail:'Sheet is empty'};
    return {status:'ok', detail:Math.max(text.trim().split('\n').length-1,0)+' row(s)'};
  }catch(e){ return {status:'fail', detail:e.message||'Fetch failed'}; }
}

const HEALTH_CHECKS=[
  { key:'whatsapp', label:'WhatsApp (Meta)', category:'integration', fn: async (env,c)=>{
    if(!c.wa_phone_id||!c.wa_token) return {status:'warn', detail:'Not connected'};
    const r=await fetch(`https://graph.facebook.com/v18.0/${c.wa_phone_id}?fields=display_phone_number,quality_rating`, {headers:{Authorization:`Bearer ${c.wa_token}`}});
    const data=await r.json().catch(()=>({}));
    if(!r.ok) return {status:'fail', detail:data?.error?.message||'HTTP '+r.status};
    if(data.quality_rating==='RED') return {status:'warn', detail:'Connected, but number quality rating is RED'};
    return {status:'ok', detail:data.display_phone_number||'Connected'};
  }},
  { key:'resend', label:'Resend (Email)', category:'integration', fn: async (env,c)=>{
    if(!c.resend_api_key) return {status:'warn', detail:'Not connected'};
    const r=await fetch('https://api.resend.com/domains', {headers:{Authorization:`Bearer ${c.resend_api_key}`}});
    if(!r.ok) return {status:'fail', detail:r.status===401?'API key invalid or revoked':'HTTP '+r.status};
    const data=await r.json().catch(()=>({}));
    const verified=(data?.data||[]).some(d=>d.status==='verified');
    return {status:verified?'ok':'warn', detail:verified?'Domain verified':'Connected, but no verified sending domain yet'};
  }},
  { key:'chatwoot', label:'Chatwoot', category:'integration', fn: async (env,c)=>{
    if(!c.chatwoot_base||!c.chatwoot_account_id||!c.chatwoot_token) return {status:'warn', detail:'Not connected'};
    const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes`, {headers:{api_access_token:c.chatwoot_token}});
    if(!r.ok) return {status:'fail', detail:'HTTP '+r.status};
    return {status:'ok', detail:'Connected'};
  }},
  { key:'sheet_leads', label:'Google Sheet — Leads Export', category:'sheets', fn: async (env,c)=>checkSheet(c.gsheet_url) },
  { key:'sheet_prospect', label:'Google Sheet — Prospect Import', category:'sheets', fn: async (env,c)=>checkSheet(c.prospect_gsheet_url) },
  { key:'sheet_ecom_products', label:'Google Sheet — Ecom Products', category:'sheets', fn: async (env,c)=>checkSheet(c.ecom_products_sheet) },
  { key:'sheet_ecom_orders', label:'Google Sheet — Ecom Orders', category:'sheets', fn: async (env,c)=>checkSheet(c.ecom_orders_sheet) },
  { key:'recovery_engine', label:'Follow-up Recovery Engine', category:'core', fn: async (env,c)=>{
    if(c.recovery_enabled==='No') return {status:'warn', detail:'Disabled for this account'};
    if(!c.recovery_heartbeat_at) return {status:'warn', detail:'Never run yet for this account'};
    const hrs=(Date.now()-new Date(c.recovery_heartbeat_at).getTime())/3600000;
    if(hrs>36) return {status:'fail', detail:'No heartbeat in '+Math.round(hrs)+'h — engine may be down'};
    return {status:'ok', detail:'Last run '+Math.round(hrs)+'h ago'};
  }},
  { key:'followup_config', label:'Follow-up Sequence Config', category:'core', fn: async (env,c)=>{
    const {results}=await env.DB.prepare(`SELECT step, type, message, template_name FROM followup_ladder_steps WHERE client_id=?`).bind(Number(c.Id)).all();
    if(!results||!results.length) return {status:'warn', detail:'Not configured'};
    const incomplete=(results||[]).filter(r=>(r.type==='session'&&!r.message)||(r.type==='template'&&!r.template_name)).length;
    if(incomplete) return {status:'fail', detail:`${incomplete} of ${results.length} step(s) missing a message/template`};
    return {status:'ok', detail:results.length+'-step ladder configured'};
  }},
];

async function runHealthChecks(env, client){
  const results=[];
  for(const check of HEALTH_CHECKS){
    let result;
    try{ result=await check.fn(env, client); }
    catch(e){ result={status:'fail', detail:e.message||'Check threw an error'}; }
    results.push({key:check.key, label:check.label, category:check.category, ...result});
  }
  return results;
}

function overallHealthStatus(results){
  if(results.some(r=>r.status==='fail')) return 'fail';
  if(results.some(r=>r.status==='warn')) return 'warn';
  return 'ok';
}

async function saveHealthResults(env, client, results){
  let log=[]; try{ log=JSON.parse(client.integration_health_log||'[]'); }catch(e){}
  log.push({ts:new Date().toISOString(), results});
  if(log.length>14) log=log.slice(-14); // ~2 weeks of daily runs
  await patchClientFields(env, client.Id, {
    integration_health_log: JSON.stringify(log),
    integration_health_status: overallHealthStatus(results),
    integration_health_checked_at: new Date().toISOString(),
  });
}

async function handleHealthRun(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  const results=await runHealthChecks(env, c);
  await saveHealthResults(env, c, results);
  return json({ok:true, status:overallHealthStatus(results), results, checked_at:new Date().toISOString()});
}

// Daily Cron Trigger entry point — see wrangler.toml [triggers]. Loops every client (paginated)
// instead of relying on each client's browser being open, so the check genuinely runs once a
// day for everyone, not just for whoever happens to visit Settings that day.
async function runDailyHealthCheckForAllClients(env){
  let page=1;
  while(true){
    const r=await ncFetch(env, `api/v2/tables/${CLIENTS_TABLE}/records?limit=200&offset=${(page-1)*200}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const rows=data?.list||[];
    if(!rows.length) break;
    for(const c of rows){
      try{
        const results=await runHealthChecks(env, c);
        await saveHealthResults(env, c, results);
      }catch(e){ console.error('[health] check failed for client', c.Id, e.message); }
    }
    if(rows.length<200) break;
    page++;
  }
}

// Instagram's long-lived token (handleInstagramOauthCallback) expires 60 days after issue and
// must be refreshed before then, or Instagram DM silently stops working with no user-visible
// warning. Piggybacked on the same daily 2am tick as the health check above — refreshing daily is
// wasteful (Meta docs say don't refresh more than once every 24h anyway) but harmless, and far
// simpler than tracking each client's exact expiry date. ig_connected_at is used only as a cheap
// "don't bother for a brand-new connection" guard, not an exact refresh schedule.
async function runInstagramTokenRefreshForAllClients(env){
  // No where-filter on ig_access_token (unlike the targeted queries elsewhere in this file) —
  // this runs once a day across every client regardless, same full-table walk
  // runDailyHealthCheckForAllClients uses, and the per-row skip below is cheap enough not to
  // need a narrower NocoDB query.
  let page=1;
  while(true){
    const r=await ncFetch(env, `api/v2/tables/${CLIENTS_TABLE}/records?limit=200&offset=${(page-1)*200}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const rows=data?.list||[];
    if(!rows.length) break;
    for(const c of rows){
      if(!c.ig_access_token) continue;
      try{
        const rr=await fetch(`https://graph.instagram.com/refresh_access_token?grant_type=ig_refresh_token&access_token=${encodeURIComponent(c.ig_access_token)}`);
        const rd=await rr.json().catch(()=>({}));
        if(rr.ok && rd.access_token) await patchClientFields(env, c.Id, {ig_access_token:rd.access_token});
        else console.error('[instagram] token refresh failed for client', c.Id, rd?.error?.message||rr.status);
      }catch(e){ console.error('[instagram] token refresh error for client', c.Id, e.message); }
    }
    if(rows.length<200) break;
    page++;
  }
}

// One-off/rerunnable admin action — walks every CLIENTS row and calls engineSyncChatwootWebhook
// for any client with Chatwoot already connected, so engine_webhook_secret gets generated and the
// /engine/webhook registration happens without each client needing to individually re-save a
// Settings field first. Safe to run repeatedly: engineSyncChatwootWebhook is itself idempotent
// (no-ops if already correct) and untouched for clients with no Chatwoot connection yet or with
// engine_disabled='Yes'. Does NOT touch Chatwoot's separate Agent Bots feature (Settings → Bots) —
// only the inbox-level Webhooks API; a bot wired there still needs its Webhook URL fixed by hand.
async function handleAdminBackfillEngineWebhooks(request, env){
  if(!await requireAdminSession(request, env)) return json({error:'Invalid or expired admin session'}, 401);
  let page=1, processed=0, synced=0, skipped=0;
  const errors=[];
  while(true){
    const r=await ncFetch(env, `api/v2/tables/${CLIENTS_TABLE}/records?limit=200&offset=${(page-1)*200}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const rows=data?.list||[];
    if(!rows.length) break;
    for(const c of rows){
      processed++;
      if(!c.chatwoot_base||!c.chatwoot_account_id||!c.chatwoot_token||!c.chatwoot_inbox_id){ skipped++; continue; }
      try{
        await engineSyncChatwootWebhook(env, c);
        synced++;
      }catch(e){ errors.push({client_id:c.Id, client_name:c.client_name||'', error:e.message}); }
    }
    if(rows.length<200) break;
    page++;
  }
  return json({ok:true, processed, synced, skipped, errors});
}

async function handleAiComplete(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {model, temperature, max_tokens, messages}=await request.json().catch(()=>({}));
  if(!Array.isArray(messages)||!messages.length) return json({error:'messages required'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  if(!env.GEMINI_API_KEY && !c.openrouter_key) return json({error:'No AI provider is configured on the server.'}, 503);

  // Shared Gemini is primary for every client. Preserve the OpenAI-compatible response shape
  // because dashboard callers already read choices[0].message.content.
  const systemText=messages.filter(m=>m?.role==='system').map(m=>String(m.content||'')).join('\n\n');
  const userText=messages.filter(m=>m?.role!=='system').map(m=>`${m.role||'user'}: ${String(m.content||'')}`).join('\n');
  const text=await engineGeminiGenerateWithFallback(env, c, systemText, userText, {
    model:model&&String(model).startsWith('gemini-')?model:undefined,
    temperature:temperature??0.3,
    maxOutputTokens:max_tokens||300
  });
  if(!text) return json({error:'All configured AI providers failed.'}, 502);
  return json({choices:[{message:{role:'assistant',content:text}}]});
}

// Business AI chat — natural language questions answered from a compact data snapshot the
// dashboard sends alongside the question. Never fetches raw PII; the frontend computes
// aggregates client-side and sends only the summary. Daily limit: 10 per user (email) per day,
// tracked in D1. All answers are grounded in the sent snapshot — AI cannot invent numbers.
async function handleAiBusinessChat(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const question=String(body.question||'').trim();
  const summary=body.summary||{};
  if(!question) return json({error:'question required'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  if(!env.GEMINI_API_KEY&&!c.openrouter_key) return json({error:'No AI provider configured.'}, 503);

  // Daily limit tracking per user email in D1
  const DAILY_LIMIT=10;
  const userKey=String(payload.email||payload.cid||'').toLowerCase()||String(payload.cid);
  const today=new Date().toISOString().slice(0,10);
  let usedToday=0;
  try{
    await env.DB.prepare(`CREATE TABLE IF NOT EXISTS ai_chat_usage (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      client_id INTEGER NOT NULL, user_key TEXT NOT NULL, date TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0,
      UNIQUE(client_id, user_key, date)
    )`).run().catch(()=>{});
    const row=await env.DB.prepare(`SELECT count FROM ai_chat_usage WHERE client_id=? AND user_key=? AND date=?`)
      .bind(Number(payload.cid), userKey, today).first().catch(()=>null);
    usedToday=Number(row?.count||0);
  }catch(e){}

  if(usedToday>=DAILY_LIMIT){
    return json({error:'daily_limit_reached', remaining:0, limit:DAILY_LIMIT}, 429);
  }

  // Build context from the summary the frontend sent (no PII, only aggregates)
  const ctx=[];
  if(summary.totalLeads!=null) ctx.push(`Total leads: ${summary.totalLeads}`);
  if(summary.newToday!=null)   ctx.push(`New leads today: ${summary.newToday}`);
  if(summary.hot!=null)        ctx.push(`Hot leads: ${summary.hot}`);
  if(summary.warm!=null)       ctx.push(`Warm leads: ${summary.warm}`);
  if(summary.converted!=null)  ctx.push(`Converted/booked: ${summary.converted}`);
  if(summary.convRate!=null)   ctx.push(`Conversion rate: ${summary.convRate}%`);
  if(summary.botPct!=null)     ctx.push(`Leads engaged by bot: ${summary.botPct}%`);
  if(summary.tasksOverdue!=null) ctx.push(`Overdue tasks: ${summary.tasksOverdue}`);
  if(summary.tasksDueToday!=null) ctx.push(`Tasks due today: ${summary.tasksDueToday}`);
  if(summary.newThisWeek!=null) ctx.push(`New leads this week: ${summary.newThisWeek}`);
  if(summary.stages&&typeof summary.stages==='object'){
    const top=Object.entries(summary.stages).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([s,n])=>`${s}:${n}`).join(', ');
    ctx.push(`Pipeline stages: ${top}`);
  }
  if(summary.sources&&typeof summary.sources==='object'){
    const top=Object.entries(summary.sources).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([s,n])=>`${s}:${n}`).join(', ');
    ctx.push(`Lead sources: ${top}`);
  }
  if(summary.agents&&typeof summary.agents==='object'){
    const top=Object.entries(summary.agents).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([s,n])=>`${s}:${n}`).join(', ');
    ctx.push(`Agents (leads handled): ${top}`);
  }

  const system=`You are a business intelligence assistant for "${String(c.client_name||'this business').slice(0,60)}" on Leadvyne CRM. Answer the user's question using ONLY the data snapshot below — never invent numbers, never reference data not shown. Keep answers concise, specific, and actionable. Use plain text with short bullet points where helpful. If the question cannot be answered from the snapshot, say so clearly and suggest what data would help.

BUSINESS DATA SNAPSHOT (today ${today}):
${ctx.length?ctx.join('\n'):'No data available yet.'}`;

  const answer=await engineGeminiGenerateWithFallback(env, c, system, question, {
    temperature:0.3, maxOutputTokens:350
  });
  if(!answer) return json({error:'AI generation failed.'}, 502);

  // Increment usage counter
  try{
    await env.DB.prepare(`INSERT INTO ai_chat_usage(client_id,user_key,date,count) VALUES(?,?,?,1)
      ON CONFLICT(client_id,user_key,date) DO UPDATE SET count=count+1`)
      .bind(Number(payload.cid), userKey, today).run();
  }catch(e){}

  const remaining=Math.max(0, DAILY_LIMIT-usedToday-1);
  return json({answer, remaining, limit:DAILY_LIMIT});
}

// Automation entry point for objection/trust-signal handling — meant to be called by the
// external n8n bot as ONE step inside its own reply flow (not an independent Chatwoot webhook
// listener), so n8n stays the single point of truth for what actually gets sent to the customer
// and there's no risk of two systems replying to the same message. Client_id-based like
// /ecom/order-link, since n8n has no Authentik session. Grounds its answer in the same
// business_policies/review_link data the dashboard's Trust Signals widget and Deal Coach already
// use — see SETUP.md's "Trust Signals & grounded objection-handling" section. Returns
// {handled:false} for anything that isn't an objection/trust question, so n8n's own flow can
// carry on normally — this never tries to handle a whole conversation turn, only this one
// narrow slice of it.
async function handleAiObjectionReply(request, env){
  const body=await request.json().catch(()=>({}));
  const clientId=String(body.client_id||'');
  const message=String(body.message||'').trim();
  if(!clientId||!message) return json({error:'client_id and message required'}, 400);
  const c=await getClientById(env, clientId);
  if(!c) return json({error:'Client not found'}, 404);
  if(!env.GEMINI_API_KEY && !c.openrouter_key) return json({error:'No AI provider is configured on the server.'}, 503);

  let pol={}; try{ pol=JSON.parse(c.business_policies||'{}'); }catch(e){}
  const policyLines=[];
  if(pol.refund) policyLines.push(`Refund policy: ${pol.refund}`);
  if(pol.delivery) policyLines.push(`Delivery policy: ${pol.delivery}`);
  if(pol.cancellation) policyLines.push(`Cancellation policy: ${pol.cancellation}`);
  const reviewLink=c.review_link||'';

  const system=`You are screening one incoming WhatsApp message for a business named "${c.client_name||'this business'}" to decide if it raises an objection or trust concern (refund, delivery, cancellation, pricing doubt, "is this legit" etc.) that can be answered directly from the policies below. If it does, write a short, natural, on-brand WhatsApp reply that answers it directly using the real policy text — quote the actual terms, never invent anything not listed. You may mention the review link if it genuinely strengthens trust. If the message is NOT an objection/trust question (a normal question, a greeting, an order request with no objection, etc.), respond with exactly {"handled":false}. Respond with ONLY valid JSON: {"handled":true,"reply":"..."} or {"handled":false}.

${policyLines.length?policyLines.join('\n'):'No policies configured yet — if the message is an objection you can\'t ground in a real policy, respond {"handled":false} rather than inventing one.'}
${reviewLink?`Review link: ${reviewLink}`:''}`;

  const raw=(await engineGeminiGenerateWithFallback(env, c, system, message, {
    temperature:0.3, maxOutputTokens:250, json:true
  }))||'{"handled":false}';
  let parsed={handled:false};
  try{ parsed=JSON.parse(raw); }catch(e){}
  return json({handled:!!parsed.handled, reply:parsed.handled?String(parsed.reply||'').trim():undefined});
}

// Fetches the last few messages on a Chatwoot conversation, formatted as plain "Customer: .../
// Bot: ..." lines — used to resolve short replies that carry no signal on their own, like "Order
// m size" or "the 30 min one", back to whichever specific product/service was actually being
// discussed. Without this, a detector looking only at the single incoming message has no way to
// connect "M size" to a product name it was never told — exactly the gap that let a real customer
// reply "Order m size" to a shown product and get "we don't have anything matching" back instead
// of an order link, because the classifier had no idea a product had just been shown at all.
// Assumes Chatwoot's messages-list response is oldest-first (`payload`, ascending by created_at) —
// the standard REST-list convention, but unverified against a live payload from this specific
// Chatwoot instance/version, same honest caveat as elsewhere this repo parses Chatwoot's API shape.
async function fetchRecentChatwootContext(c, conversationId, limit){
  if(!c.chatwoot_base||!c.chatwoot_account_id||!c.chatwoot_token||!conversationId) return '';
  try{
    const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${conversationId}/messages`, {headers:{api_access_token:c.chatwoot_token}});
    if(!r.ok) return '';
    const data=await r.json().catch(()=>({}));
    const msgs=(data?.payload||[]).slice(-limit);
    return msgs.map(m=>`${m.message_type==='incoming'?'Customer':'Bot'}: ${String(m.content||'').slice(0,300)}`).join('\n');
  }catch(e){ return ''; }
}

// Core detection logic, shared by the HTTP endpoint below (handleAiOrderSignal, for n8n to call)
// and handleChatwootIncomingOrderSignal's own direct auto-send path (no n8n involved — see that
// function for why). A "signal" isn't just an explicit "I want to buy X" — a specific-variant
// question (size, color, stock, price of one item) is just as strong a buying signal for a
// physical-goods business, so those count too. `contextText` (recent conversation, see
// fetchRecentChatwootContext above) is optional but important: it's what lets a bare reply like
// "M size" resolve back to whichever product was actually just shown, instead of matching nothing.
// When the model can confidently match to one product, `sku` comes back too. Never sends anything
// — purely a screen.
async function detectOrderSignal(env, c, clientId, message, contextText){
  if(!env.GEMINI_API_KEY && !c.openrouter_key) return {signal:false, error:'No AI provider configured.'};

  const productsTable=await ecomResolveTable(env, clientId, 'products');
  let productList='';
  let categoryList=[];
  if(productsTable){
    // Full rows keep this compatible with older Products tables where some optional style fields
    // do not exist yet; only fields actually present on each row are added to the classifier text.
    const pr=await ncFetch(env, `api/v2/tables/${productsTable}/records?where=(client_id,eq,${clientId})&limit=100`);
    const pd=await pr.json().catch(()=>({}));
    const products=pd?.list||[];
    productList=products.map(p=>`- ${p.name}${p.short_label?' short label:'+p.short_label:''}${p.sku?' [sku:'+p.sku+']':''}${p.category?' category:'+p.category:''}${p.brand?' brand:'+p.brand:''}${p.variant?' variant:'+p.variant:''}${p.style?' style:'+p.style:''}${p.color?' color:'+p.color:''}${p.size?' size:'+p.size:''}${p.shade?' shade:'+p.shade:''}${p.skin_type?' skin type:'+p.skin_type:''}${p.hair_type?' hair type:'+p.hair_type:''}${p.concern?' concern:'+p.concern:''}${p.volume_ml?' volume:'+p.volume_ml:''}${p.ingredient?' ingredient:'+p.ingredient:''}${p.description?' description:'+String(p.description).slice(0,500):''}`).join('\n');
    categoryList=[...new Set(products.map(p=>(p.category||'').trim()).filter(Boolean))];
  }

  const system=`You are screening one incoming WhatsApp message for a business selling physical products. Classify it into exactly one of:
- "order": the customer clearly wants to buy/order right now — "order this", "I'll take it", "buy it", "yes place my order", "order pls", confirming they want to proceed after being shown a product.
- "enquiry": genuine interest in a specific product without yet committing to buy — a size/color/stock/price question about one item, "tell me more", "give me the details", "do you have it in red".
- neither (not a signal at all) — general browsing, greetings, or unrelated questions.
If "order" or "enquiry", try to match it to exactly one product from the catalog below.
- Search broadly across every catalog value shown: exact name, short label, SKU, category, brand, variant, style, color, size, shade, skin/hair type, concern, volume, ingredient and description. A customer's everyday phrase can match any of those stored Product fields.
- Match by reasonable everyday judgment, not exact string equality — a customer writes informally, the catalog doesn't. "Green shirt" should match a catalog color of "Light Green" or "Bottle Green"; "greenshirt" and "green shirt" are the same query; a size like "S"/"small"/"S size" are the same detail. Don't withhold sku just because the wording isn't identical to the catalog fields — withhold it only when you genuinely can't tell which product (or no product) is meant.
- A message with NO distinguishing detail of its own — "order it", "M size" alone, "that one", "yes please" — should be resolved using the recent conversation below, if given: it very likely refers to whichever product was just discussed.
- A message that names its own distinguishing detail (a color, size, or product name) should be matched against the catalog by that detail. If it's consistent with the product just discussed (e.g. "size M" right after that same shirt was shown), match to that one. If it conflicts with the product just discussed (e.g. "red shirt" right after a green shirt was shown), treat it as asking about a NEW product and match fresh by the new detail — don't keep reusing the old product's sku just because it was recently discussed. Only omit sku (or classify as neither, if it's clearly asking for something not carried at all) when the named detail truly doesn't correspond to anything in the catalog.
- Always also include product_name using the catalog product's EXACT plain name whenever you include sku. Never shorten, expand, paraphrase, autocomplete, or invent a product name. If no single catalog record is a confident exact match, omit sku and product_name; the application will ask the customer to clarify instead of guessing.
- If you cannot confidently match one specific product, but the message clearly asks about a product category rather than any one item (e.g. "shirts", "do you have pants") AND that category (or something close to it) is in the Known categories list below, include "category" instead — the exact string from Known categories that best matches. Never include both sku and category; category only applies when no single product is a confident match.
- Separately (and only when a category is also included, or already clear from recent conversation), if the message itself names a specific brand from the catalog above (e.g. "REPOSE", "do you have Cloudnine Hybrid") rather than a specific model, also include "brand" — the exact brand string from the catalog that best matches. A bare brand name with no other detail ("REPOSE" on its own, right after being asked which brand) still counts — resolve the category from recent conversation the same way a bare size/color reply already does.
Respond with ONLY valid JSON: {"signal":true,"mode":"order","sku":"...","product_name":"..."} or {"signal":true,"mode":"enquiry","sku":"...","product_name":"..."} or {"signal":true,"mode":"enquiry","category":"...","brand":"..."} (sku/product_name omitted if no confident single-product match; category/brand omitted unless relevant — brand only ever accompanies category, never sku) or {"signal":false}.
${contextText?`\nRecent conversation (oldest first — use this to resolve references back to a specific product):\n${contextText}\n`:''}
Known categories: ${categoryList.join(', ')||'(none)'}
Product catalog:
${productList||'(no products listed)'}`;

  const raw=(await engineGeminiGenerateWithFallback(env, c, system, message, {
    temperature:0.2, maxOutputTokens:150, json:true
  }))||'{"signal":false}';
  let parsed={signal:false};
  try{ parsed=JSON.parse(raw); }catch(e){}
  const mode=parsed.mode==='order'?'order':'enquiry'; // defaults to the more conservative 'enquiry' (no link sent) if the model omits mode or returns something unrecognized
  return {
    signal:!!parsed.signal, mode,
    sku:parsed.signal?(parsed.sku||undefined):undefined,
    productName:parsed.signal?(parsed.product_name||undefined):undefined,
    category:parsed.signal?(parsed.category||undefined):undefined,
    brand:parsed.signal?(parsed.brand||undefined):undefined
  };
}

// Classifies one incoming message for order-readiness — same n8n-calls-Cloudflare shape as
// handleAiObjectionReply above (client_id-based, no session; n8n orchestrates, this only
// classifies). n8n should then call POST /ecom/order-link with the returned sku (and the
// customer's phone) to actually build+send+log the link; this endpoint only decides *whether* and
// *for what*, it never sends anything itself. Optional body.context lets n8n pass its own recent-
// conversation text if it has one handy; otherwise there's none here (n8n calls this standalone,
// with just the one message) — see detectOrderSignal's comment for why context matters.
async function handleAiOrderSignal(request, env){
  const body=await request.json().catch(()=>({}));
  const clientId=String(body.client_id||'');
  const message=String(body.message||'').trim();
  if(!clientId||!message) return json({error:'client_id and message required'}, 400);
  const c=await getClientById(env, clientId);
  if(!c) return json({error:'Client not found'}, 404);
  const result=await detectOrderSignal(env, c, clientId, message, String(body.context||''));
  if(result.error) return json({error:result.error}, result.error.startsWith('No AI provider')?400:502);
  return json({signal:result.signal, sku:result.sku});
}

// Booking-industry equivalent of handleAiOrderSignal above — same n8n-calls-Cloudflare shape
// (client_id-based, no session, pure detection, no side effects), but screens for booking
// readiness (wants to schedule/book, or asks about availability/duration/price of a specific
// service) instead of purchase readiness, and matches against the Appointment module's Services
// catalog (apptResolveTable(c,'services')) instead of an ecom product catalog — the two aren't the
// same table, so handleAiOrderSignal can't be reused as-is for a services business. Completes the
// same two-step pattern /ai/order-signal + /ecom/order-link already gives ecom clients: n8n calls
// this on incoming messages, and on signal:true calls POST /leads/booking-link (passing service_id
// if matched) to actually send the link — kept as two calls, not merged into one, so n8n stays in
// control of whether its own bot also replies to the same message (the same double-reply-risk
// reasoning that kept detection and action separate for /ai/order-signal).
// Core detection logic, shared by the HTTP endpoint below (handleAiBookingSignal, for n8n to call)
// and handleChatwootMessageHook's own direct auto-send path (no n8n involved at all — see that
// function for why). `contextText` (fetchRecentChatwootContext, above) resolves bare replies like
// "the 30 min one" back to whichever service was actually just discussed. Returns
// {signal, service_id?} — never sends anything, purely a screen.
async function detectBookingSignal(env, c, clientId, message, contextText){
  if(!env.GEMINI_API_KEY && !c.openrouter_key) return {signal:false, error:'No AI provider configured.'};

  let serviceList='';
  if(c.industry==='healthcare'){
    const services=await hcListActiveServices(env,clientId);
    serviceList=services.map(s=>`- ${s.name} [service_id:${s.id}]${s.duration_minutes?' ('+s.duration_minutes+' min)':''}${Number(s.price)>0?' '+((s.currency||'')+' '+s.price):''}`).join('\n');
  }else{
    const servicesTable=apptResolveTable(c, 'services');
    if(servicesTable){
    const sr=await ncFetch(env, `api/v2/tables/${servicesTable}/records?where=(client_id,eq,${clientId})~and(status,neq,inactive)&limit=100&fields=Id,name,duration_minutes,price,currency`);
    const sd=await sr.json().catch(()=>({}));
    serviceList=(sd?.list||[]).map(s=>`- ${s.name} [service_id:${s.Id}]${s.duration_minutes?' ('+s.duration_minutes+' min)':''}${s.price?' '+((s.currency||'')+' '+s.price):''}`).join('\n');
    }
  }

  const system=`You are screening one incoming WhatsApp message for a services business (healthcare, consultancy, salon, etc), to decide if it's a booking-readiness signal — either an explicit request to book/schedule an appointment, OR a specific question about availability, duration, or price of one particular service that shows they're close to booking. General browsing questions, greetings, or unrelated questions are NOT signals.
If it is a signal, try to match it to exactly one service from the list below by name — include its service_id only if you're confident of the match, otherwise omit it (don't guess). A short reply like "the 30 min one" or "yes book it" with no service name still counts as a signal and should be matched using the recent conversation below, if given. Respond with ONLY valid JSON: {"signal":true,"service_id":"..."} or {"signal":true} (no confident match) or {"signal":false}.
${contextText?`\nRecent conversation (oldest first — use this to resolve references back to a specific service):\n${contextText}\n`:''}
Services offered:
${serviceList||'(no services listed)'}`;

  const raw=(await engineGeminiGenerateWithFallback(env, c, system, message, {
    temperature:0.2, maxOutputTokens:150, json:true
  }))||'{"signal":false}';
  let parsed={signal:false};
  try{ parsed=JSON.parse(raw); }catch(e){}
  return {signal:!!parsed.signal, service_id:parsed.signal?(parsed.service_id||undefined):undefined};
}

// Optional body.context lets n8n pass its own recent-conversation text if it has one handy — see
// detectBookingSignal's comment for why context matters for bare replies like "yes, the 30 min one".
async function handleAiBookingSignal(request, env){
  const body=await request.json().catch(()=>({}));
  const clientId=String(body.client_id||'');
  const message=String(body.message||'').trim();
  if(!clientId||!message) return json({error:'client_id and message required'}, 400);
  const c=await getClientById(env, clientId);
  if(!c) return json({error:'Client not found'}, 404);
  const result=await detectBookingSignal(env, c, clientId, message, String(body.context||''));
  if(result.error) return json({error:result.error}, result.error.startsWith('No AI provider')?400:502);
  return json({signal:result.signal, service_id:result.service_id});
}

// Plain lookup, no AI — "has this phone number ordered before, and what's the status" — so a
// returning customer ("where's my order?", "I already paid") gets recognized instead of the bot
// starting a fresh sales pitch. Cheap enough to call on every incoming message; n8n decides what
// to do with the result (reference the existing order, skip re-pushing an order link, etc.).
async function handleEcomOrderLookup(request, env){
  const url=new URL(request.url);
  const clientId=String(url.searchParams.get('client_id')||'');
  const phone=String(url.searchParams.get('phone')||'').replace(/[^0-9+]/g,'');
  if(!clientId||!phone) return json({error:'client_id and phone required'}, 400);
  const ordersTable=await ecomResolveTable(env, clientId, 'orders');
  if(!ordersTable) return json({found:false, orders:[]});
  const r=await ncFetch(env, `api/v2/tables/${ordersTable}/records?where=(client_id,eq,${clientId})~and(customer_phone,eq,${encodeURIComponent(phone)})&sort=-order_date&limit=5`);
  const data=await r.json().catch(()=>({}));
  const orders=(data?.list||[]).map(o=>({order_id:o.order_id, status:o.status, items:o.items, total:o.total, currency:o.currency, order_date:o.order_date}));
  return json({found:orders.length>0, orders});
}

/* ── Campaigns module (broadcast.html) — Chatwoot template list/create + send
   routes, so chatwoot_token never reaches the browser (previously broadcast.html
   embedded both the master NocoDB token and the client's own chatwoot_token
   directly, readable via view-source — see SETUP.md's "Known gap" note). Lead
   reads/writes for the Follow-ups tab and the Tracking log reuse the existing
   generic /nocodb/* passthrough below — only the actual Chatwoot sends and the
   template list/create need a dedicated route, since those are the only calls
   that require the client's chatwoot_token. ── */
// Chatwoot has no "whatsapp_templates" sub-resource (that route 404s on every inbox — it doesn't
// exist in Chatwoot's API at all). The real API surface, confirmed against Chatwoot's own source:
// templates are synced from Meta asynchronously via POST .../sync_templates (fire-and-forget, no
// templates in the response), and the last-synced list is exposed as a flat `message_templates`
// field on the ordinary GET .../inboxes/:id (inbox show) response.
async function handleBroadcastTemplatesGet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_base||!c?.chatwoot_account_id||!c?.chatwoot_token) return json({error:'Chatwoot is not fully configured for this account.'}, 400);
  const url=new URL(request.url);
  const inboxId=Number(url.searchParams.get('inbox_id')||0)||Number(c.chatwoot_inbox_id)||0;
  if(!inboxId) return json({error:'No WhatsApp inbox configured for this account.'}, 400);
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes/${inboxId}`, {headers:{api_access_token:c.chatwoot_token}});
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:data?.message||'Chatwoot API '+r.status}, 502);
  return json({ok:true, templates:data?.message_templates||[], last_updated:data?.message_templates_last_updated||null});
}

// Triggers Chatwoot's async template sync job (pulls the latest approved templates from Meta into
// Chatwoot's cache). It only enqueues the job and returns immediately — the caller should wait a
// few seconds and then call handleBroadcastTemplatesGet again to see the refreshed list.
async function handleBroadcastTemplatesSync(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_base||!c?.chatwoot_account_id||!c?.chatwoot_token) return json({error:'Chatwoot is not fully configured for this account.'}, 400);
  const body=await request.json().catch(()=>({}));
  const inboxId=Number(body.inbox_id||0)||Number(c.chatwoot_inbox_id)||0;
  if(!inboxId) return json({error:'No WhatsApp inbox configured for this account.'}, 400);
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes/${inboxId}/sync_templates`, {
    method:'POST', headers:{api_access_token:c.chatwoot_token}
  });
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:data?.error||data?.message||'Chatwoot API '+r.status}, 502);
  return json({ok:true, message:data?.message||'Template sync initiated'});
}

// Chatwoot only *syncs* templates from Meta — it has no API to create a new one, since a template
// must be submitted straight to Meta for approval. So creating one still requires the client's own
// Meta WhatsApp Business API credentials (waba_id/wa_token) — this is a real limitation of Chatwoot
// itself, not something we can route around, unlike listing/sending which Chatwoot fully supports.
async function handleBroadcastTemplatesCreate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {name, category, language, body, header, footer, inbox_id}=await request.json().catch(()=>({}));
  if(!name||!body) return json({error:'name and body required'}, 400);
  const c=await getClientById(env, payload.cid);
  const creds=await resolveOrDetectMetaCredentials(env,c,payload.cid,{inbox_id});
  if(!creds?.waba_id||!creds?.wa_token) return json({error:'Creating a template requires Meta credentials for the selected WhatsApp channel. Use Detect credentials beside that channel in Settings → Channels.'}, 400);
  const components=[{type:'BODY', text:body}];
  if(header) components.unshift({type:'HEADER', format:'TEXT', text:header});
  if(footer) components.push({type:'FOOTER', text:footer});
  const r=await fetch(`https://graph.facebook.com/v18.0/${creds.waba_id}/message_templates`, {
    method:'POST', headers:{Authorization:`Bearer ${creds.wa_token}`, 'Content-Type':'application/json'},
    body:JSON.stringify({name, category, language, components})
  });
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:data?.error?.message||'HTTP '+r.status}, 502);
  return json({ok:true, data});
}

// Plain message send, with an optional image/video attachment — the "Direct Message" tab
// (leads still inside WhatsApp's 24h session window, so a free-text message is allowed).
async function handleBroadcastSendDm(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const form=await request.formData().catch(()=>null);
  if(!form) return json({error:'multipart form data required'}, 400);
  const conv_id=form.get('conv_id');
  const content=form.get('content')||'';
  const file=form.get('file');
  if(!conv_id||(!content&&!file)) return json({error:'conv_id and content (or file) required'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_base||!c?.chatwoot_account_id||!c?.chatwoot_token) return json({error:'Chatwoot is not configured for this account.'}, 400);
  const fd=new FormData();
  fd.append('message_type','outgoing'); fd.append('private','false');
  if(content) fd.append('content', content);
  if(file && file.size) fd.append('attachments[]', file, file.name||'attachment');
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${conv_id}/messages`, {method:'POST', headers:{api_access_token:c.chatwoot_token}, body:fd});
  if(!r.ok) return json({error:'HTTP '+r.status}, 502);
  return json({ok:true, data:await r.json().catch(()=>({}))});
}

// Approved-template send — for leads outside the 24h window, or any lead you want to reach
// with a formal WhatsApp Business template. The "Template Broadcast" tab.
async function handleBroadcastSendTemplate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {conv_id, content, template_name, category, language, processed_params}=await request.json().catch(()=>({}));
  if(!conv_id||!content||!template_name) return json({error:'conv_id, content, and template_name required'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_base||!c?.chatwoot_account_id||!c?.chatwoot_token) return json({error:'Chatwoot is not configured for this account.'}, 400);
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${conv_id}/messages`, {
    method:'POST', headers:{api_access_token:c.chatwoot_token, 'Content-Type':'application/json'},
    body:JSON.stringify({content, message_type:'outgoing', private:false, template_params:{name:template_name, category:category||'MARKETING', language:language||'en', processed_params:processed_params||{}}})
  });
  if(!r.ok) return json({error:'HTTP '+r.status}, 502);
  return json({ok:true, data:await r.json().catch(()=>({}))});
}

// Follow-up Engine's fixed 5-step ladder shape — one single place for every follow-up setting
// (previously split between this D1 table, added by migrations/0047_followup_ladder.sql, and
// dashboard.html's now-retired Settings → Follow-up Messages section). Steps 1-2 stay inside
// WhatsApp's 24h customer-service window, so a plain session message is allowed; steps 3-5 are
// fixed at 2/4/7 days of silence — always past 24h, so only an approved template can legally reach
// the customer there (see sendFollowupLadderStep). Days for steps 3-5 are NOT merchant-editable —
// the whole point of this ladder replacing the old free-form "up to 3 steps, any hours" model is a
// fixed, predictable shape; hours for steps 1-2 stay editable since both are well inside the same
// 24h window regardless of the exact value.
const FOLLOWUP_LADDER_STEP_SHAPE=[
  {step:1, type:'session', defaultHours:1},
  {step:2, type:'session', defaultHours:6},
  {step:3, type:'template', defaultHours:25},
  {step:4, type:'template', defaultHours:72},
  {step:5, type:'template', defaultHours:168},
];
function followupLadderDefaultStep(step, legacyHours, legacyMessages){
  const shape=FOLLOWUP_LADDER_STEP_SHAPE.find(s=>s.step===step);
  if(shape.type==='session'){
    const legacyIdx=step-1;
    const legacyHour=legacyHours[legacyIdx];
    return {step, type:'session', hours:(legacyHour&&legacyHour<24)?legacyHour:shape.defaultHours, days:null,
      message:legacyMessages[legacyIdx]||'', message_b:'', template_name:'', template_language:'en_US', template_category:'MARKETING', template_body_vars:0,
      template_name_b:'', template_language_b:'en_US', template_category_b:'MARKETING', template_body_vars_b:0};
  }
  return {step, type:'template', hours:shape.defaultHours, days:null,
    message:'', message_b:'', template_name:'', template_language:'en_US', template_category:'MARKETING', template_body_vars:0,
    template_name_b:'', template_language_b:'en_US', template_category_b:'MARKETING', template_body_vars_b:0};
}

// GET/POST /followups/ladder — the Follow-up Engine tab's single settings surface (replaces the
// old GET/POST /followups/variants A/B-per-step model, migrations/0007, now unused going forward
// but left in place rather than dropped). Variant B (message_b / template_name_b+language_b+
// category_b+body_vars_b, migrations/0048) is optional on every step — see pickLadderVariant for
// how it's chosen at send time once configured.
async function handleFollowupLadderGet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  const {results}=await env.DB.prepare(`SELECT * FROM followup_ladder_steps WHERE client_id=?`).bind(Number(payload.cid)).all();
  const bySt={}; (results||[]).forEach(r=>{ bySt[r.step]=r; });
  // Best-effort one-time read-only migration: a client who configured the old classic sequence
  // (dashboard.html Settings, now retired) but never saved this new ladder yet sees step 1-2
  // pre-filled from their existing followup_hours/followup_messages instead of starting blank —
  // nothing is written here, only shown; hitting Save is what actually persists it.
  const legacyHours=(c?.followup_hours||'').split(',').map(s=>parseFloat(s.trim())).filter(n=>n>0);
  const legacyMessages=(c?.followup_messages||'').split('\n').map(s=>s.trim()).filter(Boolean);
  const list=FOLLOWUP_LADDER_STEP_SHAPE.map(shape=>{
    const r=bySt[shape.step];
    return r
      ? {step:r.step, type:r.type, hours:r.hours, days:r.days, message:r.message, message_b:r.message_b,
         template_name:r.template_name, template_language:r.template_language, template_category:r.template_category, template_body_vars:r.template_body_vars,
         template_name_b:r.template_name_b, template_language_b:r.template_language_b, template_category_b:r.template_category_b, template_body_vars_b:r.template_body_vars_b}
      : followupLadderDefaultStep(shape.step, legacyHours, legacyMessages);
  });
  return json({list});
}
async function handleFollowupLadderSave(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const steps=Array.isArray(body.steps)?body.steps:[];
  const now=new Date().toISOString();
  for(const shape of FOLLOWUP_LADDER_STEP_SHAPE){
    const s=steps.find(x=>parseInt(x.step)===shape.step);
    if(!s) continue;
    if(shape.type==='session'){
      const hours=Math.min(23, Math.max(1, parseInt(s.hours)||shape.defaultHours));
      await env.DB.prepare(`INSERT INTO followup_ladder_steps (client_id, step, type, hours, days, message, message_b, template_name, template_language, template_category, template_body_vars, template_name_b, template_language_b, template_category_b, template_body_vars_b, updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(client_id, step) DO UPDATE SET hours=excluded.hours, message=excluded.message, message_b=excluded.message_b, updated_at=excluded.updated_at`)
        .bind(Number(payload.cid), shape.step, 'session', hours, null,
          String(s.message||'').trim().slice(0,1000), String(s.message_b||'').trim().slice(0,1000),
          '', 'en_US', 'MARKETING', 0, '', 'en_US', 'MARKETING', 0, now)
        .run();
    } else {
      await env.DB.prepare(`INSERT INTO followup_ladder_steps (client_id, step, type, hours, days, message, message_b, template_name, template_language, template_category, template_body_vars, template_name_b, template_language_b, template_category_b, template_body_vars_b, updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(client_id, step) DO UPDATE SET hours=excluded.hours, days=excluded.days, template_name=excluded.template_name, template_language=excluded.template_language, template_category=excluded.template_category, template_body_vars=excluded.template_body_vars,
          template_name_b=excluded.template_name_b, template_language_b=excluded.template_language_b, template_category_b=excluded.template_category_b, template_body_vars_b=excluded.template_body_vars_b, updated_at=excluded.updated_at`)
        .bind(Number(payload.cid), shape.step, 'template', shape.defaultHours, null, '', '',
          String(s.template_name||'').trim().slice(0,200), String(s.template_language||'en_US').trim().slice(0,20), String(s.template_category||'MARKETING').trim().slice(0,20), Math.max(0, parseInt(s.template_body_vars)||0),
          String(s.template_name_b||'').trim().slice(0,200), String(s.template_language_b||'en_US').trim().slice(0,20), String(s.template_category_b||'MARKETING').trim().slice(0,20), Math.max(0, parseInt(s.template_body_vars_b)||0),
          now)
        .run();
    }
  }
  return json({ok:true});
}

// Auto-promoting A/B pick: a step with no Variant B configured always sends A (variant label 'A',
// same as any step that's never had a B at all). Once B exists, both start at an even 50/50 split
// — MIN_SAMPLES sends per variant minimum before ANY promotion is considered, so a brand-new step
// isn't skewed off a handful of noisy early sends. Once both variants have enough samples, the one
// with a meaningfully higher reply rate (more than PROMOTE_MARGIN apart — anything closer is called
// a tie, kept at 50/50 rather than over-fitting noise) gets weighted PROMOTE_WEIGHT instead of 0.5.
// This is a simple, explainable heuristic (epsilon-greedy-ish), not a rigorous statistical test —
// appropriate for follow-up reply-rate sample sizes, which are rarely large enough to need one.
const FOLLOWUP_VARIANT_MIN_SAMPLES=20;
const FOLLOWUP_VARIANT_PROMOTE_MARGIN=0.05; // 5 percentage points
const FOLLOWUP_VARIANT_PROMOTE_WEIGHT=0.8;
async function pickLadderVariant(env, clientId, step, stepCfg){
  const hasB=stepCfg.type==='session'?!!stepCfg.message_b:!!stepCfg.template_name_b;
  if(!hasB) return 'A';
  const {results}=await env.DB.prepare(`SELECT variant, COUNT(*) as sent, SUM(CASE WHEN replied_at IS NOT NULL THEN 1 ELSE 0 END) as replied
    FROM followup_sends WHERE client_id=? AND step=? AND variant IN ('A','B') GROUP BY variant`)
    .bind(Number(clientId), step).all();
  const byVariant={A:{sent:0,replied:0}, B:{sent:0,replied:0}};
  (results||[]).forEach(r=>{ if(byVariant[r.variant]) byVariant[r.variant]={sent:r.sent, replied:r.replied}; });
  if(byVariant.A.sent<FOLLOWUP_VARIANT_MIN_SAMPLES || byVariant.B.sent<FOLLOWUP_VARIANT_MIN_SAMPLES){
    return Math.random()<0.5?'A':'B';
  }
  const rateA=byVariant.A.replied/byVariant.A.sent, rateB=byVariant.B.replied/byVariant.B.sent;
  if(Math.abs(rateA-rateB)<FOLLOWUP_VARIANT_PROMOTE_MARGIN) return Math.random()<0.5?'A':'B';
  const winner=rateA>rateB?'A':'B';
  return Math.random()<FOLLOWUP_VARIANT_PROMOTE_WEIGHT?winner:(winner==='A'?'B':'A');
}
// Resolves a chosen variant letter down to the actual content to send for this step.
function ladderVariantContent(stepCfg, variant){
  if(stepCfg.type==='session') return {message: variant==='B'?stepCfg.message_b:stepCfg.message};
  return variant==='B'
    ? {template_name:stepCfg.template_name_b, template_language:stepCfg.template_language_b, template_category:stepCfg.template_category_b, template_body_vars:stepCfg.template_body_vars_b}
    : {template_name:stepCfg.template_name, template_language:stepCfg.template_language, template_category:stepCfg.template_category, template_body_vars:stepCfg.template_body_vars};
}

// Real-scarcity line for ecom follow-ups — session steps (1-2) only: a WhatsApp template's approved
// body text can't be altered beyond filling its own {{n}} variables, so there's no legal way to
// append this to a template step (3-5). Resolves the lead's own InterestedProduct (free-text, set
// by the live engine's classifier — see engineClassifyIntent) against the real catalog the same
// fuzzy way ecomResolveProduct always has, and only speaks up when stock is holding a genuinely low,
// real number — never a fabricated countdown or "hurry" line with nothing behind it.
const FOLLOWUP_LOW_STOCK_THRESHOLD=5;
async function ecomFollowupScarcityLine(env, c, lead){
  if(c.industry!=='ecommerce' || !lead.InterestedProduct) return '';
  try{
    const product=await ecomResolveProduct(env, c.Id, '', lead.InterestedProduct);
    const stock=Number(product?.stock);
    if(!product || !Number.isFinite(stock) || stock<=0 || stock>FOLLOWUP_LOW_STOCK_THRESHOLD) return '';
    return `\n\n⚡ Only ${stock} left in ${product.name} — grab it before it's gone.`;
  }catch(e){ return ''; }
}

// Client-wide "preferred send window" (bot_config.followup_quiet_hours_enabled, default on;
// followup_window_start_hour/followup_window_end_hour, default 18-21 — evenings, after typical
// office hours) — computed once per client per cron tick (not per lead, since it's the same answer
// for all of them), same local-time-from-timezone pattern the final-stage-positive callback message
// already uses (see engineRouteFlow's own `botConfig.timezone` block). A lead who becomes "due"
// outside the window is simply left for a later tick — nothing is marked sent, so it's never lost,
// only delayed to the next time this function returns true.
function followupWithinQuietHours(c){
  const botConfig=engineParseJsonField(c.bot_config, {});
  if(botConfig.followup_quiet_hours_enabled===false) return true;
  const tz=botConfig.timezone||'Asia/Kolkata';
  const startHour=Number.isFinite(botConfig.followup_window_start_hour)?botConfig.followup_window_start_hour:18;
  const endHour=Number.isFinite(botConfig.followup_window_end_hour)?botConfig.followup_window_end_hour:21;
  const nowLocal=new Date(new Date().toLocaleString('en-US',{timeZone:tz}));
  const hour=nowLocal.getHours();
  return startHour<=endHour ? (hour>=startHour && hour<endHour) : (hour>=startHour || hour<endHour);
}

// The actual "pick variant, send, mark Follow up N, log followup_sends" work for one ladder step —
// shared by the manual "Send Next Now" route (handleBroadcastFollowupSend) and the automated cron
// (runClassicFollowupsForAllClients) further down, so neither has to fork its own copy.
// Steps 1-2 (type 'session') go out as a plain Chatwoot session message — only valid within
// WhatsApp's 24h customer-service window, which is exactly why both are capped under 24h at save
// time (handleFollowupLadderSave). Steps 3-5 (type 'template') go straight through Meta's Graph
// API as an approved template message instead — same direct-Graph-API shape as
// handleWaSendTemplate/sendShopifyNotification, deliberately bypassing Chatwoot for the send side
// (Chatwoot's own template relay depends on a separate sync some inboxes 404 on, per
// handleWaSendTemplate's own comment) — the only message type WhatsApp allows this far past the
// customer's last message. Throws on a hard send failure so callers decide how to report it: a 502
// to the rep for the manual route, a caught-and-logged per-lead skip for the cron sweep.
async function sendFollowupLadderStep(env, c, lead, step, stepCfg){
  const clientId=String(c.Id);
  let sentText='', sentViaVoice=false;
  const variant=await pickLadderVariant(env, c.Id, step, stepCfg);
  const content=ladderVariantContent(stepCfg, variant);

  if(stepCfg.type==='session'){
    if(!c.chatwoot_base||!c.chatwoot_account_id||!c.chatwoot_token) throw new Error('Chatwoot is not configured for this account.');
    const convId=lead.ConversationID||lead.conv_id||lead.ConversationId||lead.chatwoot_conv_id;
    if(!convId) throw new Error('This lead has no conversation yet.');
    sentText=String(content.message||'').replace(/\{name\}/gi, lead.Name||'there');
    // Real-scarcity line (ecom only, session steps only — see ecomFollowupScarcityLine's own
    // comment on why a template step can't carry this).
    sentText+=await ecomFollowupScarcityLine(env, c, lead);

    // Voice Follow-ups (Settings → Voice) — same Sarvam-primary/AI4Bharat-standby pipeline as live
    // voice-to-voice replies. Only applies to steps 1-2: a WhatsApp template's approved wording is
    // fixed by Meta, so there is no text to speak in its place for steps 3-5.
    if(c.voice_followup_enabled==='Yes'){
      const bcp47=ENGINE_TTS_LANG_MAP[(lead.Language||c.language||'en').toLowerCase()];
      if(bcp47){
        const audioBuf=await engineTtsWithFallback(env, sentText, (lead.Language||c.language||'en'), c.voice_tts_provider);
        if(audioBuf){
          const vfd=new FormData();
          vfd.append('content', engineExtractLinkPriceCaption(sentText));
          vfd.append('message_type','outgoing'); vfd.append('private','false');
          vfd.append('attachments[]', new Blob([audioBuf], {type:'audio/ogg; codecs=opus'}), 'followup.ogg');
          const vr=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${convId}/messages`, {method:'POST', headers:{api_access_token:c.chatwoot_token}, body:vfd});
          sentViaVoice=vr.ok;
          if(!vr.ok) await reportOpsError(env, 'sendFollowupLadderStep — voice send failed, falling back to text', new Error('HTTP '+vr.status), {clientId, convId});
        }
      }
    }
    if(!sentViaVoice){
      const fd=new FormData();
      fd.append('content', sentText); fd.append('message_type','outgoing'); fd.append('private','false');
      const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${convId}/messages`, {method:'POST', headers:{api_access_token:c.chatwoot_token}, body:fd});
      if(!r.ok) throw new Error('HTTP '+r.status);
    }
  } else {
    if(!c.wa_phone_id||!c.wa_token) throw new Error('WhatsApp Business API is not connected for this account — connect it from Settings → Channels.');
    if(!lead.Phone) throw new Error('This lead has no phone number.');
    // Each {{n}} placeholder in the template's approved BODY text gets filled with the lead's name
    // (template_body_vars, counted when the template was picked in the Follow-up Engine UI) — a
    // pragmatic default covering the overwhelmingly common case (a template's only variable is the
    // customer's name), not a general variable-mapping system.
    const varCount=Math.max(0, content.template_body_vars||0);
    const components=varCount?[{type:'body', parameters:Array.from({length:varCount}, ()=>({type:'text', text:lead.Name||'there'}))}]:[];
    const r=await fetch(`https://graph.facebook.com/v18.0/${c.wa_phone_id}/messages`, {
      method:'POST', headers:{Authorization:`Bearer ${c.wa_token}`, 'Content-Type':'application/json'},
      body:JSON.stringify({messaging_product:'whatsapp', to:lead.Phone, type:'template', template:{name:content.template_name, language:{code:content.template_language||'en_US'}, components}})
    });
    const data=await r.json().catch(()=>({}));
    if(!r.ok) throw new Error(data?.error?.message||('HTTP '+r.status));
    sentText=`[template: ${content.template_name}]`;
  }

  // Mark the step as sent. If this PATCH fails the message still went out, so we log the failure
  // rather than throwing — throwing here would leave `Follow up N` unset and cause the next cron
  // tick to send the same message again (double-send).
  const patchRes=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'PATCH', body:{Id:Number(lead.Id), ['Follow up '+step]:'Yes'}});
  if(!patchRes.ok) console.error('[followup] PATCH Follow up',step,'failed for lead',lead.Id,'HTTP',patchRes.status);
  try{
    await env.DB.prepare(`INSERT INTO followup_sends (client_id, lead_id, step, variant, sent_at) VALUES (?,?,?,?,?)`)
      .bind(Number(c.Id), Number(lead.Id), step, variant, new Date().toISOString()).run();
  }catch(e){ /* best-effort — the message already went out regardless of whether this logs */ }
  return {text:sentText, sentViaVoice, variant};
}

// Manual "send next follow-up now" — a rep's on-demand override alongside the automated ladder
// cron (runClassicFollowupsForAllClients) and the separate recovery ladder (recovery.js, untouched
// by this). `stage` in the response keeps its old field name (not `step`) since dashboard.html's
// sendTaskWaFollowUp already reads response.stage to flip the right Lead field client-side.
async function handleBroadcastFollowupSend(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {lead_id}=await request.json().catch(()=>({}));
  if(!lead_id) return json({error:'lead_id required'}, 400);
  const c=await getClientById(env, payload.cid);

  const leadR=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records/${lead_id}`);
  if(!leadR.ok) return json({error:'Lead not found'}, 404);
  const lead=await leadR.json();
  if(String(lead.ClientId)!==String(payload.cid)) return json({error:'Not your lead'}, 403);

  await ensureLeadsColumns(env, ['Follow up 4','Follow up 5']);
  const {results:stepRows}=await env.DB.prepare(`SELECT * FROM followup_ladder_steps WHERE client_id=?`).bind(Number(payload.cid)).all();
  const steps={}; (stepRows||[]).forEach(r=>{ steps[r.step]=r; });
  const silentHoursManual=(Date.now()-new Date(lead.LastMsgAt||lead.Date||0).getTime())/3600000;
  let nextStep=-1;
  for(let s=1; s<=5; s++){
    if(lead['Follow up '+s]==='Yes') continue;
    const stepCfg=steps[s];
    if(stepCfg?.type==='session' && silentHoursManual>=24) continue; // WhatsApp 24h session window closed
    nextStep=s; break;
  }
  if(nextStep===-1) return json({error:'No follow-up steps left to send for this lead.'}, 400);
  const stepCfg=steps[nextStep];
  if(!stepCfg) return json({error:`Step ${nextStep} isn't set up yet — configure it in Campaigns → Follow-up Engine.`}, 400);
  if(stepCfg.type==='session' && !stepCfg.message) return json({error:'No message configured for this step yet.'}, 400);
  if(stepCfg.type==='template' && !stepCfg.template_name) return json({error:'No template chosen for this step yet.'}, 400);

  try{
    const {text, sentViaVoice}=await sendFollowupLadderStep(env, c, lead, nextStep, stepCfg);
    return json({ok:true, stage:nextStep, sentText:text, sentViaVoice});
  }catch(e){ return json({error:e.message||'Send failed'}, 502); }
}

// Automated ladder sweep — runs on the existing `*/15 * * * *` tick (see scheduled() below) rather
// than the daily one, since steps 1-2 are sub-daily (hours, not days). Per-client cost stays low:
// a client who's never touched the Follow-up Engine has zero rows in followup_ladder_steps and is
// skipped in one query, same as the old count>0 gate.
async function runClassicFollowupsForAllClients(env){
  let page=1;
  while(true){
    const r=await ncFetch(env, `api/v2/tables/${CLIENTS_TABLE}/records?limit=200&offset=${(page-1)*200}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const rows=data?.list||[];
    if(!rows.length) break;
    for(const c of rows){
      try{ await classicFollowupProcessClient(env, c); }
      catch(e){ console.error('[classic-followups] failed for client', c.Id, e.message); }
    }
    if(rows.length<200) break;
    page++;
  }
}
async function classicFollowupProcessClient(env, c){
  if(c.followup_do_enabled==='Yes') return; // handed off to LeadFollowupAgent Durable Objects
  const {results:stepRows}=await env.DB.prepare(`SELECT * FROM followup_ladder_steps WHERE client_id=?`).bind(Number(c.Id)).all();
  if(!stepRows||!stepRows.length) return; // Follow-up Engine never configured for this client
  // Checked once per client per tick, not per lead — it's the same answer for every lead of this
  // client this tick. A lead who becomes due while outside the window is simply picked up on a
  // later tick (nothing is marked sent here), not skipped forever.
  if(!followupWithinQuietHours(c)) return;
  const steps={}; stepRows.forEach(r=>{ steps[r.step]=r; });
  // Silent-hours threshold per step: 1-2 use their own configured `hours`; 3-5 are fixed at their
  // day count * 24 (not merchant-editable — see FOLLOWUP_LADDER_STEP_SHAPE's own comment).
  const thresholdHours=step=>{
    const cfg=steps[step];
    if(cfg.type==='session') return cfg.hours||24;
    return FOLLOWUP_LADDER_STEP_SHAPE.find(shape=>shape.step===step)?.defaultHours||((cfg.days||0)*24);
  };
  await ensureLeadsColumns(env, ['Follow up 4','Follow up 5']);
  const where=`(ClientId,eq,${c.Id})~and(OptOut,neq,Yes)~and(Handover,neq,Yes)`;
  let page=1;
  while(true){
    const leadsR=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}&limit=200&offset=${(page-1)*200}&fields=${encodeURIComponent('Id,Name,Phone,Stage,LastMsgAt,Date,Language,ConversationID,conv_id,ConversationId,chatwoot_conv_id,Follow up 1,Follow up 2,Follow up 3,Follow up 4,Follow up 5')}`);
    if(!leadsR.ok) break;
    const data=await leadsR.json().catch(()=>({}));
    const leadRows=data?.list||[];
    if(!leadRows.length) break;
    for(const lead of leadRows){
      if(PIPELINE_TERMINAL_STAGES.has(lead.Stage)) continue;
      const lastRealMs=lead.LastMsgAt||lead.Date;
      if(!lastRealMs) continue;
      const silentHours=(Date.now()-new Date(lastRealMs).getTime())/3600000;
      let nextStep=-1;
      for(let s=1; s<=5; s++){
        if(!steps[s]) continue; // step not configured yet — transparently skipped, not blocking
        if(lead['Follow up '+s]==='Yes') continue; // already sent
        // session steps are only valid inside WhatsApp's 24h customer-service window; once
        // that window has closed, skip past them so template steps further down can still fire.
        if(steps[s].type==='session' && silentHours>=24) continue;
        nextStep=s; break;
      }
      if(nextStep===-1) continue; // sequence exhausted, or all remaining session steps expired
      const stepCfg=steps[nextStep];
      if(stepCfg.type==='session' && !stepCfg.message) continue;
      if(stepCfg.type==='template' && !stepCfg.template_name){
        console.warn('[classic-followups] step',nextStep,'for lead',lead.Id,'has no template_name configured');
        env.DB.prepare(`INSERT INTO followup_send_failures (client_id, lead_id, step, error_message, source, failed_at) VALUES (?,?,?,?,?,?)`)
          .bind(Number(c.Id), Number(lead.Id), nextStep, 'No template_name configured for this step', 'cron', new Date().toISOString())
          .run().catch(()=>{});
        continue;
      }
      if(silentHours<thresholdHours(nextStep)) continue; // not due yet
      try{ await sendFollowupLadderStep(env, c, lead, nextStep, stepCfg); }
      catch(e){
        console.error('[classic-followups] send failed for lead', lead.Id, 'step', nextStep, e.message);
        if(stepCfg.type==='template'){
          // Write to followup_send_failures so the dashboard can show WHY the after-24h template send
          // failed (expired token, unapproved template, missing WA credentials, etc.) instead of silently swallowing it.
          const errCode=e.message?.match(/\b(1\d{5}|190|100)\b/)?.[0]||null;
          env.DB.prepare(`INSERT INTO followup_send_failures (client_id, lead_id, step, error_message, error_code, source, failed_at) VALUES (?,?,?,?,?,?,?)`)
            .bind(Number(c.Id), Number(lead.Id), nextStep, String(e.message).slice(0,500), errCode?Number(errCode):null, 'cron', new Date().toISOString())
            .run().catch(()=>{});
        }
      }
      await new Promise(res=>setTimeout(res, 300)); // pacing, same spirit as recovery.js's SEND_DELAY_MS
    }
    if(leadRows.length<200) break;
    page++;
  }
}

// Human Deals "🧭 Coach" panel — surfaces the same Sentiment/LastObjectionCategory signals the
// engine already computes on every inbound message, matched against this client's own Objection
// Playbook (Settings → Objection Playbook, unchanged — no new config screen), plus the
// coach_signals timeline (migrations/0008_coach_signals.sql) so a rep can see where a chat's tone
// or objections shifted over the conversation, not just its current snapshot.
async function handleHumanDealsCoach(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const url=new URL(request.url);
  const leadId=url.searchParams.get('lead_id');
  if(!leadId) return json({error:'lead_id required'}, 400);
  const leadR=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records/${leadId}`);
  if(!leadR.ok) return json({error:'Lead not found'}, 404);
  const lead=await leadR.json();
  if(String(lead.ClientId)!==String(payload.cid)) return json({error:'Not your lead'}, 403);
  const c=await getClientById(env, payload.cid);
  let playbook=[]; try{ playbook=JSON.parse(c?.objection_playbook||'[]'); }catch(e){}
  const category=lead.LastObjectionCategory||'';
  const entry=playbook.find(o=>(o.category||'').toLowerCase()===category.toLowerCase());
  const {results}=await env.DB.prepare(`SELECT sentiment, objection_category, at FROM coach_signals WHERE lead_id=? ORDER BY at DESC LIMIT 20`)
    .bind(Number(leadId)).all();
  return json({
    sentiment: lead.Sentiment||'',
    objection_category: category,
    approved_response: entry?.approved_response||'',
    timeline: (results||[]).reverse(),
  });
}

// Grouped by step+variant again (migrations/0048 brought Variant B, and pickLadderVariant's
// auto-promotion, back) — 'ladder' rows from the brief window between migrations/0047 and 0048
// (when every send was logged as a single unlabeled variant) still show up as their own row here,
// same as 'legacy'/'A'/'B' rows from before migrations/0047 existed at all; nothing is discarded.
async function handleFollowupStats(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {results}=await env.DB.prepare(`SELECT step, variant, COUNT(*) as sent, SUM(CASE WHEN replied_at IS NOT NULL THEN 1 ELSE 0 END) as replied
    FROM followup_sends WHERE client_id=? GROUP BY step, variant ORDER BY step, variant`)
    .bind(Number(payload.cid)).all();
  const list=(results||[]).map(r=>({step:r.step, variant:r.variant, sent:r.sent, replied:r.replied, reply_rate:r.sent?Math.round(r.replied/r.sent*100):0}));
  return json({list});
}

/* ── Automations & Flow module (frontend/broadcast.html — "⚡ Automations" tab) ─────────────
   A standalone module inside the Campaigns/Broadcast page: build a small ordered "flow" of
   steps a lead walks through once enrolled, entered either automatically (new lead, stage
   change, gone quiet) or by picking a segment and enrolling it once. It's deliberately built by
   *reusing* the two sibling modules' own facilities rather than re-implementing sends:
     - WhatsApp steps use the exact same Chatwoot call shape as the Broadcast module's
       handleBroadcastSendDm/handleBroadcastSendTemplate above (and recovery.js's ladder).
     - Email steps reuse sendClientResendEmail (the Email Marketing module's Resend helper) and
       the same unsubscribe-link footer handleEmailCampaignSendOne sends.
     - Audience matching reuses leadsAudienceWhereClause — the Email module's own
       {stage:[...], tags_any:[...]} segment_filter shape, unchanged.
   Flow definitions live as one JSON field on the client row (automation_flows) — same
   config-blob-on-CLIENTS pattern as followup_messages/recovery_gaps_hours, since a client has a
   handful of flows, not thousands of rows needing their own table. Per-lead progress lives in
   one JSON field on the Leads table (flow_state), auto-created the first time the engine touches
   a client — the same ensureRecoveryFields()-at-runtime pattern recovery.js uses for its own
   recovery_* fields, just issued through this file's ncFetch/master-token helper instead of a
   raw per-client-token fetch.
   Execution is a Cron Trigger tick (runAutomationFlowsForAllClients, every 15 min — see
   wrangler.toml), not a browser send-loop like the Email/Broadcast modules use for one-shot
   blasts: a flow can contain multi-hour/day `wait` steps, and nothing guarantees the tab that
   built the flow stays open that long. Manual "enroll this segment now" is the one action that
   still comes from an explicit request rather than the tick, mirroring the Email module's
   send-init/send-one split (enroll now, sends still happen on the flow's own schedule). ── */

const AUTOMATION_STEP_TYPES = new Set(['wait','send_whatsapp_dm','send_whatsapp_template','send_email','update_field','send_whatsapp_media']);
const AUTOMATION_TRIGGER_TYPES = new Set(['manual','new_lead','stage_enter','no_reply']);
// Same closed-out stages recovery.js already refuses to touch — a flow (especially a broad
// "no reply in N hours" one) shouldn't keep nudging a lead that's Converted/Lost/Closed/opted out.
const AUTOMATION_TERMINAL_STAGES = new Set(['Converted','Lost','Closed','Opt Out']);

function validateAutomationFlow(body){
  const name=String(body?.name||'').trim();
  if(!name) return 'name required';
  const trigger=body?.trigger||{};
  if(!AUTOMATION_TRIGGER_TYPES.has(trigger.type)) return 'invalid trigger.type';
  if(trigger.type==='no_reply' && !(parseFloat(trigger.no_reply_hours)>0)) return 'no_reply trigger needs no_reply_hours > 0';
  if(trigger.type==='stage_enter' && !(Array.isArray(body?.segment?.stage)&&body.segment.stage.length)) return 'a stage-enter trigger needs at least one Stage selected';
  const steps=Array.isArray(body?.steps)?body.steps:[];
  if(!steps.length) return 'at least one step required';
  for(const s of steps){
    if(!AUTOMATION_STEP_TYPES.has(s?.type)) return 'invalid step type: '+s?.type;
    if(s.type==='wait' && !(parseFloat(s.hours)>0)) return 'a Wait step needs hours > 0';
    if(s.type==='send_whatsapp_dm' && !String(s.message||'').trim()) return 'a Send WhatsApp DM step needs a message';
    if(s.type==='send_whatsapp_template' && !String(s.template_name||'').trim()) return 'a Send WhatsApp Template step needs a template_name';
    if(s.type==='send_email' && (!String(s.subject||'').trim()||!String(s.html_body||'').trim())) return 'a Send Email step needs a subject and html_body';
    if(s.type==='update_field' && !String(s.field||'').trim()) return 'an Update Field step needs a field name';
    if(s.type==='send_whatsapp_media' && !String(s.media_url||'').trim()) return 'a Send WhatsApp Media step needs a media_url';
  }
  return null;
}

async function getAutomationFlows(env, clientId){
  const c=await getClientById(env, clientId);
  let list=[]; try{ list=JSON.parse(c?.automation_flows||'[]'); }catch(e){}
  return {client:c, list};
}
async function saveAutomationFlows(env, clientId, list){
  await patchClientFields(env, clientId, {automation_flows:JSON.stringify(list)});
}

async function handleAutomationFlowsList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {list}=await getAutomationFlows(env, payload.cid);
  return json({list});
}

async function handleAutomationFlowCreate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const err=validateAutomationFlow(body);
  if(err) return json({error:err}, 400);
  const {list}=await getAutomationFlows(env, payload.cid);
  const flow={
    id:'fl_'+Date.now().toString(36)+Math.random().toString(36).slice(2,8),
    name:String(body.name).trim(),
    active:false,
    trigger:{type:body.trigger.type, no_reply_hours:parseFloat(body.trigger.no_reply_hours)||null},
    segment:{stage:Array.isArray(body.segment?.stage)?body.segment.stage:[], tags_any:Array.isArray(body.segment?.tags_any)?body.segment.tags_any:[]},
    steps:body.steps,
    stats:{enrolled:0, completed:0},
    created_at:new Date().toISOString(),
  };
  list.push(flow);
  await saveAutomationFlows(env, payload.cid, list);
  return json({ok:true, flow});
}

async function handleAutomationFlowUpdate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const {list}=await getAutomationFlows(env, payload.cid);
  const idx=list.findIndex(f=>f.id===body.id);
  if(idx===-1) return json({error:'Flow not found'}, 404);
  // Flipping just `active` (pause/resume) skips re-validation — the steps were already valid
  // the last time they were saved. Anything touching name/trigger/segment/steps re-validates
  // the full merged shape before persisting.
  const touchesShape=['name','trigger','segment','steps'].some(k=>k in body);
  if(touchesShape){
    const merged={...list[idx], name:body.name??list[idx].name, trigger:body.trigger??list[idx].trigger, segment:body.segment??list[idx].segment, steps:body.steps??list[idx].steps};
    const err=validateAutomationFlow(merged);
    if(err) return json({error:err}, 400);
    list[idx]={...list[idx], name:merged.name, trigger:merged.trigger, segment:merged.segment, steps:merged.steps};
  }
  if('active' in body) list[idx].active=!!body.active;
  await saveAutomationFlows(env, payload.cid, list);
  return json({ok:true, flow:list[idx]});
}

async function handleAutomationFlowDelete(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const {list}=await getAutomationFlows(env, payload.cid);
  const next=list.filter(f=>f.id!==body.id);
  if(next.length===list.length) return json({error:'Flow not found'}, 404);
  await saveAutomationFlows(env, payload.cid, next);
  return json({ok:true});
}

async function handleAutomationAudiencePreview(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const url=new URL(request.url);
  let segmentFilter={}; try{ segmentFilter=JSON.parse(url.searchParams.get('segment_filter')||'{}'); }catch(e){}
  const where=leadsAudienceWhereClause(payload.cid, segmentFilter);
  const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}&limit=5&fields=Id,Name,Phone`);
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json(data, r.status);
  return json({count:data?.pageInfo?.totalRows??(data.list||[]).length, sample:(data.list||[]).slice(0,5)});
}

// Auto-creates the flow_state field the first time any client's flow engine touches the Leads
// table — mirrors recovery.js's ensureRecoveryFields, just routed through this file's own
// ncFetch/master-token helper instead of a raw per-client-token fetch. Memoized per Worker
// isolate (best-effort — a cold start just re-checks once, no correctness impact either way).
let _flowStateFieldEnsured=false;
async function ensureFlowStateField(env){
  if(_flowStateFieldEnsured) return;
  try{
    const existingR=await ncFetch(env, `api/v2/meta/tables/${DEFAULT_LEADS_TABLE}/fields`);
    const existing=await existingR.json().catch(()=>({}));
    const names=new Set((existing.list||[]).map(f=>f.title));
    if(!names.has('flow_state')){
      await ncFetch(env, `api/v2/meta/tables/${DEFAULT_LEADS_TABLE}/fields`, {method:'POST', body:{title:'flow_state', uidt:'LongText'}});
    }
    _flowStateFieldEnsured=true;
  }catch(e){ console.error('[automations] ensureFlowStateField failed', e.message); }
}

function parseFlowState(lead){ try{ return JSON.parse(lead.flow_state||'{}'); }catch(e){ return {}; } }
function flowLeadConvId(lead){ return lead.ConversationID||lead.conv_id||lead.ConversationId||lead.chatwoot_conv_id||null; }
function fillFlowTokens(text, lead){
  return String(text||'').replace(/\{name\}/gi, lead.Name||'there').replace(/\{stage\}/gi, lead.Stage||'').replace(/\{phone\}/gi, lead.Phone||'');
}

// Manual "Enroll matching leads now" — the one enrollment path triggered by an explicit request
// instead of the cron tick (same split as the Email module's send-init vs. its own cron-free
// send-one loop). Leads already enrolled (active or done) in this flow are left alone.
async function handleAutomationFlowEnroll(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const {list}=await getAutomationFlows(env, payload.cid);
  const flow=list.find(f=>f.id===body.id);
  if(!flow) return json({error:'Flow not found'}, 404);
  await ensureFlowStateField(env);

  const where=leadsAudienceWhereClause(payload.cid, flow.segment);
  let enrolled=0, page=1;
  while(true){
    const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}&limit=200&offset=${(page-1)*200}&fields=Id,flow_state,OptOut,Handover,Stage`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const rows=data?.list||[];
    if(!rows.length) break;
    for(const lead of rows){
      if(lead.OptOut==='Yes'||lead.Handover==='Yes'||AUTOMATION_TERMINAL_STAGES.has(lead.Stage)) continue;
      const state=parseFlowState(lead);
      if(state[flow.id]) continue;
      state[flow.id]={step:0, next_at:new Date().toISOString(), enrolled_at:new Date().toISOString(), status:'active'};
      await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'PATCH', body:{Id:lead.Id, flow_state:JSON.stringify(state)}});
      enrolled++;
    }
    if(rows.length<200) break;
    page++;
  }
  flow.stats=flow.stats||{enrolled:0,completed:0};
  flow.stats.enrolled=(flow.stats.enrolled||0)+enrolled;
  await saveAutomationFlows(env, payload.cid, list);
  return json({ok:true, enrolled});
}

// Same Chatwoot call shape as handleBroadcastSendDm above / recovery.js's sendPlainMessage.
async function sendFlowWhatsappDm(c, convId, content){
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${convId}/messages`, {
    method:'POST', headers:{api_access_token:c.chatwoot_token, 'Content-Type':'application/json'},
    body:JSON.stringify({content, message_type:'outgoing', private:false})
  });
  if(!r.ok) throw new Error('Chatwoot send failed: HTTP '+r.status);
}
// Same Chatwoot template shape as handleBroadcastSendTemplate above.
async function sendFlowWhatsappTemplate(c, convId, step, leadName){
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${convId}/messages`, {
    method:'POST', headers:{api_access_token:c.chatwoot_token, 'Content-Type':'application/json'},
    body:JSON.stringify({content:step.template_name, message_type:'outgoing', private:false, template_params:{
      name:step.template_name, category:step.category||'MARKETING', language:step.language||'en',
      processed_params:{1:leadName||'there'}
    }})
  });
  if(!r.ok) throw new Error('Chatwoot template send failed: HTTP '+r.status);
}
// Reuses sendClientResendEmail plus the same unsubscribe-link footer handleEmailCampaignSendOne
// sends — a flow's email step is just a one-recipient version of the same campaign send.
async function sendFlowEmail(env, c, lead, step){
  if(!lead.Email || lead.EmailOptOut==='Yes') return; // same channel-specific opt-out email campaigns respect
  const unsubToken=await hmacHex(env, `unsub:${lead.Id}`);
  const unsubLink=`${env.WORKER_BASE_URL}/email/unsubscribe?lead_id=${lead.Id}&token=${unsubToken}`;
  const html=`${step.html_body}<p style="font-size:11px;color:#888;margin-top:24px">Don't want these emails? <a href="${unsubLink}">Unsubscribe</a>.</p>`;
  const result=await sendClientResendEmail(c, {to:lead.Email, subject:step.subject, html});
  if(!result.ok) throw new Error(result.error||'Resend send failed');
}

// Runs every step starting at entry.step that doesn't need a wait, stopping at the next
// unexpired 'wait' (or the end of the flow). Mutates `entry` (step/next_at/status) in place —
// the caller persists lead.flow_state right after this returns.
async function advanceFlowLead(env, c, lead, flow, entry){
  while(entry.step<flow.steps.length){
    const step=flow.steps[entry.step];
    if(step.type==='wait'){
      entry.next_at=new Date(Date.now()+step.hours*3600000).toISOString();
      entry.step++;
      return {completed:false};
    }
    const convId=flowLeadConvId(lead);
    if(step.type==='send_whatsapp_dm'){
      if(convId && c.chatwoot_base && c.chatwoot_account_id && c.chatwoot_token) await sendFlowWhatsappDm(c, convId, fillFlowTokens(step.message, lead));
    }else if(step.type==='send_whatsapp_template'){
      if(convId && c.chatwoot_base && c.chatwoot_account_id && c.chatwoot_token) await sendFlowWhatsappTemplate(c, convId, step, lead.Name);
    }else if(step.type==='send_email'){
      await sendFlowEmail(env, c, lead, step);
    }else if(step.type==='update_field'){
      await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'PATCH', body:{Id:lead.Id, [step.field]:step.value}});
    }else if(step.type==='send_whatsapp_media'){
      // Drive-fetch-and-forward as a real attachment (video/image/audio/PDF) — see
      // sendDriveMediaToChatwoot below, the same fetch-bytes-and-FormData pattern
      // hospitalitySendUnitMedia already uses for unit photos/video.
      if(convId && c.chatwoot_base && c.chatwoot_account_id && c.chatwoot_token) await sendDriveMediaToChatwoot(c, convId, step.media_url, fillFlowTokens(step.caption||'', lead));
    }
    entry.step++;
  }
  entry.status='done';
  entry.next_at=null;
  return {completed:true};
}

// Cron Trigger entry point (every 15 min — see wrangler.toml [triggers]). Loops every client
// with at least one active flow, same paginated-CLIENTS-scan shape as
// runDailyHealthCheckForAllClients above.
async function runAutomationFlowsForAllClients(env){
  let page=1;
  while(true){
    const r=await ncFetch(env, `api/v2/tables/${CLIENTS_TABLE}/records?limit=200&offset=${(page-1)*200}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const rows=data?.list||[];
    if(!rows.length) break;
    for(const c of rows){
      let flows=[]; try{ flows=JSON.parse(c.automation_flows||'[]'); }catch(e){}
      const activeFlows=flows.filter(f=>f.active);
      if(!activeFlows.length) continue;
      try{ await processClientAutomationFlows(env, c, flows, activeFlows); }
      catch(e){ console.error('[automations] tick failed for client', c.Id, e.message); }
    }
    if(rows.length<200) break;
    page++;
  }
}

async function processClientAutomationFlows(env, c, allFlows, activeFlows){
  if(!c.chatwoot_base && !c.resend_api_key) return; // nothing this client could actually send with
  await ensureFlowStateField(env);
  let flowsChanged=false;

  for(const flow of activeFlows){
    // ── Ongoing auto-enrollment (manual-trigger flows only enroll via handleAutomationFlowEnroll) ──
    if(flow.trigger.type==='new_lead' || flow.trigger.type==='stage_enter'){
      const where=leadsAudienceWhereClause(c.Id, flow.segment);
      const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}&limit=100&sort=-Date&fields=Id,flow_state,OptOut,Handover,Stage`);
      const data=await r.json().catch(()=>({}));
      for(const lead of (data?.list||[])){
        if(lead.OptOut==='Yes'||lead.Handover==='Yes'||AUTOMATION_TERMINAL_STAGES.has(lead.Stage)) continue;
        const state=parseFlowState(lead);
        if(state[flow.id]) continue;
        state[flow.id]={step:0, next_at:new Date().toISOString(), enrolled_at:new Date().toISOString(), status:'active'};
        await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'PATCH', body:{Id:lead.Id, flow_state:JSON.stringify(state)}});
        flow.stats=flow.stats||{enrolled:0,completed:0}; flow.stats.enrolled++; flowsChanged=true;
      }
    }
    // "No reply in N hours" — same silence signal recovery.js's ladder already uses
    // (LastMsgAt), just enrolling into this flow's own steps instead of a hardcoded ladder.
    // Still honors the flow's own segment (e.g. restrict to certain Stages/tags) on top of that.
    if(flow.trigger.type==='no_reply'){
      const where=leadsAudienceWhereClause(c.Id, flow.segment)+'~and(LastMsgAt,notblank)';
      const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}&limit=200&fields=Id,flow_state,OptOut,Handover,Stage,LastMsgAt`);
      const data=await r.json().catch(()=>({}));
      const cutoffMs=Date.now()-flow.trigger.no_reply_hours*3600000;
      for(const lead of (data?.list||[])){
        if(lead.OptOut==='Yes'||lead.Handover==='Yes'||AUTOMATION_TERMINAL_STAGES.has(lead.Stage)) continue;
        if(new Date(lead.LastMsgAt).getTime()>cutoffMs) continue; // still within the reply window
        const state=parseFlowState(lead);
        if(state[flow.id]) continue;
        state[flow.id]={step:0, next_at:new Date().toISOString(), enrolled_at:new Date().toISOString(), status:'active'};
        await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'PATCH', body:{Id:lead.Id, flow_state:JSON.stringify(state)}});
        flow.stats=flow.stats||{enrolled:0,completed:0}; flow.stats.enrolled++; flowsChanged=true;
      }
    }

    // ── Advance leads already enrolled and due ──
    // flow_state is a LongText JSON blob, so it can't be filtered "due now" server-side — narrow
    // with a cheap `like` on the flow id (present as a JSON object key), then check next_at
    // precisely in memory. Same trade-off recovery.js accepts for its own ladder fields.
    const dueWhere=`(ClientId,eq,${c.Id})~and(flow_state,like,%22${flow.id}%22)`;
    let page=1;
    while(true){
      const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(dueWhere)}&limit=100&offset=${(page-1)*100}`);
      if(!r.ok) break;
      const data=await r.json().catch(()=>({}));
      const rows=data?.list||[];
      if(!rows.length) break;
      for(const lead of rows){
        const state=parseFlowState(lead);
        const entry=state[flow.id];
        if(!entry || entry.status!=='active') continue;
        if(lead.OptOut==='Yes'||lead.Handover==='Yes'||AUTOMATION_TERMINAL_STAGES.has(lead.Stage)){
          entry.status='exited';
          await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'PATCH', body:{Id:lead.Id, flow_state:JSON.stringify(state)}});
          continue;
        }
        if(new Date(entry.next_at).getTime()>Date.now()) continue; // not due yet

        try{
          const advanced=await advanceFlowLead(env, c, lead, flow, entry);
          if(advanced.completed){ flow.stats=flow.stats||{enrolled:0,completed:0}; flow.stats.completed++; flowsChanged=true; }
          await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'PATCH', body:{Id:lead.Id, flow_state:JSON.stringify(state)}});
        }catch(e){ console.error('[automations] step failed for lead', lead.Id, 'flow', flow.id, e.message); }
        await new Promise(res=>setTimeout(res, 300)); // pacing, same spirit as recovery.js's SEND_DELAY_MS
      }
      if(rows.length<100) break;
      page++;
    }
  }

  if(flowsChanged){
    try{ await patchClientFields(env, c.Id, {automation_flows:JSON.stringify(allFlows)}); }catch(e){}
  }
}

/* ── CALENDAR EVENTS (Task Manager's Calendar module — SETUP.md "Calendar events") ──
   Lets a rep put an important date on the calendar — a lead follow-up, an Exhibition/expo, a
   Startup Mission Program date, a Birthday, or any other important date — and assign a Meta-
   approved WhatsApp template to it up front, so the actual outreach fires on its own on the day
   instead of relying on someone remembering to send it manually. Storage mirrors
   automation_flows exactly (a JSON array on CLIENTS, no dedicated table for the events
   themselves); migrations/0014_calendar_events.sql adds one small D1 table purely to dedupe
   sends, so a recurring yearly event (a Birthday) sends exactly once per occurrence, and a
   segment event sends to each matching lead exactly once per occurrence.
   Audience is one of three shapes, chosen per event:
   - 'lead'    — a single existing Lead (the "Lead Follow-up" case).
   - 'segment' — every Lead matching a Stage/Tag filter, same shape/where-clause as Automations'
     segment audience — for a broadcast-style event like an Exhibition invite.
   - 'contact' — a name + phone not yet in the CRM at all (a personal contact's Birthday, say).
     The first time this fires, a minimal Lead row is created for them (Stage 'new', tagged
     "Calendar Contact") and its id is written back onto the event (`contact_lead_id`), so every
     later occurrence (next year's Birthday) reuses the same lead instead of creating a new one.
   Template variables are resolved once at event-creation time, not per-recipient — an Exhibition/
   Important Date's details are the same for everyone invited; `personalize_first` optionally
   substitutes {{1}} with each individual recipient's own Name.
   **Known limitation, same one this file already has elsewhere for any brand-new contact**: a
   template can only be delivered into an existing Chatwoot conversation — there's no proactive
   "start a new WhatsApp conversation" capability anywhere in this app (conversations are only
   ever created by an inbound message hitting the engine webhook). A 'contact' or newly-added
   'lead' who has never messaged in yet has this fire silently skip them (not retried, no error
   surfaced beyond the client-side event list) until they've sent at least one real WhatsApp
   message — every occurrence after that sends fine. */
const CALENDAR_EVENT_TYPES=['Lead Follow-up','Exhibition','Startup Mission Program','Birthday','Important Date'];
const CALENDAR_AUDIENCE_MODES=new Set(['lead','segment','contact']);

async function getCalendarEvents(env, clientId){
  const c=await getClientById(env, clientId);
  let list=[]; try{ list=JSON.parse(c?.calendar_events||'[]'); }catch(e){}
  return {client:c, list};
}
async function saveCalendarEvents(env, clientId, list){
  await patchClientFields(env, clientId, {calendar_events:JSON.stringify(list)});
}

function validateCalendarEvent(body){
  if(!String(body?.title||'').trim()) return 'title required';
  if(!CALENDAR_EVENT_TYPES.includes(body?.type)) return 'invalid type';
  if(!/^\d{4}-\d{2}-\d{2}$/.test(body?.date||'')) return 'a valid date (YYYY-MM-DD) is required';
  if(!CALENDAR_AUDIENCE_MODES.has(body?.audience_mode)) return 'invalid audience_mode';
  if(body.audience_mode==='lead' && !body.lead_id) return 'lead_id required for a lead-audience event';
  if(body.audience_mode==='segment' && !(Array.isArray(body.segment?.stage)&&body.segment.stage.length) && !(Array.isArray(body.segment?.tags_any)&&body.segment.tags_any.length)) return 'a segment-audience event needs at least one Stage or Tag';
  if(body.audience_mode==='contact' && (!String(body.contact_name||'').trim()||!String(body.contact_phone||'').trim())) return 'contact_name and contact_phone required for a contact-audience event';
  return null;
}
function calendarEventFromBody(body, existing){
  return {
    ...(existing||{}),
    title:String(body.title).trim(), type:body.type, date:body.date,
    recurring_yearly:!!body.recurring_yearly, audience_mode:body.audience_mode,
    lead_id:body.audience_mode==='lead'?Number(body.lead_id):null,
    lead_name:body.audience_mode==='lead'?String(body.lead_name||''):'',
    segment:body.audience_mode==='segment'?{stage:Array.isArray(body.segment?.stage)?body.segment.stage:[], tags_any:Array.isArray(body.segment?.tags_any)?body.segment.tags_any:[]}:null,
    contact_name:body.audience_mode==='contact'?String(body.contact_name||'').trim():(existing?.contact_name||''),
    contact_phone:body.audience_mode==='contact'?String(body.contact_phone||'').trim():(existing?.contact_phone||''),
    contact_lead_id:body.audience_mode==='contact'?(existing?.contact_lead_id||null):null,
    template_name:String(body.template_name||''), template_category:String(body.template_category||'MARKETING'), template_language:String(body.template_language||'en'),
    template_vars:Array.isArray(body.template_vars)?body.template_vars.map(String):[],
    personalize_first:!!body.personalize_first,
    notes:String(body.notes||''),
  };
}

async function handleCalendarEventsList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {list}=await getCalendarEvents(env, payload.cid);
  return json({list});
}
// Google Calendar push for a Calendar Event — always all-day (these are dates, never timed
// appointments) using RRULE:FREQ=YEARLY for a recurring one. Best-effort: a client who hasn't
// connected Google Calendar just gets gcal_event_id staying null, same "optional integration
// degrades gracefully" pattern used everywhere else in this file.
async function gcalSyncCalendarEvent(env, clientId, event){
  const c=await getClientById(env, clientId);
  if(!c?.gcal_refresh_token||!c?.gcal_calendar_id) return event.gcal_event_id||null;
  return gcalUpsertEvent(env, c, {gcalEventId:event.gcal_event_id||null, title:event.title, notes:event.notes, date:event.date, allDay:true, recurrenceYearly:!!event.recurring_yearly});
}

async function handleCalendarEventCreate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const err=validateCalendarEvent(body);
  if(err) return json({error:err}, 400);
  const {list}=await getCalendarEvents(env, payload.cid);
  const event={id:'ce_'+Date.now().toString(36)+Math.random().toString(36).slice(2,8), created_at:new Date().toISOString(), ...calendarEventFromBody(body)};
  event.gcal_event_id=await gcalSyncCalendarEvent(env, payload.cid, event);
  list.push(event);
  await saveCalendarEvents(env, payload.cid, list);
  return json({ok:true, event});
}
async function handleCalendarEventUpdate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const {list}=await getCalendarEvents(env, payload.cid);
  const idx=list.findIndex(e=>e.id===body.id);
  if(idx===-1) return json({error:'Event not found'}, 404);
  const merged={...list[idx], ...body};
  const err=validateCalendarEvent(merged);
  if(err) return json({error:err}, 400);
  list[idx]=calendarEventFromBody(merged, list[idx]);
  list[idx].gcal_event_id=await gcalSyncCalendarEvent(env, payload.cid, list[idx]);
  await saveCalendarEvents(env, payload.cid, list);
  return json({ok:true, event:list[idx]});
}
async function handleCalendarEventDelete(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  if(!body.id) return json({error:'id required'}, 400);
  const {client:c, list}=await getCalendarEvents(env, payload.cid);
  const removed=list.find(e=>e.id===body.id);
  if(!removed) return json({error:'Event not found'}, 404);
  if(removed.gcal_event_id && c?.gcal_refresh_token) await gcalDeleteEvent(env, c, removed.gcal_event_id);
  const next=list.filter(e=>e.id!==body.id);
  await saveCalendarEvents(env, payload.cid, next);
  return json({ok:true});
}

// This year's occurrence, for a recurring event, is just this event's own month/day paired with
// the current year — a non-recurring event only ever has the one literal date. Used both to know
// whether an event is "due today" and as the dedupe key (calendar_event_sends.occurrence_key), so
// a recurring event correctly gets a fresh key (and therefore a fresh send) every year.
function calendarOccurrenceDate(event, today){
  if(!event.recurring_yearly) return event.date;
  const [, m, d]=event.date.split('-');
  return `${today.getFullYear()}-${m}-${d}`;
}
function calendarEventDueToday(event, today, todayStr){
  return calendarOccurrenceDate(event, today)===todayStr;
}
function calendarTemplateBody(t){
  if(t?.components){ const b=t.components.find(c=>(c.type||'').toUpperCase()==='BODY'); if(b) return b.text||''; }
  return t?.body||t?.content||'';
}
function calendarBuildContent(bodyText, vars, personalizeFirst, recipientName){
  let content=bodyText;
  (vars||[]).forEach((v,idx)=>{
    const val=(idx===0&&personalizeFirst)?(recipientName||v||''):(v||'');
    content=content.replace(new RegExp(`\\{\\{${idx+1}\\}\\}`,'g'), val);
  });
  return content;
}
async function calendarFetchTemplateBody(env, c, templateName){
  if(!c?.chatwoot_base||!c?.chatwoot_account_id||!c?.chatwoot_token||!c?.chatwoot_inbox_id) return null;
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes/${c.chatwoot_inbox_id}`, {headers:{api_access_token:c.chatwoot_token}});
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return null;
  const t=(data?.message_templates||[]).find(x=>x.name===templateName);
  return t?calendarTemplateBody(t):null;
}
// Resolves an event's recipients to an array of Lead rows (fields: Id, Name, Phone, ConversationID
// etc.) regardless of audience_mode. For 'contact', creates the backing Lead the first time this
// event ever fires and mutates `event.contact_lead_id` in place — the caller is responsible for
// persisting the events array afterward (both call sites below already do a single batched save).
async function calendarResolveLeads(env, clientId, event){
  if(event.audience_mode==='lead'){
    if(!event.lead_id) return [];
    const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records/${event.lead_id}`);
    const lead=await r.json().catch(()=>null);
    return (r.ok&&lead)?[lead]:[];
  }
  if(event.audience_mode==='segment'){
    const where=leadsAudienceWhereClause(clientId, event.segment);
    const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}~and(OptOut,neq,Yes)&limit=500`);
    const data=await r.json().catch(()=>({}));
    return data?.list||[];
  }
  if(event.audience_mode==='contact'){
    if(event.contact_lead_id){
      const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records/${event.contact_lead_id}`);
      const lead=await r.json().catch(()=>null);
      if(r.ok&&lead) return [lead];
    }
    const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records`, {method:'POST', body:{ClientId:String(clientId), Name:event.contact_name, Phone:event.contact_phone, Stage:'new', Tags:'Calendar Contact'}});
    const created=await r.json().catch(()=>null);
    if(!r.ok||!created?.Id) return [];
    event.contact_lead_id=created.Id;
    return [created];
  }
  return [];
}
async function calendarSendEventToLeads(env, c, event, leads, occurrenceKey){
  if(!event.template_name || !leads.length) return;
  const bodyText=await calendarFetchTemplateBody(env, c, event.template_name);
  if(bodyText==null) return; // template no longer exists / Chatwoot not configured — nothing sane to send
  for(const lead of leads){
    const convId=flowLeadConvId(lead);
    if(!convId) continue; // known limitation — see this module's header comment
    const already=await env.DB.prepare(`SELECT id FROM calendar_event_sends WHERE event_id=? AND lead_id=? AND occurrence_key=?`)
      .bind(event.id, lead.Id, occurrenceKey).first();
    if(already) continue;
    const content=calendarBuildContent(bodyText, event.template_vars, event.personalize_first, lead.Name);
    const processedParams={}; (event.template_vars||[]).forEach((v,idx)=>{ processedParams[idx+1]=(idx===0&&event.personalize_first)?(lead.Name||v||''):(v||''); });
    try{
      const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${convId}/messages`, {
        method:'POST', headers:{api_access_token:c.chatwoot_token, 'Content-Type':'application/json'},
        body:JSON.stringify({content, message_type:'outgoing', private:false, template_params:{name:event.template_name, category:event.template_category||'MARKETING', language:event.template_language||'en', processed_params:processedParams}})
      });
      if(r.ok){
        await env.DB.prepare(`INSERT OR IGNORE INTO calendar_event_sends (client_id, event_id, lead_id, occurrence_key, sent_at) VALUES (?,?,?,?,?)`)
          .bind(Number(c.Id), event.id, lead.Id, occurrenceKey, new Date().toISOString()).run();
      }
    }catch(e){ /* best-effort — one failed send in a segment shouldn't stop the rest */ }
  }
}
// Daily cron path (piggybacked on the same 0 2 * * * tick as the health check/Pipeline
// followups — day-granularity, same reasoning as those two).
async function runCalendarEventsForAllClients(env){
  let page=1;
  const today=new Date();
  const todayStr=today.toISOString().slice(0,10);
  while(true){
    const r=await ncFetch(env, `api/v2/tables/${CLIENTS_TABLE}/records?limit=200&offset=${(page-1)*200}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const rows=data?.list||[];
    if(!rows.length) break;
    for(const c of rows){
      let events=[]; try{ events=JSON.parse(c.calendar_events||'[]'); }catch(e){}
      const due=events.filter(ev=>calendarEventDueToday(ev, today, todayStr));
      if(!due.length) continue;
      try{
        let changed=false;
        for(const event of due){
          const before=event.contact_lead_id;
          const leads=await calendarResolveLeads(env, c.Id, event);
          if(event.contact_lead_id!==before) changed=true;
          await calendarSendEventToLeads(env, c, event, leads, calendarOccurrenceDate(event, today));
        }
        if(changed) await saveCalendarEvents(env, c.Id, events);
      }catch(e){ console.error('[calendar-events] failed for client', c.Id, e.message); }
    }
    if(rows.length<200) break;
    page++;
  }
}
// Manual "send now" — lets a rep test an event's template immediately, or fire an Exhibition
// invite on demand instead of waiting for its calendar date. Ignores the dedupe table entirely
// (an explicit manual click should always go out), but still records the send so the *next*
// scheduled occurrence doesn't double-send the same day.
async function handleCalendarEventSendNow(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {id}=await request.json().catch(()=>({}));
  if(!id) return json({error:'id required'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  let events=[]; try{ events=JSON.parse(c.calendar_events||'[]'); }catch(e){}
  const event=events.find(e=>e.id===id);
  if(!event) return json({error:'Event not found'}, 404);
  if(!event.template_name) return json({error:'This event has no template assigned yet.'}, 400);
  const before=event.contact_lead_id;
  const leads=await calendarResolveLeads(env, payload.cid, event);
  if(!leads.length) return json({error:'No recipients resolved for this event.'}, 400);
  const occurrenceKey='manual-'+new Date().toISOString();
  await calendarSendEventToLeads(env, c, event, leads, occurrenceKey);
  if(event.contact_lead_id!==before) await saveCalendarEvents(env, payload.cid, events);
  return json({ok:true, sent_to:leads.length});
}

/* ── Review Request module — automated "ask for a review N days after a deal closes" ─────────
   Deliberately its own module rather than something built on the generic Automations engine above:
   a client would otherwise have to hand-build a flow (trigger=stage_enter, one wait step, one
   send_whatsapp_dm step) with no click-through visibility at all, since a plain flow message has
   no tracked link. This module adds exactly that: reuses ClosedAt (added for the Revenue Forecast
   dashboard — see there — "when did this deal actually finish") as its trigger signal,
   sendFlowWhatsappDm/fillFlowTokens (Automations' own Chatwoot send + templating) to actually
   send, and the same HMAC-signed-link pattern handleEmailUnsubscribe already uses below for a
   stateless, tamper-proof public click-tracking link.

   Storage: Cloudflare D1 (env.DB), not NocoDB — see migrations/0001_reviews_referrals.sql. This
   module's config (review_config) and per-lead request/click state (review_requests) are data
   this app invented with no other reader anywhere else in it, unlike Country/CompanyName (added
   the same week, see "Data enrichment on capture") which every existing lead view already reads
   out of NocoDB — so only this module's own tables went to D1, not the lead record itself.
   Stage/DealValue/OptOut/ClosedAt/ConversationID etc. are still read straight from NocoDB below;
   this module doesn't duplicate or cache any of that. */
const REVIEW_DEFAULT_MESSAGE="Hi {name}! 🙏 So glad we could help. If you have a moment, we'd really appreciate a quick review — it means a lot to a small team like ours: {review_link}";

async function reviewClickLink(env, leadId){
  const token=await hmacHex(env, `review:${leadId}`);
  return `${env.WORKER_BASE_URL}/reviews/click?lead_id=${leadId}&token=${token}`;
}

// Cron Trigger entry point — dispatched from the same */15 min tick as
// runAutomationFlowsForAllClients (a multi-hour/day delay doesn't need finer granularity than
// that). Reads D1's own review_config table directly — only clients that ever turned this on,
// not a full NocoDB CLIENTS scan the way the pre-D1 version of this function needed.
async function sweepReviewRequests(env){
  const {results}=await env.DB.prepare(`SELECT client_id, stages_json, delay_hours, message FROM review_config WHERE enabled=1`).all();
  for(const cfg of (results||[])){
    try{ await processClientReviewRequests(env, cfg); }
    catch(e){ console.error('[reviews] tick failed for client', cfg.client_id, e.message); }
  }
}

async function processClientReviewRequests(env, cfg){
  let stages=[]; try{ stages=JSON.parse(cfg.stages_json||'[]'); }catch(e){}
  if(!stages.length) return;
  const c=await getClientById(env, cfg.client_id);
  if(!c?.review_link || !c.chatwoot_base) return;
  const delayHours=Number(cfg.delay_hours)||72;
  // One D1 round-trip for "who's already been asked," then filtered in memory against the NocoDB
  // candidate scan below — cheaper than a D1 SELECT per candidate lead, and D1 has no way to join
  // against a NocoDB `where` clause directly.
  const {results:already}=await env.DB.prepare(`SELECT lead_id FROM review_requests WHERE client_id=? AND requested_at IS NOT NULL`).bind(cfg.client_id).all();
  const alreadySet=new Set((already||[]).map(r=>r.lead_id));
  const stageOr=stages.map(s=>`(Stage,eq,${s})`).join('~or');
  const where=`(ClientId,eq,${cfg.client_id})~and(${stageOr})~and(ClosedAt,notblank)`;
  let page=1;
  while(true){
    const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(where)}&limit=100&offset=${(page-1)*100}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const rows=data?.list||[];
    if(!rows.length) break;
    for(const lead of rows){
      if(alreadySet.has(lead.Id)) continue;
      if(lead.OptOut==='Yes') continue;
      const closedMs=new Date(lead.ClosedAt).getTime();
      if(!isFinite(closedMs) || Date.now()-closedMs<delayHours*3600000) continue;
      const convId=flowLeadConvId(lead);
      if(!convId) continue;
      try{
        const link=await reviewClickLink(env, lead.Id);
        const template=cfg.message||REVIEW_DEFAULT_MESSAGE;
        const content=fillFlowTokens(template, lead).replace(/\{review_link\}/gi, link);
        await sendFlowWhatsappDm(c, convId, content);
        await env.DB.prepare(`INSERT INTO review_requests (lead_id, client_id, requested_at) VALUES (?,?,?)`)
          .bind(lead.Id, Number(cfg.client_id), new Date().toISOString()).run();
      }catch(e){ console.error('[reviews] send failed for lead', lead.Id, e.message); }
      await new Promise(res=>setTimeout(res, 300)); // pacing, same spirit as recovery.js's SEND_DELAY_MS
    }
    if(rows.length<100) break;
    page++;
  }
}

// Public click-tracking redirect (`GET /reviews/click?lead_id=&token=`) — HMAC-verified with the
// same constant-time compare handleEmailUnsubscribe uses below, no session. Stamps clicked_at in
// D1 once (never overwritten) so click-through can be measured (Reviews tab stats), then redirects
// to the client's own review_link — the destination platform's (Google/Trustpilot/etc.) own
// analytics never sees this app's tracking step. `client_id` comes straight off the D1 row itself
// (stored there at send time), so this route needs no NocoDB lead lookup at all — only one NocoDB
// read, for the CLIENTS row's review_link, which still lives there (see file-header comment above).
async function handleReviewClick(request, env){
  const url=new URL(request.url);
  const leadId=parseInt(url.searchParams.get('lead_id'),10);
  const token=url.searchParams.get('token')||'';
  if(!leadId||!token) return new Response('Invalid link.', {status:400});
  const expected=await hmacHex(env, `review:${leadId}`);
  if(expected.length!==token.length) return new Response('Invalid link.', {status:400});
  let diff=0;
  for(let i=0;i<expected.length;i++) diff|=expected.charCodeAt(i)^token.charCodeAt(i);
  if(diff!==0) return new Response('Invalid link.', {status:400});
  const row=await env.DB.prepare(`SELECT client_id, clicked_at FROM review_requests WHERE lead_id=?`).bind(leadId).first();
  if(!row) return new Response('Link expired.', {status:404});
  const c=await getClientById(env, row.client_id);
  if(!c?.review_link) return new Response('Link expired.', {status:404});
  if(!row.clicked_at){
    await env.DB.prepare(`UPDATE review_requests SET clicked_at=? WHERE lead_id=? AND clicked_at IS NULL`).bind(new Date().toISOString(), leadId).run();
  }
  return Response.redirect(c.review_link, 302);
}

// Session-gated config — reads/writes D1's review_config (one row per client), upserted via
// SQLite's ON CONFLICT (D1 is SQLite under the hood).
async function handleReviewsConfigSet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const enabled=body.review_request_enabled==='Yes'?1:0;
  const stagesJson=JSON.stringify(Array.isArray(body.review_request_stages)?body.review_request_stages:[]);
  const delayHours=parseInt(body.review_request_delay_hours)||72;
  const message=String(body.review_request_message||'').trim()||null;
  await env.DB.prepare(`INSERT INTO review_config (client_id, enabled, stages_json, delay_hours, message) VALUES (?,?,?,?,?)
    ON CONFLICT(client_id) DO UPDATE SET enabled=excluded.enabled, stages_json=excluded.stages_json, delay_hours=excluded.delay_hours, message=excluded.message`)
    .bind(Number(payload.cid), enabled, stagesJson, delayHours, message).run();
  return json({ok:true});
}
async function handleReviewsConfigGet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  const cfg=await env.DB.prepare(`SELECT enabled, stages_json, delay_hours, message FROM review_config WHERE client_id=?`).bind(Number(payload.cid)).first();
  let stages=[]; try{ stages=JSON.parse(cfg?.stages_json||'[]'); }catch(e){}
  return json({
    enabled: !!cfg?.enabled,
    stages, delay_hours: cfg?.delay_hours || 72,
    message: cfg?.message || REVIEW_DEFAULT_MESSAGE,
    review_link: c?.review_link||'',
  });
}
// Session-gated stats — Requests Sent / Clicked Through, computed straight from D1 rather than
// filtering allLeads client-side the way the pre-D1 version of the Reviews tab did (that data no
// longer lives on the lead record at all).
async function handleReviewsStats(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const row=await env.DB.prepare(`SELECT COUNT(*) AS requested, COUNT(clicked_at) AS clicked FROM review_requests WHERE client_id=? AND requested_at IS NOT NULL`).bind(Number(payload.cid)).first();
  return json({requested:row?.requested||0, clicked:row?.clicked||0});
}

/* ── Channels module ──────────────────────────────────────────────────────
   Automates what SETUP.md used to require by hand: creating the client's
   Chatwoot account, connecting WhatsApp via Meta Embedded Signup, and adding
   other inbox types — all driven from the dashboard's Channels page. ── */
async function handleChannelsCreateAccount(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.CHATWOOT_PLATFORM_TOKEN||!env.CHATWOOT_INSTANCE_BASE) return json({error:'Chatwoot platform credentials are not configured on the server.'}, 500);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  if(c.chatwoot_account_id && c.chatwoot_token) return json({error:'A Chatwoot account is already connected for this client.'}, 400);

  const acctR=await chatwootPlatformFetch(env, '/platform/api/v1/accounts', {method:'POST', body:{name:c.client_name||`Leadvyne client ${c.Id}`}});
  const acct=await acctR.json().catch(()=>({}));
  if(!acctR.ok||!acct?.id) return json({error:'Chatwoot account creation failed: '+(acct?.message||('HTTP '+acctR.status))}, 502);

  const email=c.authentik_email||`client-${c.Id}@leadvyne.local`;
  const password=crypto.randomUUID()+'Aa1!'; // account owner logs in via the one-click SSO link/access_token below, not this password directly — but it's stored (see chatwoot_owner_password below) so the User Management profile page can still surface it on request.
  const userR=await chatwootPlatformFetch(env, '/platform/api/v1/users', {method:'POST', body:{name:c.client_name||`Client ${c.Id}`, email, password}});
  const user=await userR.json().catch(()=>({}));
  if(!userR.ok||!user?.id||!user?.access_token) return json({error:'Chatwoot user creation failed: '+(user?.message||('HTTP '+userR.status))}, 502);

  const linkR=await chatwootPlatformFetch(env, `/platform/api/v1/accounts/${acct.id}/account_users`, {method:'POST', body:{user_id:user.id, role:'administrator'}});
  if(!linkR.ok) return json({error:'Failed to link the Chatwoot user to the account: HTTP '+linkR.status}, 502);

  await ensureClientColumns(env, ['chatwoot_owner_password']);
  await patchClientFields(env, payload.cid, {chatwoot_base:env.CHATWOOT_INSTANCE_BASE, chatwoot_account_id:String(acct.id), chatwoot_token:user.access_token, chatwoot_user_id:String(user.id), chatwoot_owner_password:password});
  return json({ok:true, chatwoot_base:env.CHATWOOT_INSTANCE_BASE, chatwoot_account_id:String(acct.id)});
}

async function handleChannelsWhatsappConnect(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.META_APP_ID||!env.META_APP_SECRET) return json({error:'Meta app credentials are not configured on the server.'}, 500);
  const {code, waba_id, phone_number_id}=await request.json().catch(()=>({}));
  if(!code||!waba_id||!phone_number_id) return json({error:'code, waba_id and phone_number_id are required'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_account_id||!c?.chatwoot_token||!c?.chatwoot_base) return json({error:'Connect a Chatwoot account first.'}, 400);
  const collision=await findOtherClientByField(env, 'waba_id', waba_id, payload.cid) || await findOtherClientByField(env, 'wa_phone_id', phone_number_id, payload.cid);
  if(collision) return json({error:'This WhatsApp Business Account / number is already connected to a different client.'}, 409);

  const planLimits=getPlanLimits(c.plan_tier);
  if(planLimits){
    const currentChannels=await countClientChannels(env, c);
    if(currentChannels>=planLimits.max_channels){
      return json({error:`Your ${planLimits.label} plan includes ${planLimits.max_channels} channel${planLimits.max_channels===1?'':'s'}. Upgrade your plan to connect another.`}, 402);
    }
  }

  const tokenR=await fetch(`https://graph.facebook.com/v18.0/oauth/access_token?client_id=${env.META_APP_ID}&client_secret=${env.META_APP_SECRET}&code=${encodeURIComponent(code)}`);
  const tokenData=await tokenR.json().catch(()=>({}));
  if(!tokenR.ok||!tokenData.access_token) return json({error:'Meta token exchange failed: '+(tokenData?.error?.message||('HTTP '+tokenR.status))}, 502);
  const wa_token=tokenData.access_token;

  // Best-effort — a failure here shouldn't block the connection; it can be re-subscribed from Meta Business Manager.
  await fetch(`https://graph.facebook.com/v18.0/${waba_id}/subscribed_apps`, {method:'POST', headers:{Authorization:`Bearer ${wa_token}`}}).catch(()=>{});

  const phoneR=await fetch(`https://graph.facebook.com/v18.0/${phone_number_id}?fields=display_phone_number`, {headers:{Authorization:`Bearer ${wa_token}`}});
  const phoneData=await phoneR.json().catch(()=>({}));
  const phone_number=phoneData?.display_phone_number||'';

  const inboxR=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes`, {
    method:'POST', headers:{api_access_token:c.chatwoot_token, 'Content-Type':'application/json'},
    body:JSON.stringify({
      name:`WhatsApp${phone_number?' - '+phone_number:''}`,
      channel:{type:'whatsapp', phone_number, provider:'whatsapp_cloud', provider_config:{business_account_id:waba_id, phone_number_id, api_key:wa_token}}
    })
  });
  const inbox=await inboxR.json().catch(()=>({}));
  if(!inboxR.ok||!inbox?.id) return json({error:'Chatwoot inbox creation failed: '+(inbox?.message||('HTTP '+inboxR.status))}, 502);

  // Best-effort — wires this Worker's /engine/webhook onto the new inbox (see
  // engineSyncChatwootWebhook) so no manual paste-in-Chatwoot step is needed, for every industry.
  // If this fails, it can still be added/fixed from Chatwoot's own UI, or re-synced later by
  // resaving any Settings field (handleNocodbPassthrough re-checks it on every CLIENTS PATCH).
  await engineSyncChatwootWebhook(env, {...c, chatwoot_inbox_id:String(inbox.id)});

  // wa_phone_id is Meta's internal phone-number-id (needed for API calls), not something a
  // customer can dial — wa_display_phone is the actual number (e.g. "+91 94969 71950") and is
  // what the public storefront's "Order on WhatsApp" links use, so they open the exact same
  // WhatsApp thread this bot/inbox replies from instead of a different, unrelated number.
  await ensureClientColumns(env, [META_CHANNEL_CREDENTIALS_FIELD]);
  const credential={inbox_id:String(inbox.id),waba_id,wa_token,wa_phone_id:phone_number_id,display_phone:phone_number};
  const patch={[META_CHANNEL_CREDENTIALS_FIELD]:JSON.stringify(mergeMetaChannelCredential(c,credential))};
  // Keep legacy fields pinned to the first connection so old callers and single-channel accounts
  // behave exactly as before. New callers select from the per-inbox map.
  if(!c.chatwoot_inbox_id) Object.assign(patch,{chatwoot_inbox_id:String(inbox.id),waba_id,wa_token,wa_phone_id:phone_number_id,wa_display_phone:phone_number});
  await patchClientFields(env, payload.cid, patch);
  return json({ok:true, chatwoot_inbox_id:String(inbox.id), waba_id, wa_phone_id:phone_number_id});
}

// POST /channels/whatsapp/extract-meta-creds
// Auto-extracts waba_id / wa_token / wa_phone_id from the Chatwoot inbox config so clients
// whose WhatsApp was set up directly in Chatwoot (not via Embedded Signup) don't have to copy
// credentials manually. Chatwoot's inbox show endpoint returns `channel_config` which includes
// `api_key` (the Meta access token), `phone_number_id`, and `business_account_id`.
async function handleChannelsExtractMetaCreds(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_base||!c?.chatwoot_account_id||!c?.chatwoot_token)
    return json({error:'Chatwoot is not fully configured. Make sure the Chatwoot account and WhatsApp inbox are connected first.'}, 400);
  const body=await request.json().catch(()=>({}));
  const inboxId=String(body.inbox_id||c.chatwoot_inbox_id||'');
  if(!inboxId) return json({error:'Select a WhatsApp channel first.'},400);
  // Fetch full inbox details — channel_config is returned for admin tokens
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes/${inboxId}`, {
    headers:{api_access_token:c.chatwoot_token}
  });
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:data?.message||('Chatwoot API '+r.status)}, 502);
  let credential=metaCredentialFromInbox(data,inboxId);
  if(!credential.wa_token||!credential.wa_phone_id||!credential.waba_id) credential=await detectMetaCredentialFromAccessibleAccounts(env,c,credential)||credential;
  if(!credential.wa_token||!credential.waba_id||!credential.wa_phone_id) return json({error:'Could not match this Chatwoot number to an accessible Meta WhatsApp account. Reconnect this number through Meta or save its credentials manually.'}, 400);
  await ensureClientColumns(env, [META_CHANNEL_CREDENTIALS_FIELD]);
  const existing=resolveMetaCredentials(c,{inbox_id:inboxId});
  const patch={[META_CHANNEL_CREDENTIALS_FIELD]:JSON.stringify(mergeMetaChannelCredential(c,credential))};
  if(!c.wa_token) Object.assign(patch,{waba_id:credential.waba_id,wa_token:credential.wa_token,wa_phone_id:credential.wa_phone_id,chatwoot_inbox_id:inboxId});
  await patchClientFields(env, payload.cid, patch);
  return json({ok:true,inbox_id:inboxId,already_configured:!!existing,saved:{waba_id:!!credential.waba_id,wa_token:!!credential.wa_token,wa_phone_id:!!credential.wa_phone_id}});
}

async function handleChannelsManualMetaCreds(request,env){
  const payload=await requireSession(request,env);
  if(!payload) return json({error:'Invalid or expired session'},401);
  const body=await request.json().catch(()=>({}));
  const waba_id=String(body.waba_id||'').trim(),wa_token=String(body.wa_token||'').trim(),wa_phone_id=String(body.wa_phone_id||'').trim(),inbox_id=String(body.inbox_id||'').trim();
  if(!waba_id||!wa_token) return json({error:'WABA ID and access token are required.'},400);
  const c=await getClientById(env,payload.cid);
  const patch={};
  if(inbox_id){
    await ensureClientColumns(env,[META_CHANNEL_CREDENTIALS_FIELD]);
    patch[META_CHANNEL_CREDENTIALS_FIELD]=JSON.stringify(mergeMetaChannelCredential(c,{inbox_id,waba_id,wa_token,wa_phone_id}));
  }
  if(!inbox_id||!c?.wa_token) Object.assign(patch,{waba_id,wa_token,...(wa_phone_id?{wa_phone_id}:{}),...(inbox_id?{chatwoot_inbox_id:inbox_id}:{})});
  await patchClientFields(env,payload.cid,patch);
  return json({ok:true,inbox_id,waba_id,wa_phone_id,wa_token_connected:true});
}

/* ── Instagram DM module (native — no Chatwoot) ────────────────────────────────────────────
   Deliberately separate from the WhatsApp connect flow above: WhatsApp's inbound webhook,
   normalization and outbound send all go through Chatwoot; Instagram's don't touch Chatwoot at
   all — this Worker owns the whole path itself (see /ig/webhook and engineSendInstagramReply
   further down). Uses "Instagram API with Instagram Login" (Meta's newer, simpler product —
   authenticates directly against the Instagram professional account, no Facebook Page involved),
   NOT the WhatsApp connect flow's Facebook-Login-for-Business shape above — it has its own
   Instagram app ID/secret (META_IG_APP_ID/META_IG_APP_SECRET, distinct from META_APP_ID/
   META_APP_SECRET), its own OAuth host (instagram.com/graph.instagram.com, not
   graph.facebook.com), and its authorize dialog doesn't render inside the Meta JS SDK's FB.login
   popup — so this is a plain browser-redirect OAuth, same shape as the Shopify module's
   handleShopifyOauthStart/Callback above (signOauthState carries the client id through the
   round trip), not an Embedded-Signup-style flow. See SETUP.md "Instagram DM module". ── */
// Deliberately NOT instagram_business_manage_comments — nothing in this module reads or manages
// comments (DMs only), and Meta's App Review rejects/flags permissions requested but not
// demonstrably used, so asking for it would just be unearned review risk for no functionality.
// instagram_business_content_publish WAS added (Content Calendar / Auto-Posting module, see
// marketingPublishContentPost below) — it reuses this same connection's ig_id/ig_access_token
// rather than a second OAuth flow, since Instagram Login tokens carry whatever scopes were
// granted at connect time. A client who connected Instagram *before* this scope existed is
// missing it on their existing token; auto-posting for them fails with Instagram's own
// "permission denied" until they disconnect and reconnect once from Settings → Integrations.
const META_IG_OAUTH_SCOPE='instagram_business_basic,instagram_business_manage_messages,instagram_business_content_publish';
const META_IG_GRAPH_VERSION='v24.0';
const META_IG_WEBHOOK_FIELDS=['messages','messaging_postbacks','message_reactions','messaging_seen'];

function instagramGraphError(data, fallback){
  return data?.error?.message||data?.error_message||fallback;
}

export async function subscribeInstagramWebhooks(igId, accessToken){
  const r=await fetch(`https://graph.instagram.com/${META_IG_GRAPH_VERSION}/${encodeURIComponent(igId)}/subscribed_apps`, {
    method:'POST', headers:{Authorization:`Bearer ${accessToken}`, 'Content-Type':'application/x-www-form-urlencoded'},
    body:new URLSearchParams({subscribed_fields:META_IG_WEBHOOK_FIELDS.join(',')})
  });
  const data=await r.json().catch(()=>({}));
  if(!r.ok||data.success===false) throw new Error(instagramGraphError(data, `Instagram webhook subscription failed (HTTP ${r.status})`));
  return data;
}

async function getInstagramHealth(c){
  const base={connected:!!(c?.ig_id&&c?.ig_access_token), token_valid:false, messages_subscribed:false, subscribed_fields:[], username:c?.ig_username||'', last_webhook_at:''};
  if(!base.connected) return base;
  const [profileR, subscriptionR]=await Promise.all([
    fetch(`https://graph.instagram.com/${META_IG_GRAPH_VERSION}/${encodeURIComponent(c.ig_id)}?fields=id,username`, {headers:{Authorization:`Bearer ${c.ig_access_token}`}}),
    fetch(`https://graph.instagram.com/${META_IG_GRAPH_VERSION}/${encodeURIComponent(c.ig_id)}/subscribed_apps`, {headers:{Authorization:`Bearer ${c.ig_access_token}`}})
  ]);
  const profile=await profileR.json().catch(()=>({}));
  const subscriptions=await subscriptionR.json().catch(()=>({}));
  const rows=Array.isArray(subscriptions?.data)?subscriptions.data:[];
  const fields=[...new Set(rows.flatMap(row=>Array.isArray(row.subscribed_fields)?row.subscribed_fields:[]))];
  const marker=String(c.ig_webhook_debug||'');
  return {...base, token_valid:profileR.ok&&!!profile.id, messages_subscribed:subscriptionR.ok&&fields.includes('messages'), subscribed_fields:fields,
    username:profile.username||base.username, last_webhook_at:marker.startsWith('received:')?marker.slice(9):'',
    error:profileR.ok?(subscriptionR.ok?'':instagramGraphError(subscriptions, `Subscription check failed (HTTP ${subscriptionR.status})`)):instagramGraphError(profile, `Token check failed (HTTP ${profileR.status})`)};
}

async function handleInstagramHealth(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  if(request.method==='POST'&&c.ig_id&&c.ig_access_token){
    try{ await subscribeInstagramWebhooks(c.ig_id, c.ig_access_token); }
    catch(e){ return json({...await getInstagramHealth(c), error:e.message}, 502); }
  }
  return json(await getInstagramHealth(c));
}

async function handleInstagramOauthStart(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.META_IG_APP_ID||!env.META_IG_APP_SECRET) return json({error:'Instagram app credentials are not configured on the server.'}, 500);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  if(c.ig_id && c.ig_access_token) return json({error:'Instagram is already connected for this client.'}, 400);

  const state=await signOauthState(env, payload.cid);
  const redirectUri=`${env.WORKER_BASE_URL}/ig/oauth/callback`;
  const url=`https://www.instagram.com/oauth/authorize?client_id=${env.META_IG_APP_ID}&redirect_uri=${encodeURIComponent(redirectUri)}&response_type=code&scope=${encodeURIComponent(META_IG_OAUTH_SCOPE)}&state=${encodeURIComponent(state)}`;
  return json({ok:true, url});
}

// Browser redirect target, not an XHR call — same "no frontend JS listens on this response"
// shape as handleShopifyOauthCallback above. Two token exchanges, per Meta's Instagram-Login
// docs: api.instagram.com first for a short-lived (1h) token, then graph.instagram.com to swap
// it for a long-lived (60-day) one — sending never uses the short-lived token.
async function handleInstagramOauthCallback(request, env){
  const url=new URL(request.url);
  const appBase=env.APP_BASE_URL||'https://app.leadvyne.com/dashboard.html';
  const fail=(msg)=>Response.redirect(`${appBase}?instagram=error&msg=${encodeURIComponent(msg)}`, 302);
  if(!env.META_IG_APP_ID||!env.META_IG_APP_SECRET) return fail('Instagram app credentials are not configured on the server.');
  const err=url.searchParams.get('error');
  if(err) return fail(err==='access_denied'?'Access was denied':err);
  const code=url.searchParams.get('code');
  const state=url.searchParams.get('state');
  if(!code) return fail('Invalid callback from Instagram');
  const statePayload=await verifyOauthState(env, state);
  if(!statePayload) return fail('This connection link expired — try connecting again from Integrations');

  const cForLimit=await getClientById(env, statePayload.cid);
  const planLimits=cForLimit?getPlanLimits(cForLimit.plan_tier):null;
  if(planLimits){
    const currentChannels=await countClientChannels(env, cForLimit);
    if(currentChannels>=planLimits.max_channels) return fail(`Your ${planLimits.label} plan includes ${planLimits.max_channels} channel${planLimits.max_channels===1?'':'s'} — upgrade your plan to connect another.`);
  }

  const redirectUri=`${env.WORKER_BASE_URL}/ig/oauth/callback`;
  const shortTokenR=await fetch('https://api.instagram.com/oauth/access_token', {
    method:'POST', headers:{'Content-Type':'application/x-www-form-urlencoded'},
    body:new URLSearchParams({client_id:env.META_IG_APP_ID, client_secret:env.META_IG_APP_SECRET, grant_type:'authorization_code', redirect_uri:redirectUri, code})
  });
  const shortTokenData=await shortTokenR.json().catch(()=>({}));
  if(!shortTokenR.ok||!shortTokenData.access_token) return fail('Instagram token exchange failed: '+(shortTokenData?.error_message||('HTTP '+shortTokenR.status)));
  const ig_id=String(shortTokenData.user_id||'');
  if(!ig_id) return fail('Instagram did not return an account id');

  const collision=await findOtherClientByField(env, 'ig_id', ig_id, statePayload.cid);
  if(collision) return fail('This Instagram account is already connected to a different client');

  const longTokenR=await fetch(`https://graph.instagram.com/access_token?grant_type=ig_exchange_token&client_secret=${env.META_IG_APP_SECRET}&access_token=${encodeURIComponent(shortTokenData.access_token)}`);
  const longTokenData=await longTokenR.json().catch(()=>({}));
  if(!longTokenR.ok||!longTokenData.access_token) return fail('Failed to obtain a long-lived Instagram token: '+(longTokenData?.error?.message||('HTTP '+longTokenR.status)));
  const ig_access_token=longTokenData.access_token;

  const profileR=await fetch(`https://graph.instagram.com/${META_IG_GRAPH_VERSION}/${ig_id}?fields=username&access_token=${encodeURIComponent(ig_access_token)}`);
  const profileData=await profileR.json().catch(()=>({}));
  if(!profileR.ok) return fail('Instagram profile verification failed: '+instagramGraphError(profileData, `HTTP ${profileR.status}`));
  try{ await subscribeInstagramWebhooks(ig_id, ig_access_token); }
  catch(e){ return fail(e.message+' — please check the Instagram webhook product configuration and try again.'); }

  await ensureClientColumns(env, ['ig_id','ig_access_token','ig_username','ig_connected_at','ig_webhook_debug']);
  // Verified, not the plain patchClientFields — this writes to columns ensureClientColumns may
  // have JUST created a moment ago in this same request, which is exactly the NocoDB
  // schema-cache-lag race ncPatchVerified exists for (see its own comment): a client's very first
  // Instagram connect ever on a given NocoDB base would otherwise show a false "connected ✓"
  // toast while ig_id silently never actually saved.
  const saveResult=await ncPatchVerified(env, statePayload.cid, {ig_id, ig_access_token, ig_username:profileData?.username||'', ig_connected_at:new Date().toISOString()});
  if(!saveResult.ok) return fail(saveResult.data?.error||'Failed to save the Instagram connection — try reconnecting.');
  return Response.redirect(`${appBase}?client=${statePayload.cid}&instagram=connected`, 302);
}

async function handleInstagramDisconnect(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env,payload.cid);
  if(c?.ig_id&&c?.ig_access_token){
    await fetch(`https://graph.instagram.com/${META_IG_GRAPH_VERSION}/${encodeURIComponent(c.ig_id)}/subscribed_apps`,{method:'DELETE',headers:{Authorization:`Bearer ${c.ig_access_token}`}}).catch(()=>{});
  }
  await patchClientFields(env, payload.cid, {ig_id:'', ig_access_token:'', ig_username:'', ig_connected_at:'', ig_webhook_debug:''});
  return json({ok:true});
}

// Meta's `signed_request` format (used for both the Deauthorize callback below and, historically,
// canvas/tab apps): `{base64url(HMAC-SHA256(payload, secret))}.{base64url(JSON payload)}`. Same
// base64url alphabet as hmacSignB64 above, but HMAC'd with the given secret directly rather than
// SESSION_SIGNING_KEY (this verifies a payload Meta itself signed, not one this Worker issued).
async function verifyMetaSignedRequest(secret, signedRequest){
  const [encodedSig, payload]=String(signedRequest||'').split('.');
  if(!encodedSig||!payload) return null;
  const key=await crypto.subtle.importKey('raw', new TextEncoder().encode(secret), {name:'HMAC', hash:'SHA-256'}, false, ['sign']);
  const sig=await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(payload));
  const expected=btoa(String.fromCharCode(...new Uint8Array(sig))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  if(expected!==encodedSig) return null;
  const b64=payload.replace(/-/g,'+').replace(/_/g,'/');
  const padded=b64+'='.repeat((4-b64.length%4)%4);
  try{ return JSON.parse(atob(padded)); }catch(e){ return null; }
}

// Instagram Business Login's "Deauthorize Callback URL" (Business login settings, required before
// submitting for App Review) — Meta POSTs here when a user revokes the app's access from their
// own Instagram/Meta settings, so the stored (now-invalid) token doesn't just sit there silently
// failing on every send. `user_id` in the verified payload is the same Instagram-scoped id stored
// as `ig_id`.
async function handleInstagramDeauthorize(request, env){
  if(!env.META_IG_APP_SECRET) return json({error:'Instagram app credentials are not configured on the server.'}, 500);
  const bodyText=await request.text();
  const signedRequest=new URLSearchParams(bodyText).get('signed_request');
  const payload=await verifyMetaSignedRequest(env.META_IG_APP_SECRET, signedRequest);
  // Always 200 — an unverifiable/missing signed_request isn't something Meta can act on a retry
  // for, and there's nothing sensitive to leak either way (the response body carries no lookup
  // result), so there's no reason to give it a different status than the normal case.
  if(!payload?.user_id) return json({ok:true});
  const c=await findClientByField(env, 'ig_id', String(payload.user_id));
  if(c) await patchClientFields(env, c.Id, {ig_id:'', ig_access_token:'', ig_username:'', ig_connected_at:''});
  return json({ok:true});
}

async function handleChannelsInboxCreate(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const body=await request.json().catch(()=>({}));
  const {type}=body;
  // Matches Chatwoot's own generic inbox API exactly (app/controllers/api/v1/accounts/inboxes_controller.rb
  // allowed_channel_types) minus 'whatsapp', which has its own OAuth-driven route above.
  if(!['web_widget','email','api','sms','telegram','line'].includes(type)) return json({error:'Unsupported channel type.'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_account_id||!c?.chatwoot_token||!c?.chatwoot_base) return json({error:'Connect a Chatwoot account first.'}, 400);

  const planLimits=getPlanLimits(c.plan_tier);
  if(planLimits){
    const currentChannels=await countClientChannels(env, c);
    if(currentChannels>=planLimits.max_channels){
      return json({error:`Your ${planLimits.label} plan includes ${planLimits.max_channels} channel${planLimits.max_channels===1?'':'s'}. Upgrade your plan to add another.`}, 402);
    }
  }

  let channel, name;
  if(type==='web_widget'){
    const {website_url, welcome_title, welcome_tagline}=body;
    if(!website_url) return json({error:'website_url is required'}, 400);
    name=`Website - ${website_url}`;
    channel={type:'web_widget', website_url, welcome_title:welcome_title||'', welcome_tagline:welcome_tagline||''};
  }else if(type==='email'){
    const {email}=body;
    if(!email) return json({error:'email is required'}, 400);
    name=`Email - ${email}`;
    channel={type:'email', email};
  }else if(type==='sms'){
    const {phone_number, account_sid, auth_token}=body;
    if(!phone_number||!account_sid||!auth_token) return json({error:'phone_number, account_sid and auth_token are required'}, 400);
    name=`SMS - ${phone_number}`;
    channel={type:'sms', phone_number, provider:'twilio', provider_config:{account_sid, auth_token}};
  }else if(type==='telegram'){
    const {bot_token}=body;
    if(!bot_token) return json({error:'bot_token is required'}, 400);
    name='Telegram';
    channel={type:'telegram', bot_token};
  }else if(type==='line'){
    const {line_channel_id, line_channel_secret, line_channel_token}=body;
    if(!line_channel_id||!line_channel_secret||!line_channel_token) return json({error:'line_channel_id, line_channel_secret and line_channel_token are required'}, 400);
    name='LINE';
    channel={type:'line', line_channel_id, line_channel_secret, line_channel_token};
  }else{
    name=body.name||'API Channel';
    channel={type:'api', webhook_url:body.webhook_url||''};
  }

  const inboxR=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes`, {
    method:'POST', headers:{api_access_token:c.chatwoot_token, 'Content-Type':'application/json'},
    body:JSON.stringify({name, channel})
  });
  const inbox=await inboxR.json().catch(()=>({}));
  if(!inboxR.ok||!inbox?.id) return json({error:'Chatwoot inbox creation failed: '+(inbox?.message||('HTTP '+inboxR.status))}, 502);
  return json({ok:true, inbox_id:inbox.id, name:inbox.name||name, chatwoot_settings_url:`${c.chatwoot_base}/app/accounts/${c.chatwoot_account_id}/settings/inboxes/${inbox.id}`});
}

// Live status, read straight from Chatwoot — not just the local CLIENTS columns — so the
// Channels page always reflects what's actually connected and never offers to re-create
// something that already exists there.
async function handleChannelsStatus(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  const hasAccount=!!(c.chatwoot_account_id && c.chatwoot_token);
  if(!hasAccount) return json({ok:true, account:null, inboxes:[], has_whatsapp:false});

  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes`, {headers:{api_access_token:c.chatwoot_token}});
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:'Failed to load inboxes from Chatwoot: HTTP '+r.status}, 502);
  let credentialState=c;
  const rawInboxes=data?.payload||data?.data?.payload||[];
  const whatsapp=rawInboxes.filter(ib=>ib.channel_type==='Channel::Whatsapp');
  // Automatic, best-effort detection for every connected number. A Chatwoot version that hides
  // provider_config simply leaves that channel unconfigured and the per-channel button explains
  // how to retry; failures never break the Channels page.
  if(whatsapp.length){
    const detected=await Promise.all(whatsapp.map(async ib=>{
      try{
        const ir=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/inboxes/${ib.id}`,{headers:{api_access_token:c.chatwoot_token}});
        if(!ir.ok) return null;
        const credential=metaCredentialFromInbox(await ir.json().catch(()=>({})),ib.id);
        return credential.wa_token?credential:null;
      }catch(e){ return null; }
    }));
    const found=detected.filter(Boolean);
    if(found.length){
      let merged=parseMetaChannelCredentials(c);
      for(const credential of found) merged=mergeMetaChannelCredential({[META_CHANNEL_CREDENTIALS_FIELD]:JSON.stringify(merged)},credential);
      const encoded=JSON.stringify(merged);
      if(encoded!==JSON.stringify(parseMetaChannelCredentials(c))){
        try{
          await ensureClientColumns(env,[META_CHANNEL_CREDENTIALS_FIELD]);
          await patchClientFields(env,payload.cid,{[META_CHANNEL_CREDENTIALS_FIELD]:encoded});
          credentialState={...c,[META_CHANNEL_CREDENTIALS_FIELD]:encoded};
        }catch(e){ /* status remains usable; never log credential material */ }
      }
    }
  }
  const summaries=Object.fromEntries(metaCredentialSummary(credentialState).map(x=>[String(x.inbox_id),x]));
  const inboxes=rawInboxes.map(ib=>({id:ib.id,name:ib.name,channel_type:ib.channel_type,...(ib.channel_type==='Channel::Whatsapp'?{phone_number:summaries[String(ib.id)]?.display_phone||ib.phone_number||'',meta_credentials:summaries[String(ib.id)]||{configured:false,has_phone_id:false,has_waba_id:false,display_phone:''}}:{})}));
  const has_whatsapp=inboxes.some(ib=>ib.channel_type==='Channel::Whatsapp');
  return json({ok:true, account:{chatwoot_base:c.chatwoot_base, chatwoot_account_id:c.chatwoot_account_id}, inboxes, has_whatsapp});
}

async function handleChannelsWhatsappProfileGet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c?.wa_phone_id||!c?.wa_token) return json({error:'WhatsApp Business API is not connected for this account — connect it from Settings → Channels.'}, 400);
  const r=await fetch(`https://graph.facebook.com/v18.0/${c.wa_phone_id}/whatsapp_business_profile?fields=profile_picture_url`, {headers:{Authorization:`Bearer ${c.wa_token}`}});
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:'Failed to load WhatsApp business profile: '+(data?.error?.message||('HTTP '+r.status))}, 502);
  const profile=(data?.data||[])[0]||{};
  return json({ok:true, profile_picture_url:profile.profile_picture_url||null});
}

const WA_PROFILE_PIC_MAX_BYTES=5*1024*1024;

// Setting a WhatsApp Business Profile photo is a separate flow from sending message media —
// the /{phone_number_id}/media endpoint used elsewhere in this file issues handles that are only
// valid for outgoing messages. A profile photo needs a handle from Meta's Resumable Upload API
// instead: open an upload session against the app itself (step 1), push the bytes into that
// session (step 2, returns a reusable file handle "h"), then set that handle on the business
// profile (step 3, this last call is scoped to the client's own phone number/token like every
// other wa_token call in this file).
async function handleChannelsWhatsappProfilePicture(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.META_APP_ID||!env.META_APP_SECRET) return json({error:'Meta app credentials are not configured on the server.'}, 500);
  const c=await getClientById(env, payload.cid);
  if(!c?.wa_phone_id||!c?.wa_token) return json({error:'WhatsApp Business API is not connected for this account — connect it from Settings → Channels.'}, 400);

  const form=await request.formData().catch(()=>null);
  if(!form) return json({error:'multipart form data required'}, 400);
  const file=form.get('file');
  if(!file) return json({error:'file required'}, 400);
  const mime=(file.type||'').split(';')[0];
  if(!['image/jpeg','image/png'].includes(mime)) return json({error:'Profile photo must be a JPG or PNG image.'}, 400);
  if(file.size>WA_PROFILE_PIC_MAX_BYTES) return json({error:'Image is too large — max 5 MB.'}, 400);

  const appToken=`${env.META_APP_ID}|${env.META_APP_SECRET}`;
  const bytes=await file.arrayBuffer();

  const sessionR=await fetch(`https://graph.facebook.com/v18.0/${env.META_APP_ID}/uploads?file_length=${bytes.byteLength}&file_type=${encodeURIComponent(mime)}&access_token=${encodeURIComponent(appToken)}`, {method:'POST'});
  const sessionData=await sessionR.json().catch(()=>({}));
  if(!sessionR.ok||!sessionData?.id) return json({error:'Meta upload session failed: '+(sessionData?.error?.message||('HTTP '+sessionR.status))}, 502);

  const uploadR=await fetch(`https://graph.facebook.com/v18.0/${sessionData.id}`, {
    method:'POST',
    headers:{Authorization:`OAuth ${appToken}`, file_offset:'0', 'Content-Type':'application/octet-stream'},
    body:bytes
  });
  const uploadData=await uploadR.json().catch(()=>({}));
  if(!uploadR.ok||!uploadData?.h) return json({error:'Meta file upload failed: '+(uploadData?.error?.message||('HTTP '+uploadR.status))}, 502);

  const profileR=await fetch(`https://graph.facebook.com/v18.0/${c.wa_phone_id}/whatsapp_business_profile`, {
    method:'POST',
    headers:{Authorization:`Bearer ${c.wa_token}`, 'Content-Type':'application/json'},
    body:JSON.stringify({messaging_product:'whatsapp', profile_picture_handle:uploadData.h})
  });
  const profileData=await profileR.json().catch(()=>({}));
  if(!profileR.ok||!profileData?.success) return json({error:'Setting WhatsApp profile photo failed: '+(profileData?.error?.message||('HTTP '+profileR.status))}, 502);

  return json({ok:true});
}

// Shopify (and any other Chatwoot-native OAuth integration) is configured at the Chatwoot
// instance level (SHOPIFY_CLIENT_ID/SECRET) and connected per-account via Chatwoot's own
// Settings -> Integrations page — that OAuth hop has to run on Chatwoot's own domain/callback,
// it can't be done from this Worker. This route just gets the caller into Chatwoot already
// logged in (via the Platform API's one-time SSO link) so they land on that page with zero
// credential friction, instead of hitting a login wall for a password they were never shown.
//
// Also used by the "Log in to Chatwoot" link in the Chats tab — an optional ?email= (the
// caller's own verified Authentik email, from dashboard.html's `myEmail`) picks that specific
// person's own Chatwoot agent (team_chatwoot_users, populated by createChatwootAgent above) so
// each teammate lands in Chatwoot as themselves, not borrowing the account owner's identity.
// Falls back to the owner's chatwoot_user_id when no email is given or no per-user agent exists
// for it (e.g. they were added via "Add Existing Authentik User", which never provisions one).
async function handleChannelsChatwootSso(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  // Real connection state (same check renderChannelsStatus/hasAccount uses elsewhere) — distinct
  // from chatwoot_user_id below, which only exists for accounts this Worker itself provisioned
  // via handleChannelsCreateAccount's Platform API call. A client connected the older way
  // (Settings → Channels' manual base/account/inbox/token paste — still a fully working
  // connection, chats/sends work fine off chatwoot_token alone) has no chatwoot_user_id at all,
  // so it must not be treated as "not connected" just because SSO isn't available for it.
  if(!c?.chatwoot_account_id||!c?.chatwoot_base) return json({error:'Connect a Chatwoot account first.'}, 400);

  const requestedEmail=(new URL(request.url).searchParams.get('email')||'').trim().toLowerCase();
  let chatwootUserId=c?.chatwoot_user_id;
  if(requestedEmail && requestedEmail!==String(c?.authentik_email||'').toLowerCase()){
    let teamUsers={}; try{ teamUsers=JSON.parse(c?.team_chatwoot_users||'{}'); }catch(e){}
    const key=Object.keys(teamUsers).find(k=>k.toLowerCase()===requestedEmail);
    if(key) chatwootUserId=teamUsers[key];
  }
  // No Platform-API user on file for this identity — most likely a manually-connected account,
  // or a teammate added via "Add Existing Authentik User" (which never provisions a Chatwoot
  // agent). Can't mint a one-time SSO link without a Platform-API user id, so fall back to a
  // direct (not-pre-authenticated) link — still gets them to the right place, just requires
  // their own Chatwoot login, instead of a misleading "not connected" error.
  if(!chatwootUserId) return json({ok:true, sso:false, url:`${c.chatwoot_base}/app/accounts/${c.chatwoot_account_id}/dashboard`});

  const r=await chatwootPlatformFetch(env, `/platform/api/v1/users/${chatwootUserId}/login`);
  const data=await r.json().catch(()=>({}));
  if(!r.ok||!data?.url) return json({error:'Failed to generate a Chatwoot login link: '+(data?.message||('HTTP '+r.status))}, 502);
  return json({ok:true, sso:true, url:data.url});
}

async function ensureInboxAssignmentsTable(env){
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS channel_inbox_assignments (client_id INTEGER NOT NULL,inbox_id INTEGER NOT NULL,assigned_email TEXT NOT NULL DEFAULT '',chatwoot_user_id INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY (client_id,inbox_id))`).run().catch(()=>{});
}

// GET /channels/agents — list Chatwoot agents for this account (for the assignment picker)
async function handleChannelsAgents(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_account_id||!c?.chatwoot_token) return json({error:'No Chatwoot account connected.'}, 400);
  const r=await fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/agents`, {headers:{api_access_token:c.chatwoot_token}});
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:'Failed to load agents: HTTP '+r.status}, 502);
  const agents=(Array.isArray(data)?data:(data?.payload||[])).map(a=>({id:a.id, name:a.name, email:a.email, role:a.role||'agent'}));
  return json({ok:true, agents});
}

// GET /channels/inbox-assignments — list all inbox→agent assignments for this client
async function handleChannelsInboxAssignmentsGet(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  await ensureInboxAssignmentsTable(env);
  const rows=await env.DB.prepare(`SELECT inbox_id,assigned_email,chatwoot_user_id FROM channel_inbox_assignments WHERE client_id=?`).bind(payload.cid).all();
  return json({ok:true, assignments:rows.results||[]});
}

// PUT /channels/inbox-assignment — set or clear exclusive agent for a specific inbox
async function handleChannelsInboxAssignmentPut(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c?.chatwoot_account_id||!c?.chatwoot_token) return json({error:'No Chatwoot account connected.'}, 400);
  const body=await request.json().catch(()=>({}));
  const inboxId=Number(body.inbox_id||0);
  if(!inboxId) return json({error:'inbox_id is required'}, 400);
  const clear=body.clear===true||body.chatwoot_user_id===null;
  await ensureInboxAssignmentsTable(env);
  const now=new Date().toISOString();
  if(clear){
    await env.DB.prepare(`DELETE FROM channel_inbox_assignments WHERE client_id=? AND inbox_id=?`).bind(payload.cid, inboxId).run();
  } else {
    const agentId=Number(body.chatwoot_user_id||0);
    const email=String(body.assigned_email||'').trim().toLowerCase();
    if(!email) return json({error:'assigned_email is required'}, 400);
    await env.DB.prepare(`INSERT INTO channel_inbox_assignments (client_id,inbox_id,assigned_email,chatwoot_user_id,created_at,updated_at) VALUES (?,?,?,?,?,?) ON CONFLICT(client_id,inbox_id) DO UPDATE SET assigned_email=excluded.assigned_email,chatwoot_user_id=excluded.chatwoot_user_id,updated_at=excluded.updated_at`).bind(payload.cid,inboxId,email,agentId,now,now).run();
    // Best-effort: auto-assign open conversations in Chatwoot (only when we have a Chatwoot agent id)
    if(agentId) fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations?inbox_id=${inboxId}&status=open&page=1`, {headers:{api_access_token:c.chatwoot_token}})
      .then(r=>r.json()).then(d=>{const convs=(d?.data?.payload||[]);for(const conv of convs){fetch(`${c.chatwoot_base}/api/v1/accounts/${c.chatwoot_account_id}/conversations/${conv.id}/assignments`,{method:'POST',headers:{api_access_token:c.chatwoot_token,'Content-Type':'application/json'},body:JSON.stringify({assignee_id:agentId})}).catch(()=>{});}}).catch(()=>{});
  }
  return json({ok:true, inbox_id:inboxId, cleared:clear});
}

/* ── Shopify module (Integrations tab connect + order/fulfillment/checkout webhooks) ────────
   A one-click OAuth connect that lets this Worker read a client's Shopify store directly —
   order/fulfillment webhooks trigger WhatsApp notifications straight from here, and checkout
   webhooks feed an abandoned-cart nudge, all without n8n in the loop. Contrast with
   handleChannelsChatwootSso above: that's Chatwoot's own Shopify sidebar integration (order
   context inside a conversation); this is a separate connection whose token/data live on the
   client row here, used for WhatsApp notifications (and, later, WhatsApp Catalog sync).
   Requires SHOPIFY_API_KEY / SHOPIFY_API_SECRET (a Shopify Partners app's credentials) and a
   `shopify_checkouts` NocoDB table (id below) — see SETUP.md "Shopify module". ── */
// Keep in sync with the "Webhooks API version" set on the app in Shopify Partners — Shopify only
// supports a given version for ~9-12 months after release, so this needs bumping periodically
// (quarterly releases: -01, -04, -07, -10).
const SHOPIFY_API_VERSION='2026-07';
const SHOPIFY_SCOPES='read_orders,read_fulfillments,read_checkouts';
// Auto-provisioned on first use (see getShopifyCheckoutsTableId below) instead of a hand-pasted
// table id — used to require creating this table in NocoDB by hand and pasting its id here (same
// pattern as EMAIL_CAMPAIGNS_TABLE/EMAIL_SENDS_TABLE above); now the Worker creates it itself the
// first time it's needed, memoizing the id for the life of the isolate.
let _shopifyCheckoutsTableId=null;
async function getShopifyCheckoutsTableId(env){
  if(_shopifyCheckoutsTableId) return _shopifyCheckoutsTableId;
  const {info}=await ncTableMeta(env, CLIENTS_TABLE);
  const baseId=info.base_id;
  const tablesR=await ncFetch(env, `api/v2/meta/bases/${baseId}/tables`);
  const tables=await tablesR.json().catch(()=>({list:[]}));
  let table=(tables.list||[]).find(t=>t.title==='shopify_checkouts');
  if(!table){
    const createR=await ncFetch(env, `api/v2/meta/bases/${baseId}/tables`, {method:'POST', body:{
      title:'shopify_checkouts',
      columns:[
        {column_name:'client_id', title:'client_id', uidt:'SingleLineText'},
        {column_name:'checkout_token', title:'checkout_token', uidt:'SingleLineText'},
        {column_name:'phone', title:'phone', uidt:'SingleLineText'},
        {column_name:'customer_name', title:'customer_name', uidt:'SingleLineText'},
        {column_name:'cart_summary', title:'cart_summary', uidt:'LongText'},
        {column_name:'total', title:'total', uidt:'SingleLineText'},
        {column_name:'currency', title:'currency', uidt:'SingleLineText'},
        {column_name:'recovery_url', title:'recovery_url', uidt:'SingleLineText'},
        {column_name:'created_at', title:'created_at', uidt:'SingleLineText'},
        {column_name:'nudge_sent', title:'nudge_sent', uidt:'SingleLineText'},
        {column_name:'completed', title:'completed', uidt:'SingleLineText'},
      ]
    }});
    table=await createR.json().catch(()=>null);
    if(!table?.id) throw new Error('Failed to auto-create the shopify_checkouts table in NocoDB');
  }
  _shopifyCheckoutsTableId=table.id;
  return _shopifyCheckoutsTableId;
}
// Sent via WhatsApp when each event fires — 'abandoned' is swept in by cron, the rest by webhook.
const SHOPIFY_EVENT_KINDS=['received','paid','shipped','delivered','abandoned'];

function isValidShopDomain(shop){ return /^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(String(shop||'')); }

// Same HMAC scheme as signAdminSession/hmacSignB64 above, reused so any OAuth `state` param can
// carry the client id through a redirect round-trip with no server-side session store — the
// provider hands `state` back verbatim on the callback. Generic across every OAuth connection
// this Worker does (Shopify below, Google Search Console further down) — not provider-specific
// despite living next to the Shopify module first. 10-minute expiry: this only needs to survive
// one redirect hop, not a whole session.
// returnTo is optional and only used by handleGcalOauthStart (see its own comment) — every other
// caller passes just (env, clientId) and gets identical behavior to before this param existed.
async function signOauthState(env, clientId, returnTo){
  const payload={cid:String(clientId), exp:Math.floor(Date.now()/1000)+600, n:crypto.randomUUID(), ...(returnTo?{rt:returnTo}:{})};
  const body=btoa(JSON.stringify(payload));
  return `${body}.${await hmacSignB64(env, body)}`;
}
async function verifyOauthState(env, token){
  if(!token) return null;
  const [body, sig]=String(token).split('.');
  if(!body||!sig) return null;
  if(await hmacSignB64(env, body)!==sig) return null;
  let payload; try{ payload=JSON.parse(atob(body)); }catch(e){ return null; }
  if(!payload?.cid||!payload?.exp||payload.exp<Math.floor(Date.now()/1000)) return null;
  return payload;
}

// Shopify's OAuth callback signs every query param (except hmac/signature) with the app's
// client secret — sorted key=value pairs joined with '&', hex HMAC-SHA256. Same idea as
// verifyStripeSignature above, just over query params instead of a raw body.
async function verifyShopifyOauthHmac(env, searchParams){
  const hmac=searchParams.get('hmac');
  if(!hmac) return false;
  const pairs=[...searchParams.entries()].filter(([k])=>k!=='hmac'&&k!=='signature').sort(([a],[b])=>a<b?-1:1);
  const message=pairs.map(([k,v])=>`${k}=${v}`).join('&');
  const key=await crypto.subtle.importKey('raw', new TextEncoder().encode(env.SHOPIFY_API_SECRET), {name:'HMAC', hash:'SHA-256'}, false, ['sign']);
  const sig=await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(message));
  const expected=hex(sig);
  if(expected.length!==hmac.length) return false;
  let diff=0; for(let i=0;i<expected.length;i++) diff|=expected.charCodeAt(i)^hmac.charCodeAt(i);
  return diff===0;
}

// Shopify signs webhook bodies with a base64 HMAC-SHA256 (X-Shopify-Hmac-Sha256) over the raw,
// unparsed request body — must be verified before the body is touched as JSON.
async function verifyShopifyWebhookHmac(env, rawBody, hmacHeader){
  if(!hmacHeader) return false;
  const key=await crypto.subtle.importKey('raw', new TextEncoder().encode(env.SHOPIFY_API_SECRET), {name:'HMAC', hash:'SHA-256'}, false, ['sign']);
  const sig=await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(rawBody));
  const expected=btoa(String.fromCharCode(...new Uint8Array(sig)));
  if(expected.length!==hmacHeader.length) return false;
  let diff=0; for(let i=0;i<expected.length;i++) diff|=expected.charCodeAt(i)^hmacHeader.charCodeAt(i);
  return diff===0;
}

async function shopifyFetch(env, shop, token, path, opts={}){
  return fetch(`https://${shop}/admin/api/${SHOPIFY_API_VERSION}${path}`, {
    ...opts,
    headers:{'X-Shopify-Access-Token':token, 'Content-Type':'application/json', ...(opts.headers||{})}
  });
}

async function handleShopifyOauthStart(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.SHOPIFY_API_KEY||!env.SHOPIFY_API_SECRET) return json({error:'Shopify app credentials are not configured on the server.'}, 500);
  const {shop}=await request.json().catch(()=>({}));
  if(!isValidShopDomain(shop)) return json({error:'Enter your store as yourstore.myshopify.com'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  if(c.shopify_shop_domain && c.shopify_access_token) return json({error:'A Shopify store is already connected for this client. Disconnect it first to switch stores.'}, 400);

  const state=await signOauthState(env, payload.cid);
  const redirectUri=`${env.WORKER_BASE_URL}/shopify/oauth/callback`;
  const url=`https://${shop}/admin/oauth/authorize?client_id=${env.SHOPIFY_API_KEY}&scope=${encodeURIComponent(SHOPIFY_SCOPES)}&redirect_uri=${encodeURIComponent(redirectUri)}&state=${encodeURIComponent(state)}`;
  return json({ok:true, url});
}

// Browser redirect target, not an XHR call — Shopify itself lands the merchant here after they
// approve the install, so failures redirect back into the dashboard with a query param instead
// of returning JSON (there's no frontend JS listening on this response).
async function handleShopifyOauthCallback(request, env){
  const url=new URL(request.url);
  const appBase=env.APP_BASE_URL||'https://app.leadvyne.com/dashboard.html';
  const fail=(msg)=>Response.redirect(`${appBase}?shopify=error&msg=${encodeURIComponent(msg)}`, 302);
  if(!env.SHOPIFY_API_KEY||!env.SHOPIFY_API_SECRET) return fail('Shopify app credentials are not configured on the server.');

  if(!await verifyShopifyOauthHmac(env, url.searchParams)) return fail('Shopify signature verification failed');
  const shop=url.searchParams.get('shop');
  const code=url.searchParams.get('code');
  const state=url.searchParams.get('state');
  if(!isValidShopDomain(shop)||!code) return fail('Invalid callback from Shopify');
  const statePayload=await verifyOauthState(env, state);
  if(!statePayload) return fail('This connection link expired — try connecting again from Integrations');

  const collision=await findOtherClientByField(env, 'shopify_shop_domain', shop, statePayload.cid);
  if(collision) return fail('This Shopify store is already connected to a different client');

  const tokenR=await fetch(`https://${shop}/admin/oauth/access_token`, {
    method:'POST', headers:{'Content-Type':'application/json'},
    body:JSON.stringify({client_id:env.SHOPIFY_API_KEY, client_secret:env.SHOPIFY_API_SECRET, code})
  });
  const tokenData=await tokenR.json().catch(()=>({}));
  if(!tokenR.ok||!tokenData.access_token) return fail('Token exchange failed: '+(tokenData?.error||'HTTP '+tokenR.status));
  const access_token=tokenData.access_token;

  // Best-effort — registers the webhooks this module depends on. A client re-connecting after a
  // revoke can just disconnect and connect again to re-register them.
  const topics=['orders/create','orders/paid','orders/cancelled','fulfillments/create','fulfillments/update','checkouts/create','checkouts/update','app/uninstalled'];
  const webhookUri=`${env.WORKER_BASE_URL}/shopify/webhook`;
  await Promise.all(topics.map(topic=>
    shopifyFetch(env, shop, access_token, '/webhooks.json', {method:'POST', body:JSON.stringify({webhook:{topic, address:webhookUri, format:'json'}})}).catch(()=>{})
  ));

  await patchClientFields(env, statePayload.cid, {shopify_shop_domain:shop, shopify_access_token:access_token, shopify_connected_at:new Date().toISOString()});
  return Response.redirect(`${appBase}?client=${statePayload.cid}&shopify=connected`, 302);
}

async function handleShopifyDisconnect(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  await patchClientFields(env, payload.cid, {shopify_shop_domain:'', shopify_access_token:'', shopify_connected_at:''});
  return json({ok:true});
}

/* ── Google Search Console module (Reports page's "🔍 SEO" tab) ────────────────────────────
   A one-click OAuth connect (same signOauthState/verifyOauthState + browser-redirect-callback
   shape as the Shopify module above), storing only a refresh_token — Google access tokens expire
   in ~1h, so every read exchanges the refresh_token for a fresh one rather than caching (this
   Worker is stateless per-request anyway, same "no caching" tradeoff as every other per-call
   external token exchange in this file). Requires GOOGLE_CLIENT_ID/GOOGLE_CLIENT_SECRET (a Google
   Cloud OAuth 2.0 Client — Web application type, with this Worker's own /gsc/oauth/callback URL
   as an authorized redirect URI, and the Search Console API enabled on that project) — see
   SETUP.md "Reports page". ── */
const GSC_SCOPE='https://www.googleapis.com/auth/webmasters.readonly';

async function handleGscOauthStart(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.GOOGLE_CLIENT_ID||!env.GOOGLE_CLIENT_SECRET) return json({error:'Google Search Console credentials are not configured on the server.'}, 500);
  const state=await signOauthState(env, payload.cid);
  const redirectUri=`${env.WORKER_BASE_URL}/gsc/oauth/callback`;
  // access_type=offline + prompt=consent — Google only issues a refresh_token on a consent
  // screen, never on a silent re-approval; without prompt=consent a client reconnecting after a
  // token was lost (e.g. this row got cleared) could silently get no refresh_token back at all.
  const url=`https://accounts.google.com/o/oauth2/v2/auth?client_id=${encodeURIComponent(env.GOOGLE_CLIENT_ID)}&redirect_uri=${encodeURIComponent(redirectUri)}&response_type=code&scope=${encodeURIComponent(GSC_SCOPE)}&access_type=offline&prompt=consent&state=${encodeURIComponent(state)}`;
  return json({ok:true, url});
}

// Browser redirect target, not an XHR call — Google lands the user here after they approve
// access, so failures redirect back into the dashboard with a query param instead of returning
// JSON (there's no frontend JS listening on this response) — same shape as
// handleShopifyOauthCallback above.
async function handleGscOauthCallback(request, env){
  const url=new URL(request.url);
  const appBase=env.APP_BASE_URL||'https://app.leadvyne.com/dashboard.html';
  const fail=(msg)=>Response.redirect(`${appBase}?gsc=error&msg=${encodeURIComponent(msg)}`, 302);
  if(!env.GOOGLE_CLIENT_ID||!env.GOOGLE_CLIENT_SECRET) return fail('Google Search Console credentials are not configured on the server.');
  const err=url.searchParams.get('error');
  if(err) return fail(err==='access_denied'?'Access was denied':err);
  const code=url.searchParams.get('code');
  const state=url.searchParams.get('state');
  if(!code) return fail('Invalid callback from Google');
  const statePayload=await verifyOauthState(env, state);
  if(!statePayload) return fail('This connection link expired — try connecting again from Reports');

  const redirectUri=`${env.WORKER_BASE_URL}/gsc/oauth/callback`;
  const tokenR=await fetch('https://oauth2.googleapis.com/token', {
    method:'POST', headers:{'Content-Type':'application/x-www-form-urlencoded'},
    body:new URLSearchParams({code, client_id:env.GOOGLE_CLIENT_ID, client_secret:env.GOOGLE_CLIENT_SECRET, redirect_uri:redirectUri, grant_type:'authorization_code'})
  });
  const tokenData=await tokenR.json().catch(()=>({}));
  if(!tokenR.ok||!tokenData.refresh_token) return fail(tokenData?.error_description||'Google did not return a refresh token — remove Leadvyne from your Google Account\'s third-party access first, then reconnect.');

  await patchClientFields(env, statePayload.cid, {gsc_refresh_token:tokenData.refresh_token, gsc_connected_at:new Date().toISOString()});
  return Response.redirect(`${appBase}?client=${statePayload.cid}&gsc=connected`, 302);
}

async function gscGetAccessToken(env, c){
  if(!c.gsc_refresh_token) return null;
  const r=await fetch('https://oauth2.googleapis.com/token', {
    method:'POST', headers:{'Content-Type':'application/x-www-form-urlencoded'},
    body:new URLSearchParams({refresh_token:c.gsc_refresh_token, client_id:env.GOOGLE_CLIENT_ID, client_secret:env.GOOGLE_CLIENT_SECRET, grant_type:'refresh_token'})
  });
  const data=await r.json().catch(()=>({}));
  return r.ok?data.access_token:null;
}

// Lists Search Console properties this Google account has verified access to, so the frontend can
// offer a picker rather than guessing which one is this client's actual site — a connected Google
// account can have several (main domain, subdomains, old properties never removed).
async function handleGscSitesList(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c?.gsc_refresh_token) return json({error:'Connect Google Search Console first.'}, 400);
  const token=await gscGetAccessToken(env, c);
  if(!token) return json({error:'Failed to refresh Google access token — try reconnecting.'}, 502);
  const r=await fetch('https://www.googleapis.com/webmasters/v3/sites', {headers:{Authorization:`Bearer ${token}`}});
  const data=await r.json().catch(()=>({}));
  if(!r.ok) return json({error:data?.error?.message||'Google rejected the request'}, 502);
  return json({sites:(data.siteEntry||[]).map(s=>({site_url:s.siteUrl, permission_level:s.permissionLevel})), current:c.gsc_site_url||''});
}

async function handleGscSiteSave(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {site_url}=await request.json().catch(()=>({}));
  if(!site_url) return json({error:'site_url required'}, 400);
  await patchClientFields(env, payload.cid, {gsc_site_url:site_url});
  return json({ok:true});
}

async function handleGscDisconnect(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  await patchClientFields(env, payload.cid, {gsc_refresh_token:'', gsc_site_url:'', gsc_connected_at:''});
  return json({ok:true});
}

// SEO report — Reports page's "🔍 SEO" tab. Search Console's own data has a ~2-3 day reporting
// lag (Google's documented processing latency, not something this Worker can work around) — "last
// 28 days" here means the 28 days ending 3 days ago, not today; requesting a fresher end date just
// gets back rows of zeros for days Google hasn't finished processing yet.
async function handleReportsSeo(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c?.gsc_refresh_token||!c?.gsc_site_url) return json({connected:false});
  const token=await gscGetAccessToken(env, c);
  if(!token) return json({connected:false, error:'Failed to refresh Google access token — try reconnecting.'});

  const end=new Date(); end.setDate(end.getDate()-3);
  const start=new Date(end); start.setDate(start.getDate()-27);
  const fmt=d=>d.toISOString().slice(0,10);
  const siteUrl=encodeURIComponent(c.gsc_site_url);

  const query=async(dimensions, rowLimit)=>{
    const r=await fetch(`https://www.googleapis.com/webmasters/v3/sites/${siteUrl}/searchAnalytics/query`, {
      method:'POST', headers:{Authorization:`Bearer ${token}`, 'Content-Type':'application/json'},
      body:JSON.stringify({startDate:fmt(start), endDate:fmt(end), dimensions, rowLimit:rowLimit||1000})
    });
    const data=await r.json().catch(()=>({}));
    return r.ok?(data.rows||[]):[];
  };

  const [dailyRows, queryRows, pageRows]=await Promise.all([query(['date']), query(['query'],10), query(['page'],10)]);

  const daily=dailyRows.map(row=>({
    date:row.keys[0], clicks:row.clicks||0, impressions:row.impressions||0,
    ctr:Math.round((row.ctr||0)*1000)/10, position:Math.round((row.position||0)*10)/10,
  }));
  const totalClicks=daily.reduce((s,d)=>s+d.clicks,0);
  const totalImpressions=daily.reduce((s,d)=>s+d.impressions,0);
  const avgPosition=totalImpressions?Math.round((dailyRows.reduce((s,r)=>s+(r.position||0)*(r.impressions||0),0)/totalImpressions)*10)/10:0;

  const shapeRow=(row,keyName)=>({[keyName]:row.keys[0], clicks:row.clicks||0, impressions:row.impressions||0, ctr:Math.round((row.ctr||0)*1000)/10, position:Math.round((row.position||0)*10)/10});

  return json({
    connected:true, site_url:c.gsc_site_url, range:{start:fmt(start), end:fmt(end)},
    totals:{clicks:totalClicks, impressions:totalImpressions, ctr:totalImpressions?Math.round((totalClicks/totalImpressions)*1000)/10:0, avg_position:avgPosition},
    daily,
    top_queries:queryRows.map(row=>shapeRow(row,'query')),
    top_pages:pageRows.map(row=>shapeRow(row,'page')),
  });
}

/* ── Google Calendar Sync (Task Manager — SETUP.md "Google Calendar sync") ────────────────────
   One-way push: manual Tasks (due_date/due_time) and Calendar Events (see the "CALENDAR EVENTS"
   module above) get created/updated/deleted as real events on a dedicated Google Calendar the
   moment they're created/edited/marked done/deleted in Leadvyne — so a rep sees their Leadvyne
   work on their phone's own calendar app without opening the dashboard. Same
   signOauthState/verifyOauthState + browser-redirect-callback shape as the Google Search Console
   module above, reusing the *same* GOOGLE_CLIENT_ID/GOOGLE_CLIENT_SECRET Cloud OAuth Client (just
   a different scope) — no second Google Cloud project needed.
   **Deliberately one-way for now** — an edit made directly in Google Calendar does NOT flow back
   into Leadvyne. True two-way sync needs either a push-notification channel (Google's Calendar
   watch/webhook API, which expires and must be renewed on a schedule) or periodic polling with a
   sync token, both genuinely separate pieces of infra from what shipped here; documented as a
   known next step in SETUP.md rather than half-built. */
const GCAL_SCOPE='https://www.googleapis.com/auth/calendar';
const GCAL_CALENDAR_NAME='Leadvyne Tasks & Events';

async function handleGcalOauthStart(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  if(!env.GOOGLE_CLIENT_ID||!env.GOOGLE_CLIENT_SECRET) return json({error:'Google credentials are not configured on the server.'}, 500);
  // Which page to land back on after Google redirects to the callback below — defaults to
  // dashboard.html (the original/only caller) when omitted. Restricted to a bare "<name>.html"
  // (optionally with a query string) served from this same app, never an external URL — the
  // state token is HMAC-signed so a caller can't forge one to redirect elsewhere regardless, but
  // this keeps the intent explicit. frontend/projects.html passes its own name here so connecting
  // Google Calendar from the Projects tool returns there instead of bouncing to the CRM.
  const {return_to}=await request.json().catch(()=>({}));
  const safeReturnTo=(typeof return_to==='string' && /^[a-z0-9_-]+\.html(\?[^\s]*)?$/i.test(return_to)) ? return_to : null;
  const state=await signOauthState(env, payload.cid, safeReturnTo);
  const redirectUri=`${env.WORKER_BASE_URL}/gcal/oauth/callback`;
  const url=`https://accounts.google.com/o/oauth2/v2/auth?client_id=${encodeURIComponent(env.GOOGLE_CLIENT_ID)}&redirect_uri=${encodeURIComponent(redirectUri)}&response_type=code&scope=${encodeURIComponent(GCAL_SCOPE)}&access_type=offline&prompt=consent&state=${encodeURIComponent(state)}`;
  return json({ok:true, url});
}

async function handleGcalOauthCallback(request, env){
  const url=new URL(request.url);
  // Verified as early as possible, before any failure path, so an expired/invalid state is the
  // only case that falls back to the default page — every other outcome (including Google's own
  // access_denied) still honors whichever page actually started this connection.
  const statePayload=await verifyOauthState(env, url.searchParams.get('state'));
  const appBase=statePayload?.rt ? `https://app.leadvyne.com/${statePayload.rt}` : (env.APP_BASE_URL||'https://app.leadvyne.com/dashboard.html');
  const redirectSep=appBase.includes('?')?'&':'?';
  const fail=(msg)=>Response.redirect(`${appBase}${redirectSep}gcal=error&msg=${encodeURIComponent(msg)}`, 302);
  if(!env.GOOGLE_CLIENT_ID||!env.GOOGLE_CLIENT_SECRET) return fail('Google credentials are not configured on the server.');
  const err=url.searchParams.get('error');
  if(err) return fail(err==='access_denied'?'Access was denied':err);
  const code=url.searchParams.get('code');
  if(!code) return fail('Invalid callback from Google');
  if(!statePayload) return fail('This connection link expired — try connecting again from Tasks');

  const redirectUri=`${env.WORKER_BASE_URL}/gcal/oauth/callback`;
  const tokenR=await fetch('https://oauth2.googleapis.com/token', {
    method:'POST', headers:{'Content-Type':'application/x-www-form-urlencoded'},
    body:new URLSearchParams({code, client_id:env.GOOGLE_CLIENT_ID, client_secret:env.GOOGLE_CLIENT_SECRET, redirect_uri:redirectUri, grant_type:'authorization_code'})
  });
  const tokenData=await tokenR.json().catch(()=>({}));
  if(!tokenR.ok||!tokenData.refresh_token) return fail(tokenData?.error_description||'Google did not return a refresh token — remove Leadvyne from your Google Account\'s third-party access first, then reconnect.');

  // Creates the dedicated secondary calendar right away (rather than lazily on first sync) so the
  // "Connected ✓" state is immediately meaningful — a rep can open Google Calendar and see the new
  // calendar exists even before any task/event has synced into it yet.
  const calId=await gcalCreateCalendar(tokenData.access_token);
  if(!calId) return fail('Connected to Google, but could not create the "Leadvyne Tasks & Events" calendar — try again.');

  await patchClientFields(env, statePayload.cid, {gcal_refresh_token:tokenData.refresh_token, gcal_calendar_id:calId, gcal_connected_at:new Date().toISOString()});
  return Response.redirect(`${appBase}${redirectSep}client=${statePayload.cid}&gcal=connected`, 302);
}

async function gcalCreateCalendar(accessToken){
  const r=await fetch('https://www.googleapis.com/calendar/v3/calendars', {
    method:'POST', headers:{Authorization:`Bearer ${accessToken}`, 'Content-Type':'application/json'},
    body:JSON.stringify({summary:GCAL_CALENDAR_NAME})
  });
  const data=await r.json().catch(()=>({}));
  return r.ok?data.id:null;
}

async function gcalGetAccessToken(env, c){
  if(!c.gcal_refresh_token) return null;
  const r=await fetch('https://oauth2.googleapis.com/token', {
    method:'POST', headers:{'Content-Type':'application/x-www-form-urlencoded'},
    body:new URLSearchParams({refresh_token:c.gcal_refresh_token, client_id:env.GOOGLE_CLIENT_ID, client_secret:env.GOOGLE_CLIENT_SECRET, grant_type:'refresh_token'})
  });
  const data=await r.json().catch(()=>({}));
  return r.ok?data.access_token:null;
}

async function handleGcalStatus(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  return json({connected:!!(c?.gcal_refresh_token&&c?.gcal_calendar_id)});
}

async function handleGcalDisconnect(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  // Leaves the Google-side calendar itself alone — deleting it from here would also be surprising
  // if a rep still wants to keep the events already synced there; they can delete the calendar
  // themselves in Google Calendar if they want it fully gone.
  await patchClientFields(env, payload.cid, {gcal_refresh_token:'', gcal_calendar_id:'', gcal_connected_at:''});
  return json({ok:true});
}

// Shared create/update — one function for both since a Google Calendar event id already existing
// is the only thing that distinguishes the two (PATCH vs POST). `allDay` picks Google's `date` vs
// `dateTime` event shape; a timed event gets a fixed 30-minute duration (Google requires an end
// time, and this app never tracks a task's actual duration). `recurrenceYearly` uses Google's own
// native RRULE recurrence for display — purely cosmetic on the Google side; Leadvyne's own
// Calendar Events cadence/dedupe logic (see calendarOccurrenceDate above) is entirely unaffected
// by however this renders in Google Calendar.
async function gcalUpsertEvent(env, c, {gcalEventId, title, notes, date, time, allDay, recurrenceYearly, durationMinutes}){
  const token=await gcalGetAccessToken(env, c);
  if(!token||!c.gcal_calendar_id) return null;
  const body={
    summary:title||'(untitled)', description:notes||'',
    ...(allDay
      ? {start:{date}, end:{date}}
      : {start:{dateTime:`${date}T${time||'09:00'}:00`}, end:{dateTime:gcalAddMinutes(date, time||'09:00', Math.max(5, Number(durationMinutes)||30))}}),
    ...(recurrenceYearly?{recurrence:['RRULE:FREQ=YEARLY']}:{}),
  };
  const method=gcalEventId?'PATCH':'POST';
  const url=gcalEventId
    ? `https://www.googleapis.com/calendar/v3/calendars/${c.gcal_calendar_id}/events/${gcalEventId}`
    : `https://www.googleapis.com/calendar/v3/calendars/${c.gcal_calendar_id}/events`;
  const r=await fetch(url, {method, headers:{Authorization:`Bearer ${token}`, 'Content-Type':'application/json'}, body:JSON.stringify(body)});
  const data=await r.json().catch(()=>({}));
  // A previously-synced event the rep since deleted straight from Google Calendar comes back 404/410
  // on PATCH — recover by creating a fresh one instead of leaving this task/event un-synced forever.
  if(!r.ok && gcalEventId && (r.status===404||r.status===410)){
    const r2=await fetch(`https://www.googleapis.com/calendar/v3/calendars/${c.gcal_calendar_id}/events`, {method:'POST', headers:{Authorization:`Bearer ${token}`, 'Content-Type':'application/json'}, body:JSON.stringify(body)});
    const data2=await r2.json().catch(()=>({}));
    return r2.ok?data2.id:null;
  }
  return r.ok?data.id:null;
}
function gcalAddMinutes(date, time, minutes){
  const dt=new Date(`${date}T${time}:00`);
  dt.setMinutes(dt.getMinutes()+minutes);
  return dt.toISOString().slice(0,19);
}
async function gcalDeleteEvent(env, c, gcalEventId){
  if(!gcalEventId||!c.gcal_calendar_id) return;
  const token=await gcalGetAccessToken(env, c);
  if(!token) return;
  await fetch(`https://www.googleapis.com/calendar/v3/calendars/${c.gcal_calendar_id}/events/${gcalEventId}`, {method:'DELETE', headers:{Authorization:`Bearer ${token}`}}).catch(()=>{});
}

// Manual Tasks have no server-side CRUD at all (dashboard.html writes the whole manual_tasks blob
// directly via the generic /nocodb passthrough) — so unlike Calendar Events below, this is a
// dedicated route the frontend calls right after its own save succeeds, passing just the one
// task's current shape rather than the Worker re-parsing the whole tasks blob itself.
async function handleGcalSyncTask(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const {action, task}=await request.json().catch(()=>({}));
  if(!task?.id) return json({error:'task required'}, 400);
  const c=await getClientById(env, payload.cid);
  if(!c?.gcal_refresh_token||!c?.gcal_calendar_id) return json({ok:true, skipped:'not-connected'});
  if(action==='delete' || task.status==='done' || !task.due_date){
    if(task.gcal_event_id) await gcalDeleteEvent(env, c, task.gcal_event_id);
    return json({ok:true, gcal_event_id:null});
  }
  const gcalEventId=await gcalUpsertEvent(env, c, {gcalEventId:task.gcal_event_id||null, title:task.title, notes:task.notes, date:task.due_date, time:task.due_time, allDay:!task.due_time});
  return json({ok:true, gcal_event_id:gcalEventId});
}

// Fires a WhatsApp template straight through Meta's Graph API (same shape as
// handleWaSendTemplate above) and records the attempt in shopify_notify_log regardless of
// outcome, so the Shopify card (dashboard.html, Settings → Integrations) has something to show
// even for a skipped/failed send. `kind` indexes into shopify_notify_config.config; `vars`
// supplies the values available for that event's template variable mapping.
async function sendShopifyNotification(env, c, kind, vars, logMeta){
  let stored={}; try{ stored=JSON.parse(c.shopify_notify_config||'{}'); }catch(e){}
  const cfg=stored?.config?.[kind];
  let log=[]; try{ log=JSON.parse(c.shopify_notify_log||'[]'); }catch(e){}
  const entry={ts:new Date().toISOString(), event:kind, order:logMeta.order||'', phone:logMeta.phone||''};

  if(!cfg?.name){ entry.status='skipped'; entry.detail='Not configured'; }
  else if(!c.wa_phone_id||!c.wa_token){ entry.status='skipped'; entry.detail='WhatsApp not connected'; }
  else if(!logMeta.phone){ entry.status='skipped'; entry.detail='No customer phone on this order'; }
  else{
    const params=cfg.params||[];
    const components=params.length ? [{type:'body', parameters:params.map(key=>({type:'text', text:String((key&&vars[key])||'')}))}] : [];
    const r=await fetch(`https://graph.facebook.com/v18.0/${c.wa_phone_id}/messages`, {
      method:'POST', headers:{Authorization:`Bearer ${c.wa_token}`, 'Content-Type':'application/json'},
      body:JSON.stringify({messaging_product:'whatsapp', to:logMeta.phone, type:'template', template:{name:cfg.name, language:{code:cfg.lang||'en'}, components}})
    });
    const data=await r.json().catch(()=>({}));
    entry.status=r.ok?'sent':'failed';
    entry.detail=r.ok?(data?.messages?.[0]?.id||'sent'):(data?.error?.message||'HTTP '+r.status);
  }
  log.push(entry);
  if(log.length>30) log=log.slice(-30); // ~last 30 events is plenty for the log view, not an audit trail
  await patchClientFields(env, c.Id, {shopify_notify_log:JSON.stringify(log)});
}

async function findShopifyCheckoutRow(env, clientId, token){
  if(!token) return null;
  const tableId=await getShopifyCheckoutsTableId(env);
  const r=await ncFetch(env, `api/v2/tables/${tableId}/records?where=(client_id,eq,${clientId})~and(checkout_token,eq,${encodeURIComponent(token)})&limit=1`);
  if(!r.ok) return null;
  const data=await r.json().catch(()=>({}));
  return data?.list?.[0]||null;
}

async function upsertShopifyCheckout(env, clientId, payload){
  const token=payload.token||payload.cart_token;
  if(!token) return;
  const tableId=await getShopifyCheckoutsTableId(env);
  const fields={
    client_id:clientId, checkout_token:token,
    phone:payload.phone||payload.shipping_address?.phone||payload.billing_address?.phone||'',
    customer_name:[payload.billing_address?.first_name, payload.billing_address?.last_name].filter(Boolean).join(' '),
    cart_summary:(payload.line_items||[]).map(li=>`${li.quantity}x ${li.title}`).join(', '),
    total:payload.total_price||'', currency:payload.currency||'',
    recovery_url:payload.abandoned_checkout_url||'', created_at:payload.created_at||new Date().toISOString(),
  };
  const existing=await findShopifyCheckoutRow(env, clientId, token);
  if(existing) await ncFetch(env, `api/v2/tables/${tableId}/records`, {method:'PATCH', body:{Id:existing.Id, ...fields}});
  else await ncFetch(env, `api/v2/tables/${tableId}/records`, {method:'POST', body:{...fields, nudge_sent:'No', completed:'No'}});
}

async function markShopifyCheckoutCompleted(env, clientId, token){
  if(!token) return;
  const tableId=await getShopifyCheckoutsTableId(env);
  const existing=await findShopifyCheckoutRow(env, clientId, token);
  if(existing) await ncFetch(env, `api/v2/tables/${tableId}/records`, {method:'PATCH', body:{Id:existing.Id, completed:'Yes'}});
}

async function findEcomOrderByShopifyId(env, tableId, clientId, shopifyOrderId){
  const r=await ncFetch(env, `api/v2/tables/${tableId}/records?where=(client_id,eq,${clientId})~and(shopify_order_id,eq,${shopifyOrderId})&limit=1`);
  if(!r.ok) return null;
  const data=await r.json().catch(()=>({}));
  return data?.list?.[0]||null;
}

// Mirrors upsertShopifyCheckout's find-then-patch-or-create pattern, keeping the client's own
// Ecommerce module Orders page (ecom.html — ORDER_FIELDS there is the authoritative column list
// this must match) in sync with Shopify's order lifecycle, not just the WhatsApp notifications
// sendShopifyNotification fires. Matched on `shopify_order_id` (Shopify's own numeric order id,
// stable across every webhook for that order) rather than `order_id`/name, which a merchant could
// edit in Shopify after the fact. Requires a `shopify_order_id` column on the orders table (both
// the shared default and any client's own — see SETUP.md); silently no-ops if the client has no
// orders table resolvable at all (ecomResolveTable falls back to the shared default, so in
// practice this only skips if that default table id itself is ever cleared).
async function syncShopifyOrderToEcom(env, c, order, status){
  const tableId=await ecomResolveTable(env, c.Id, 'orders');
  if(!tableId||!order?.id) return;
  const fields={
    client_id:c.Id, shopify_order_id:String(order.id), status,
    order_id:order.name||('#'+(order.order_number||order.id)),
    customer_name:[order.customer?.first_name, order.customer?.last_name].filter(Boolean).join(' '),
    customer_phone:order.phone||order.shipping_address?.phone||order.customer?.phone||'',
    order_date:(order.created_at||'').slice(0,10),
    items:(order.line_items||[]).map(li=>`${li.quantity}x ${li.title}`).join(', '),
    // Structured alongside the flattened `items` text above rather than replacing it — `items` is
    // what ecom.html's Orders table already renders. This is purely additive, for the Reports
    // page's Shopify top-products breakdown (handleShopifyAnalytics below), which needs real
    // per-line price/qty/sku that the flattened string doesn't carry. Requires a `line_items_json`
    // column (Long text) on the orders table, same "add this column" pattern as shopify_order_id —
    // see SETUP.md. Orders synced before this column existed have no line_items_json, so
    // per-product analytics only cover orders from here on; an accepted reporting-only gap.
    line_items_json:JSON.stringify((order.line_items||[]).map(li=>({title:li.title||'', quantity:Number(li.quantity)||0, price:Number(li.price)||0, sku:li.sku||''}))),
    total:order.total_price||0, currency:order.currency||'',
    delivery_address:[order.shipping_address?.address1, order.shipping_address?.city, order.shipping_address?.country].filter(Boolean).join(', '),
  };
  const existing=await findEcomOrderByShopifyId(env, tableId, c.Id, fields.shopify_order_id);
  const r=existing
    ? await ncFetch(env, `api/v2/tables/${tableId}/records`, {method:'PATCH', body:{Id:existing.Id, ...fields}})
    : await ncFetch(env, `api/v2/tables/${tableId}/records`, {method:'POST', body:fields});
  if(!r.ok){
    const data=await r.json().catch(()=>({}));
    await reportOpsError(env, 'syncShopifyOrderToEcom', new Error(data?.msg||data?.error||`HTTP ${r.status}`), {clientId:c.Id, shopifyOrderId:fields.shopify_order_id, tableId});
  }
}

// Ecommerce Analytics — Reports page's "🛍️ Ecommerce" tab (and reused by handleReportsProducts
// below for its top-products section, so that route doesn't re-scan the same orders table
// twice). Despite the function name (kept for the route/call-site history — see SETUP.md), this
// is NOT Shopify-specific: it reads the same orders table every order lands in regardless of
// source — Shopify-synced (syncShopifyOrderToEcom), the built-in storefront checkout
// (handleEcomPublicOrder/onshope.com), or manual entry — so a client using only the built-in
// storefront sees real revenue/product data here too, not an empty "connect Shopify" prompt.
// `shopify_connected` is returned purely as an informational flag for an optional "auto-sync your
// Shopify store too" nudge, never a gate on showing the report itself. Revenue trend/AOV/order
// count come from the orders table's `total` (always present, any order, any source). Top
// products prefer the structured `line_items_json` (see syncShopifyOrderToEcom above, Shopify-only
// — the built-in storefront's `handleEcomPublicOrder` doesn't populate it since it only ever
// creates one line per order) and fall back to best-effort parsing the flattened `items` text
// ("2x Product Name" lines, populated by every order source) — quantity-only in that fallback,
// since the flattened string never carried a per-line price. Cart abandonment rate is Shopify-only
// (shopify_checkouts table, sweepAbandonedShopifyCheckouts) — the built-in storefront has no
// abandoned-checkout concept of its own, so this stays 0/0 for a Shopify-less client rather than
// guessing.
async function handleShopifyAnalytics(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);
  const tableId=await ecomResolveTable(env, payload.cid, 'orders');
  if(!tableId) return json({has_orders_table:false, shopify_connected:!!c.shopify_shop_domain, months:[], order_count:0, total_revenue:0, aov:0, top_products:[], style_breakdown:{}, abandonment_rate:0});

  const months=6;
  const since=new Date(); since.setMonth(since.getMonth()-(months-1)); since.setDate(1);
  const sinceStr=since.toISOString().slice(0,10);

  // Lookup for the style_breakdown below — line items only carry a title/sku, not a product's
  // style/attributes, so this joins them back to the product record. Keyed by both sku and
  // lowercased name since the `items`-text fallback path (non-Shopify orders) has no sku at all.
  const productByKey={};
  const productsTableId=await ecomResolveTable(env, payload.cid, 'products');
  if(productsTableId){
    try{
      const ppr=await ncFetch(env, `api/v2/tables/${productsTableId}/records?where=(client_id,eq,${payload.cid})&limit=1000&fields=sku,name,style,shade,skin_type,hair_type,concern,brand,variant`);
      const ppd=await ppr.json().catch(()=>({}));
      (ppd?.list||[]).forEach(p=>{
        if(p.sku) productByKey['sku:'+String(p.sku).toLowerCase()]=p;
        if(p.name) productByKey['name:'+String(p.name).toLowerCase()]=p;
      });
    }catch(e){}
  }
  const styleBreakdown={cosmetics:{by_shade:{}, by_skin_type:{}}, haircare:{by_hair_type:{}, by_concern:{}}, general:{by_brand:{}, by_variant:{}}};
  function bumpStyleBucket(bucket, key, qty, revenue){
    if(!bucket[key]) bucket[key]={key, quantity:0, revenue:0};
    bucket[key].quantity+=qty; bucket[key].revenue+=revenue;
  }
  // Additive only — fashion_garments/unset-style products never reach any of these branches, so
  // top_products (below) stays the only breakdown for that style, exactly as before this feature.
  function addStyleBreakdown(product, qty, revenue){
    if(!product) return;
    if(product.style==='cosmetics'){
      if(product.shade) bumpStyleBucket(styleBreakdown.cosmetics.by_shade, product.shade, qty, revenue);
      if(product.skin_type) bumpStyleBucket(styleBreakdown.cosmetics.by_skin_type, product.skin_type, qty, revenue);
    }else if(product.style==='haircare'){
      if(product.hair_type) bumpStyleBucket(styleBreakdown.haircare.by_hair_type, product.hair_type, qty, revenue);
      if(product.concern) bumpStyleBucket(styleBreakdown.haircare.by_concern, product.concern, qty, revenue);
    }else if(product.style==='general'){
      if(product.brand) bumpStyleBucket(styleBreakdown.general.by_brand, product.brand, qty, revenue);
      if(product.variant) bumpStyleBucket(styleBreakdown.general.by_variant, product.variant, qty, revenue);
    }
  }

  let orders=[];
  for(let page=1; page<=10; page++){
    const r=await ncFetch(env, `api/v2/tables/${tableId}/records?where=${encodeURIComponent(`(client_id,eq,${payload.cid})~and(order_date,gte,${sinceStr})`)}&limit=200&offset=${(page-1)*200}&fields=order_date,total,currency,items,line_items_json,status`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const list=data?.list||[];
    orders=orders.concat(list);
    if(list.length<200) break;
  }

  const byMonth={}, productTotals={};
  let totalRevenue=0, orderCount=0;
  orders.forEach(o=>{
    if(String(o.status||'').toLowerCase()==='cancelled') return;
    orderCount++;
    const month=String(o.order_date||'').slice(0,7);
    const total=Number(o.total)||0;
    totalRevenue+=total;
    if(month){ if(!byMonth[month]) byMonth[month]={key:month, orders:0, revenue:0}; byMonth[month].orders++; byMonth[month].revenue+=total; }
    let lineItems=null;
    if(o.line_items_json){ try{ lineItems=JSON.parse(o.line_items_json); }catch(e){} }
    if(Array.isArray(lineItems)&&lineItems.length){
      lineItems.forEach(li=>{
        const title=li.title||'Unknown';
        if(!productTotals[title]) productTotals[title]={title, quantity:0, revenue:0};
        const qty=Number(li.quantity)||0, rev=(Number(li.price)||0)*qty;
        productTotals[title].quantity+=qty;
        productTotals[title].revenue+=rev;
        const matched=(li.sku&&productByKey['sku:'+String(li.sku).toLowerCase()])||productByKey['name:'+title.toLowerCase()];
        addStyleBreakdown(matched, qty, rev);
      });
    }else if(o.items){
      String(o.items).split(',').map(s=>s.trim()).filter(Boolean).forEach(part=>{
        const m=part.match(/^(\d+)x\s+(.+)$/i);
        if(!m) return;
        const title=m[2].trim();
        if(!productTotals[title]) productTotals[title]={title, quantity:0, revenue:0};
        const qty=parseInt(m[1])||0;
        productTotals[title].quantity+=qty;
        addStyleBreakdown(productByKey['name:'+title.toLowerCase()], qty, 0);
      });
    }
  });

  let totalCheckouts=0, completedCheckouts=0;
  try{
    let checkouts=[];
    const checkoutsTableId=await getShopifyCheckoutsTableId(env);
    for(let page=1; page<=10; page++){
      const r=await ncFetch(env, `api/v2/tables/${checkoutsTableId}/records?where=${encodeURIComponent(`(client_id,eq,${payload.cid})~and(created_at,gte,${since.toISOString()})`)}&limit=200&offset=${(page-1)*200}&fields=completed`);
      if(!r.ok) break;
      const data=await r.json().catch(()=>({}));
      const list=data?.list||[];
      checkouts=checkouts.concat(list);
      if(list.length<200) break;
    }
    totalCheckouts=checkouts.length;
    completedCheckouts=checkouts.filter(ch=>ch.completed==='Yes').length;
  }catch(e){}

  return json({
    has_orders_table:true, shopify_connected:!!c.shopify_shop_domain,
    currency:orders[0]?.currency||'',
    months:Object.values(byMonth).sort((a,b)=>a.key.localeCompare(b.key)),
    order_count:orderCount,
    total_revenue:Math.round(totalRevenue*100)/100,
    aov:orderCount?Math.round((totalRevenue/orderCount)*100)/100:0,
    top_products:Object.values(productTotals).sort((a,b)=>b.revenue-a.revenue||b.quantity-a.quantity).slice(0,10),
    style_breakdown:{
      cosmetics:{
        by_shade:Object.values(styleBreakdown.cosmetics.by_shade).sort((a,b)=>b.revenue-a.revenue||b.quantity-a.quantity).slice(0,10),
        by_skin_type:Object.values(styleBreakdown.cosmetics.by_skin_type).sort((a,b)=>b.revenue-a.revenue||b.quantity-a.quantity).slice(0,10),
      },
      haircare:{
        by_hair_type:Object.values(styleBreakdown.haircare.by_hair_type).sort((a,b)=>b.revenue-a.revenue||b.quantity-a.quantity).slice(0,10),
        by_concern:Object.values(styleBreakdown.haircare.by_concern).sort((a,b)=>b.revenue-a.revenue||b.quantity-a.quantity).slice(0,10),
      },
      general:{
        by_brand:Object.values(styleBreakdown.general.by_brand).sort((a,b)=>b.revenue-a.revenue||b.quantity-a.quantity).slice(0,10),
        by_variant:Object.values(styleBreakdown.general.by_variant).sort((a,b)=>b.revenue-a.revenue||b.quantity-a.quantity).slice(0,10),
      },
    },
    total_checkouts:totalCheckouts, completed_checkouts:completedCheckouts,
    abandonment_rate:totalCheckouts?Math.round(((totalCheckouts-completedCheckouts)/totalCheckouts)*1000)/10:0,
  });
}

// Product & Service Performance — Reports page's "🧩 Product" tab. Two independent sources,
// whichever modules a client actually has: the Appointment Booking module's own service catalog
// (bookings grouped by service_id, only `confirmed`/`completed` counted as real revenue —
// `requested`/`cancelled`/`no_show` never converted) joined against each service's currently-
// listed price, and Shopify's top-products (reuses handleShopifyAnalytics' own aggregation
// wholesale rather than re-scanning the same orders table). Revenue-per-service is
// booked-count × list price — an approximation (assumes every booking went at the listed price;
// nothing tracks a per-booking custom/discounted amount anywhere in this module), same "cheap and
// predictable, documented limitation" tradeoff used elsewhere in this file.
async function handleReportsProducts(request, env){
  const payload=await requireSession(request, env);
  if(!payload) return json({error:'Invalid or expired session'}, 401);
  const c=await getClientById(env, payload.cid);
  if(!c) return json({error:'Client not found'}, 404);

  const services=[];
  const bookingsTable=apptResolveTable(c, 'bookings');
  const servicesTable=apptResolveTable(c, 'services');
  if(bookingsTable && servicesTable){
    const svcR=await ncFetch(env, `api/v2/tables/${servicesTable}/records?where=(client_id,eq,${payload.cid})&limit=200&fields=Id,name,price,currency`);
    const svcData=await svcR.json().catch(()=>({}));
    const svcById={};
    (svcData?.list||[]).forEach(s=>{ svcById[String(s.Id)]={name:s.name, price:Number(s.price)||0, currency:s.currency||''}; });

    let bookings=[];
    for(let page=1; page<=10; page++){
      const r=await ncFetch(env, `api/v2/tables/${bookingsTable}/records?where=${encodeURIComponent(`(client_id,eq,${payload.cid})`)}&limit=200&offset=${(page-1)*200}&fields=service_id,service_name,status`);
      if(!r.ok) break;
      const data=await r.json().catch(()=>({}));
      const list=data?.list||[];
      bookings=bookings.concat(list);
      if(list.length<200) break;
    }
    const byService={};
    bookings.forEach(b=>{
      const key=b.service_id||b.service_name||'(unspecified)';
      if(!byService[key]) byService[key]={service_id:b.service_id||'', name:b.service_name||svcById[b.service_id]?.name||'Unknown', bookings:0, booked:0};
      byService[key].bookings++;
      if(b.status==='confirmed'||b.status==='completed') byService[key].booked++;
    });
    Object.values(byService).forEach(row=>{
      const svc=svcById[row.service_id];
      row.price=svc?.price||0; row.currency=svc?.currency||'';
      row.revenue=Math.round(row.booked*row.price*100)/100;
      services.push(row);
    });
    services.sort((a,b)=>b.revenue-a.revenue||b.bookings-a.bookings);
  }

  let topProducts=[], hasOrdersTable=false, styleBreakdown={};
  try{
    const ecomData=await (await handleShopifyAnalytics(request, env)).json();
    topProducts=ecomData.top_products||[];
    hasOrdersTable=!!ecomData.has_orders_table;
    styleBreakdown=ecomData.style_breakdown||{};
  }catch(e){}

  return json({services, top_products:topProducts, style_breakdown:styleBreakdown, has_orders_table:hasOrdersTable});
}

/* ── SCHEDULED REPORT BUILDER (Reports page → 🗓️ Scheduled Reports) ─────────────────────────────
   A client picks which report sections they want (REPORT_SECTIONS below), a frequency (daily or
   weekly), a template/accent color, and who gets it by email — saved as a row in D1's
   scheduled_reports table (migrations/0042_scheduled_reports.sql). Multiple reports per client are
   just multiple rows. runScheduledReportsForAllClients (piggybacked on the existing daily
   '0 2 * * *' cron tick, same reasoning as every other daily-granularity sweep in this file — see
   that tick's own comment) sends whichever reports are due.

   Every section's data comes from either a genuinely new, lightweight direct-Lead-table query
   (Overview/Sales/Team/SaaS — these never had a server-side endpoint at all before this, only
   client-side computation in dashboard.html) or by calling this file's EXISTING report handlers
   directly as plain functions (WhatsApp/Ecommerce/Product/SEO/Marketing) — the same
   "handleReportsProducts calls handleShopifyAnalytics(request, env) directly and reads its JSON"
   pattern already used in this file, just with a synthetic internally-signed session request
   (buildInternalReportRequest) instead of a real browser one, since a cron tick has no browser
   session to reuse.

   Every report's header uses THIS CLIENT'S OWN business name (c.client_name) — never "Leadvyne"
   anywhere in the output. This is the one hard rule the whole renderer is built around: the
   product is white-label from the report recipient's point of view. ── */

const REPORT_TERMINAL_STAGES=new Set(['consultation_booked','human_handover','visit_booked','appt_booked']);
// Mirrors dashboard.html's own isWonLead/isLostLead exactly (see those functions' own comments) —
// kept in sync by hand since this is server-side Worker code and that's client-side dashboard
// code, no shared module between them.
function reportIsWonLead(l){ return l.Stage==='won'||l.Stage==='converted'||(REPORT_TERMINAL_STAGES.has(l.Stage)&&l.Stage!=='human_handover'); }
function reportIsLostLead(l){ return l.Stage==='lost'; }

async function reportFetchAllLeads(env, clientId, fields){
  let rows=[];
  for(let page=1; page<=10; page++){
    const r=await ncFetch(env, `api/v2/tables/${DEFAULT_LEADS_TABLE}/records?where=${encodeURIComponent(`(ClientId,eq,${clientId})`)}&limit=200&offset=${(page-1)*200}&fields=${fields}`);
    if(!r.ok) break;
    const data=await r.json().catch(()=>({}));
    const list=data?.list||[];
    rows=rows.concat(list);
    if(list.length<200) break;
  }
  return rows;
}

async function computeReportOverview(env, c, clientId){
  const leads=await reportFetchAllLeads(env, clientId, 'Stage,Date,DealValue');
  const since30=new Date(); since30.setDate(since30.getDate()-30);
  const newLeads30d=leads.filter(l=>l.Date && new Date(l.Date)>=since30).length;
  const won=leads.filter(reportIsWonLead);
  const lost=leads.filter(reportIsLostLead);
  const revenue=won.reduce((sum,l)=>sum+(Number(l.DealValue)||0),0);
  return {
    total_leads:leads.length, new_leads_30d:newLeads30d, won_count:won.length, lost_count:lost.length,
    conversion_rate: leads.length?Math.round((won.length/leads.length)*1000)/10:0,
    revenue, currency:c.deal_currency||'AED'
  };
}

async function computeReportSales(env, c, clientId){
  const leads=await reportFetchAllLeads(env, clientId, 'Stage,Date,ClosedAt,DealValue');
  const won=leads.filter(reportIsWonLead);
  const lost=leads.filter(reportIsLostLead);
  const revenue=won.reduce((sum,l)=>sum+(Number(l.DealValue)||0),0);
  const byWeek={};
  won.forEach(l=>{
    const d=l.ClosedAt||l.Date; if(!d) return;
    const dt=new Date(d); if(isNaN(dt.getTime())) return;
    const weekStart=new Date(dt); weekStart.setDate(dt.getDate()-dt.getDay());
    const key=weekStart.toISOString().slice(0,10);
    byWeek[key]=(byWeek[key]||0)+(Number(l.DealValue)||0);
  });
  const trend=Object.entries(byWeek).sort((a,b)=>a[0].localeCompare(b[0])).slice(-8).map(([week,total])=>({week,total}));
  return {
    won_count:won.length, lost_count:lost.length, revenue,
    avg_deal_value: won.length?Math.round((revenue/won.length)*100)/100:0,
    currency:c.deal_currency||'AED', trend
  };
}

async function computeReportTeam(env, c, clientId){
  const leads=await reportFetchAllLeads(env, clientId, 'Stage,Owner,DealValue');
  const owner=(c.authentik_email||'').trim();
  const teamEmails=(c.team_emails||'').split(',').map(e=>e.trim()).filter(Boolean);
  let names={}; try{ names=JSON.parse(c.team_names||'{}'); }catch(e){}
  const members=[...new Set([owner, ...teamEmails].filter(Boolean))];
  const rows=members.map(email=>{
    const mine=leads.filter(l=>(l.Owner||'').toLowerCase()===email.toLowerCase());
    const won=mine.filter(reportIsWonLead);
    return {
      email, name: email.toLowerCase()===owner.toLowerCase()?(c.client_name||email):(names[email]||email),
      assigned:mine.length, won:won.length, revenue:won.reduce((s,l)=>s+(Number(l.DealValue)||0),0)
    };
  }).sort((a,b)=>b.revenue-a.revenue);
  return {members:rows, currency:c.deal_currency||'AED'};
}

// SaaS Ops summary — best-effort, only populated for clients with the SaaS Ops module configured
// (saas_config). Mirrors runWeeklyOwnerDigest's own churned/at-risk computation rather than
// inventing a third way to read it.
async function computeReportSaas(env, c, clientId){
  const cfg=await env.DB.prepare(`SELECT nocodb_customers_table_id FROM saas_config WHERE client_id=?`).bind(Number(clientId)).first();
  if(!cfg?.nocodb_customers_table_id) return {enabled:false};
  const customers=await saasFetchAllCustomers(env, cfg.nocodb_customers_table_id);
  const churned=customers.filter(cust=>cust.saas_lifecycle_stage==='churned').length;
  const atRisk=customers.filter(cust=>cust.saas_lifecycle_stage!=='churned' && Number(cust.saas_health_score)<40);
  const healthy=customers.length-churned-atRisk.length;
  return {enabled:true, total_customers:customers.length, churned, at_risk:atRisk.length, healthy};
}

// Mints a fresh internally-signed session (signSession — same primitive a real login uses) and
// builds a synthetic Request so this file's EXISTING session-authed report handlers
// (handleReportsWhatsapp/handleShopifyAnalytics/handleReportsProducts/handleReportsSeo/
// handleMetaAdsSpendTrend) can be called directly, unmodified, from a cron tick — which has no
// real browser session to reuse. Exactly the same "call the handler as a plain function" pattern
// handleReportsProducts already uses on handleShopifyAnalytics, just with a request built here
// instead of a passed-through one.
async function buildInternalReportRequest(env, clientId, path, params){
  const token=await signSession(env, clientId, '');
  const qs=params?('?'+new URLSearchParams(params).toString()):'';
  return new Request(`https://internal.leadvyne${path}${qs}`, {headers:{Authorization:`Bearer ${token}`}});
}

